SELECT 'moj-all-verified-judgments-review-002-chunk-098' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"81094d5a-692d-5052-9873-46573ed6d816","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش بقصد التعاطي -تستر على مصدره - محاولة إدخال احلشيش إلى السجن -بينة غير موصلة -األصل براءة الذمة -عدم ثبوت الدعوى.","document_number":"34183868","case_number":"34154644","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/04/03","year":"1434","subject":"مخدرات -حيازة حشيش بقصد التعاطي -تستر على مصدره - محاولة إدخال احلشيش إلى السجن -بينة غير موصلة -األصل براءة الذمة -عدم ثبوت الدعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34183868:‬تاريخه ‪1434/04/03:‬هـ‬\n                  ‫رقم الدعوى ‪34154644:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34293613‬تاريخه‪1434/08/10:‬ه‬\n\n\n‫مخــدرات‪ -‬حيــازة حشــيش بقصــد التعاطــي ‪ -‬تســتر علــى مصــدره ‪-‬‬\n‫محاولــة إدخــال احلشــيش إلــى الســجن‪ -‬بينــة غيــر موصلــة‪ -‬األصــل‬\n                                 ‫بــراءة الذمــة ‪ -‬عــدم ثبــوت الدعــوى‪.‬‬\n\n\n\n\n                                                       ‫األصل براءة الذمة‪.‬‬\n\n\n\n‫دعــوى املدعــي العــام ضــد املدعــى عليــه تتضمــن طلــب إثبــات إدانتــه‬\n‫بحيــازة احلشــيش املخــدر بقصــد التعاطــي وإدخالــه الســجن والتســتر‬\n‫علــى مصــدره ‪ ،‬واحلكــم عليــه بعقوبــة الســجن طبقــا لنظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة ونظــام الســجن والتوقيــف وعقوبــة تعزيريــة‬\n‫للتســتر ‪ ،‬حيــث أنــه مت االشــتباه بحــركات غيــر طبيعيــة صــدرت مــن‬\n‫الســجني املدعــى عليــه أثنــاء نقلــه مت تفتيــش املنطقــة احمليطــة مبــكان‬\n‫وقوفــه فعثــر فيهــا علــى ثالثــة أصابــع من احلشــيش املخدر وأثبــت التقرير‬\n‫الكيميائــي الشــرعي إيجابيــة العينــة املرســلة للحشــيش املخدر‪،‬كمــا‬\n‫أنكــر أمــام احملكمــة مــا أســنده إليــه املدعي العــام‪ ،‬فطلبت احملكمة‬\n‫مــن املدعــي العــام تقــدمي بيناتــه وقــررت ســماع شــهادة شــهود محضــر‬\n‫القبــض فشــهد أحدهــم بــأن املضبوطــات كانــت مرميــة علــى األرض‬\n\n                                                                                 ‫‪60‬‬\n\f     ‫وتبعــد ثالثــة أمتــار عــن املدعــى عليــه‪ ،‬فقضــت احملكمــة بعــدم ثبــوت‬\n     ‫دعــوى املدعــي العــام جتــاه املدعــى عليــه‪ ،‬وقنــع املدعــى عليــه باحلكــم‬\n     ‫وعــارض املدعــي العــام عليــه‪ ،‬قــررت محكمــة االســتئناف املصادقــة‬\n                                                                     ‫علــى احلكــم‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي‬\n     ‫أنــا ‪ ........‬القاضــي باحملكمــة اجلزائيــة باخلبــر وبنــاء علــى املعاملــة‬\n     ‫احملالــة لنــا مــن فضيلــة رئيــس احملكمــة اجلزائيــة يف محافظــة اخلبــر‬\n     ‫برقــم ‪ 34154644‬وتاريــخ ‪1434/04/03‬ه ـ املقيــدة باحملكمــة‬\n     ‫برقــم ‪ 34823368‬وتاريــخ ‪1434/04/03‬ه ـ ففــي يــوم االثنــن املوافــق‬\n     ‫‪1434/04/08‬ه ـ افتتحــت اجللســة الســاعة ‪ 08 :00‬وفيهــا قــدم املدعــي‬\n     ‫العــام الئحــة دعــوى عامــه ضــد ‪ ........‬ســعودي اجلنســية بالســجل املدنــي‬\n     ‫ا فيهــا إنــه باالطــاع علــى احملضــر املعــد مــن قبــل وحــدة‬\n                                                                     ‫رقــم ‪ ........‬قائـ ً‬\n     ‫األمــن واحلمايــة بشــعبة ســجن اخلبــر تبــن أنــه يف يــوم الثالثــاء املوافــق‬\n     ‫‪1434/2/5‬ه ـ توفــرت معلومــة بــأن الســجني‪ ........‬يف جنــاح ‪ 2‬يعتــزم‬\n     ‫إدخــال كميــة مخــدرات إلــى العنابــر اجلديــدة عنــد نقــل الســجناء وعليــه‬\n     ‫مت اســتدعاء الســجني املشــار إليــه أعــاه أثنــاء نقــل الســجناء ولوحــظ‬\n     ‫عليــه االرتبــاك واحلركــة غيــر طبيعيــة حيــث جلــس ونهــض بشــكل‬\n     ‫ســريع عــدت مــرات وعنــد تفتيشــه وتفتيــش املنطقــة احمليطــة بــه وجــد‬\n     ‫ثــاث أصابــع قــد ألصقــت بالصــق نايلون يشــتبه أن تكون من احلشــيش‬\n     ‫املخــدر بلــغ وزنهــا (‪ )52.5‬جــرام باإلضافــة لعــدد مــن ورق الشــام وقــد مت‬\n     ‫ضبــط الكميــة املشــار إليهــا قبــل دخولهــا العنابــر اجلديــدة‪ ،‬وقــد ورد‬\n\n‫‪61‬‬\n\f‫التقرير الكيماوي الشرعي رقم ( ‪ 954‬ك ش) وتاريخ ‪1434/2/27‬هـ‬\n‫املتضمــن إيجابيــة عينــة القطــع املضبوطــة مــادة احلشــيش املخــدر واملدرج‬\n‫يف اجلــدول األول فئــة (أ) امللحــق بنظــام مكافحــة املخــدرات وبســماع‬\n‫أقــوال املتهــم األوليــة أنكــر عائديــه احلشــيش املضبــوط لــه وذكــر بأنــه‬\n‫يتعاطــى الهرويــن املخــدر منــذ اثنــا عشــر ســنة تقريب ـ ًا وأن آخــر مــرة‬\n‫تعاطــى فيهــا الهرويــن قبــل ســجنه وانتهــى التحقيــق إلــى توجيــه االتهــام‬\n‫لــه‪ ،‬بحيــازة ثالثــة أصابــع بلــغ وزنهــا (‪ )52.5‬اثنــان وخمســون جرام ـ ًا‬\n‫وخمســة مــن عشــرة مــن اجلــرام مــن احلشــيش املخــدر بقصــد التعاطــي‬\n‫وإدخالهــا الســجن والتســتر علــى مصدرهــا وذلــك لألدلــة والقرائــن‬\n‫التاليــة‪ -1 :‬محضــر البــاغ والقبــض والتفتيــش املعــد مــن قبــل وحــدة‬\n‫األمــن واحلمايــة بشــعبة ســجن اخلبــر املشــار إليــه لفــة رقــم (‪ -2)2‬التقريــر‬\n‫الكيمــاوي الشــرعي املشــار إليــه واملرفــق علــى اللفــة رقــم (‪)13‬وحيــث‬\n‫إن مــا أقــدم عليــه املتهــم املذكــور ‪-‬وهــو بكامــل أهليتــه املعتبــرة‬\n‫شــرعا‪ -‬فعــل محــرم ومعاقــب عليــه شــرع ًا ونظام ـ ًا اطلــب اآلتــي‪ :‬أوالً‪:‬‬\n‫وفقــا للفقــرة رقــم (‪ )2‬مــن املــادة رقــم (‪ )3‬مــن نظــام‬\n                                                          ‫إثبــات مــا أســند إليــه ً‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة واملــادة رقــم (‪ )29‬مــن نظــام‬\n‫الســجن والتوقيــف واحلكــم عليــه باالتــي‪ -1:‬بعقوبــة الســجن الــواردة‬\n‫بالفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )41‬مــن النظــام مع مراعــات ما تقضي‬\n‫بــه املــادة (‪ )29‬مــن نظــام الســجن والتوقيــف واحلكــم بالعقوبــة األشــد‬\n‫وفــق مــا ورد بالفقــرة (‪ )2‬مــن املــادة (‪ )62‬مــن نظــام املخــدرات ‪ -2‬بعقوبــة‬\n‫تعزيريــة لقــاء تســتره علــى مصــدر احلشــيش املخــدر ‪ -3‬تشــديد العقوبــة‬\n‫عليــه لكثــرة ســوابقه اســتنادا لبرقيــة صاحــب الســمو امللكــي نائــب‬\n‫وزيــر الداخليــة رقــم (‪ )93958/5/1‬وتاريخ ‪1429/8/23‬هـ هذه دعواي‬\n\n\n                                                                                         ‫‪62‬‬\n\f     ‫وبســؤال املدعــى عليــه عــن الدعــوى أجــاب بقولــه مــا جــاء يف الدعــوى من‬\n     ‫حيازتــي ثــاث أصابــع مــن احلشــيش املخــدر بقصــد التعاطــي وإدخالهــا‬\n     ‫للســجن والتســتر علــى مصدرهــا هــذا غيــر صحيــح والصحيــح أنــه يف‬\n     ‫يــوم احلادثــة مت إخــراج جميــع الســجناء يف جنــاح رقم(‪)2‬وكذلــك بعــض‬\n     ‫الســجناء يف جنــاح رقــم(‪)3‬و(‪)4‬مت إخراجهــم إلــى الســاحة اخلارجيــة وأنــا‬\n     ‫كنــت يف اجلنــاح رقم(‪)2‬وذلــك ألجــل تفتيــش الســجناء واحــد ًا واحــد ًا‬\n     ‫ثــم نقلنــا إلــى عنابــر جديــدة وقــد مت تفتيــش الســجناء وكنــت أنــا آخــر‬\n     ‫واحد مت تفتيشــه ولم يجدوا معي أي شــيء من املمنوعات عند تفتيشــي‬\n     ‫كمــا لــم يعثــروا مبفرشــي الــذي كنــت أحملــه معــي علــى أي شــيء مــن‬\n     ‫املمنوعــات وبعــد حتركــي ألجــل االنتقــال للعنبــر اجلديــد ذكــر أحــد‬\n     ‫العســاكر أنــه وجــد أصابــع حشــيش مخــدر يف املمــر املجــاور للســاحة‬\n     ‫وهــذا احلشــيش ليــس لــي عالقــة بــه فهــو ال يعــود لــي وال أعلــم ملــن يعــود‬\n     ‫وقــد يكــون أحــد الســجناء قــام برمــي هــذا احلشــيش املخــدر قبــل مــروره‬\n     ‫عنــد التفتيــش علمـ ًا بأنــي موقــوف يف قضيــة اســتعمال هيرويــن هكــذا‬\n     ‫أجــاب وبســؤال املدعــي العــام البينــة علــى دعــواه قــال بينتــي مــا ذكــرت‬\n     ‫فأقفلــت اجللســة عنــد الســاعة الثامنــة والنصــف لطلــب معــدي محضــر‬\n     ‫القبــض والتفتيــش وصلــى اهلل وســلم علــى نبينــا محمــد احلمــد هلل وحــده‬\n     ‫وبعــد ثــم إنــه يف هــذا اليــوم الثالثــاء ‪1434/4/9‬ه ـ الســاعة العاشــرة‬\n     ‫إال ربــع افتتحــت اجللســة بحضــور املدعــى عليــه كمــا حضــر الشــاهد‬\n     ‫‪ ........‬ســعودي بالســجل املدنــي رقــم (‪ )........‬وهــو أحــد معــدي محضــر‬\n     ‫القبــض والتفتيــش وبســؤاله عمــا لديــه مــن شــهادة قــال إنــي أعمــل‬\n     ‫عســكري يف ســجن اخلبــر يف قســم مكافحــة املخــدرات وأشــهد هلل‬\n     ‫أنــه يف تاريــخ ‪1434/2/23‬ه ـ مت إخــراج ســجناء اجلنــاح رقــم (‪ )2‬ورقــم‬\n\n\n‫‪63‬‬\n\f‫(‪ )3‬إلــى ســاحة الســجن ألجــل تفتيشــهم ثــم نقلهــم مــن العنابــر القدميــة‬\n‫إلــى العنابــر اجلديــدة وقــد قمــت أنــا بتفتيــش املدعــى عليــه وكان مــن‬\n‫أواخــر الســجناء الذيــن مت تفتيشــهم وأثنــاء تفتيشــي لــه وجــدت ثــاث‬\n‫أصابــع حشــيش مخــدر مــع ورق شــام كانــت مرميــة علــى األرض علــى‬\n‫بعــد ثــاث أمتــار تقريب ـ ًا مــن املدعــى عليــه لكنــي ال أعلــم هــل مــن‬\n‫قــام برميهــا املدعــى عليــه أم شــخص آخــر مــن الســجناء املوجوديــن يف‬\n‫الســاحة وعنــد ذلــك قمــت باســتدعاء زمالئــي هــذا مــا لــدي مــن شــهادة‬\n‫فاحلشــيش املخــدر أنــا مــن وجــده ولــم يكــن بحــوزة املدعــى عليــه إمنــا‬\n‫كان مرمي ـ ًا علــى األرض علــى بعــد ثالثــة أمتــار مــن املدعــى عليــه‬\n‫وأمــا زميلــي فقــد حضــرا بعــد أن عثــرت علــى احلشــيش املخــدر هكــذا‬\n‫شــهد وبعــرض الشــاهد وشــهادته علــى املدعــى عليــه قــال الشــاهد رجــل‬\n‫مســتقيم وشــهادته صحيحــة فاحلشــيش املخــدر لــم يكــن بحوزتــي وإمنــا‬\n‫كان مرميـ ًا علــى األرض علــى بعــد ثالثــة أمتــار عنــي وليــس عائــد ًا لــي‬\n‫وال أعلــم ملــن يعــود وقــد ذكــر الشــاهد بأنــه لــم يشــاهدني أرمــي هــذا‬\n‫احلشــيش هكــذا قــرر بعــد ذلــك جــرى الرجــوع إلــى اللفــة رقــم (‪)13‬‬\n‫وتضمنــت التقريــر الكيمــاوي الشــرعي وهــو كمــا ذكــر املدعــي‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى اإلجابــة وحيــث أنكــر‬ ‫العــام يف دعــواه فبنـ ً‬\n‫املدعــى عليــه مــا نســب إليــه وحيــث إنــه ال بينــة علــى الدعــوى وقــد حضــر‬\n‫الشــاهد وأفــاد بأنــه هــو مــن وجــد قطعــة احلشــيش املخــدر ولــم تكــن‬\n‫بحــوزة املدعــى عليــه إمنــا كانــت مرميــة عنــه علــى بعــد ثالثــة أمتــار وال‬\n‫يعلــم الشــاهد مــن قــام برمــي هــذا احلشــيش املخــدر كمــا أفــاد بــأن‬\n‫زميليــه حضــرا بعــد أن وجــد هــو قطعــة احلشــيش املخــدر وحيــث إن‬\n‫األصــل بــراءة الذمــة والســاحة التــي وجــد بهــا احلشــيش املخــدر كان‬\n\n\n                                                                                        ‫‪64‬‬\n\f     ‫يتواجــد بهــا مجموعــة مــن الســجناء ألجــل تفتيشــهم لــذا فقــد حكمــت‬\n     ‫بعــدم ثبــوت دعــوى املدعــي العــام جتــاه املدعــى عليــه ‪ .......‬مــن حيــازة‬\n     ‫احلشــيش املخــدر وإدخالــه الســجن والتســتر علــى مصــدره وبعــرض‬\n     ‫احلكــم قنــع املدعــى عليــه ولــم يقنــع املدعــي العــام مكتفيـ ًا مبــا قــدم يف‬\n     ‫الئحــة الدعــوى وأقفلــت اجللســة الســاعة العاشــرة والنصــف وصلــى اهلل‬\n                                                            ‫وســلم علــى نبينــا محمــد‪.‬‬\n     ‫احلمــدهلل وحــده وبعــد ‪ ...‬فقــد أطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n     ‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة‬\n     ‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة اخلبــر برقــم‬\n     ‫‪ 34/823368‬وتاريــخ ‪1434/4/13‬ه ـ املقيــدة لــدى احملكمــة برقــم‬\n     ‫‪ 34/929321‬وتاريــخ ‪1434/4/15‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n     ‫فضيلــة القاضــي باحملكمــة الشــيخ‪ .......‬املســجل برقــم ‪34183868‬‬\n     ‫وتاريــخ ‪1434/4/9‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد ‪ ....... /‬يف‬\n     ‫قضيــة مخــدرات وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون‬\n     ‫ومفصــل فيــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه واوراق املعاملــة قررنــا‬\n     ‫املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/5/14‬ه ـ ‪.‬‬\n\n\n\n\n‫‪65‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":60,"source_page_end":65,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c49372c8a6a1b43bf29a629de148453b521cea939de2a3d6a15bee183e1fc3f3","normalized_text_hash":"5511a159c9fc65f724d490cb2531d351a1e4d5e9b6b8697cda2a5b2937d36205","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p60-34183868"},{"id":"248ab98a-9416-5a89-bc96-bc3bf8fe5a8d","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حبوب محظورة بقصد التعاطي -إدانة -نزول عن احلد األدنى للعقوبة.","document_number":"34196715","case_number":"34161373","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":"الدائرة اجلزائية الرابعة رقم 34246641يف 1434/6/20ه املتضمن","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/04/23","year":"1434","subject":"مخدرات -حيازة حبوب محظورة بقصد التعاطي -إدانة -نزول عن احلد األدنى للعقوبة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34196715:‬تاريخه ‪1434/04/23:‬هـ‬\n                   ‫رقم الدعوى ‪34161373:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34293613‬تاريخه‪1434/08/10:‬هـ‬\n\n\n‫مخــدرات‪ -‬حيــازة حبــوب محظــورة بقصــد التعاطــي‪ -‬إدانــة‪ -‬نــزول عــن‬\n                                                 ‫احلــد األدنــى للعقوبــة‪.‬‬\n\n\n\n\n‫املــواد (‪ )3‬و(‪ )41‬و(‪ )56‬و(‪ )60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                              ‫العقليــة‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بإدانتــه بحيازة حبــوب الزنكس‬\n‫احملظــورة بقصــد التعاطــي ‪ ،‬واحلكــم عليــه بعقوبــة الســجن واملنــع مــن‬\n‫الســفر طبقــا لنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ ،‬حيــث إنــه‬\n‫مت تفتيــش املدعــى عليــه بعــد اســتيقاف الســيارة التــي كان يركبهــا‬\n‫فعثــر بحوزتــه علــى حبــوب يشــتبه أن تكــون محظــورة‪ ،‬أثبــت التقريــر‬\n‫الكيميائــي الشــرعي إيجابيــة العينــة املرســلة ملركــب البــرازوالم‬\n‫احملظــور‪ ،‬أقــر حتقيقـ ًا بحيازتــه للحبــوب املضبوطــة بقصــد التعاطــي‪،‬‬\n‫وأنكــر أمــام احملكمــة مــا أســنده إليــه املدعــي العــام ودفــع بــأن احلبــة‬\n‫عائــدة ألخيــه املريــض نفســيا وأنــه يحوزهــا ملنعــه مــن اســتخدامها‬\n‫بطريقــة خاطئــة‪ ،‬وطلبــت احملكمــة مــن املدعــى عليــه تقــدمي إثبــات علــى‬\n‫مــا دفــع بــه فعجــز عــن ذلــك‪ ،‬فقضــت احملكمــة بإدانــة املدعــى عليــه مبا‬\n\n                                                                                     ‫‪66‬‬\n\f     ‫نســب إليــه وقــررت ســجنه ملــدة شــهر ومنعــه مــن الســفر خــارج اململكــة‬\n     ‫ملــدة ســنتني‪ ،‬قنــع املدعــى عليــه باحلكــم وعــارض املدعــي العــام عليــه‬\n                        ‫وقــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة اجلزائيــة‬\n     ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n     ‫اجلزائيــة بالريــاض برقــم ‪ 34161373‬وتاريــخ ‪1434/04/08‬ه ـ املقيــدة‬\n     ‫باحملكمــة برقــم ‪ 34858791‬وتاريــخ ‪1434/04/08‬ه ـ ففــي يــوم‬\n     ‫األربعــاء املوافق‪1434/04/17‬ه ـ افتتحــت اجللســة الســاعة ‪01 :00‬‬\n     ‫وفيهــا حضــر املدعــي العــام وادعــى علــى ‪ ........‬ســعودي اجلنســية بقولــه‬\n     ‫انــه بتاريــخ ‪1434/2/18‬ه ـ مت القبــض علــى املذكــور مــن قبــل إحــدى‬\n     ‫فــرق دوريــات األمــن مبدينــة الريــاض حيــث شــاهدت ســيارة مــن نــوع‬\n     ‫(‪ )........‬حتمــل اللوحــة رقــم(‪ ).....‬بقيــادة املدعــو‪ ........‬ويرافقــه املذكــور‬\n     ‫وباالشــتباه بهــا مت اســتيقافها ولوحــظ انبعــاث رائحــة منهــا يشــتبه أن‬\n     ‫تكــون حشــيش مخــدر وبتفتيــش املذكــور عثــر بحوزتــه علــى قصديــرة‬\n     ‫بداخلهــا (‪ )4‬أربــع حبــات مكتــوب عليهــا (زينكــس) يشــتبه أن‬\n     ‫تكــون محظــورة وقــد أثبــت التقريــر الكيميائــي الشــرعي الصــادر‬\n     ‫مــن مركــز مراقبــة الســموم والكيميــاء الطبيــة الشــرعية بالريــاض‬\n     ‫املرفــق رقــم (‪ )........‬لعــام ‪1434‬ه ـ احتــواء احلبــوب املضبوطــة ملركــب‬\n     ‫البــرازوالم وهــو مــن املــواد املهدئــة واملدرجــة باجلــدول رقم(‪)2‬فئــة (د)‬\n     ‫امللحــق بــذات النظــام‪ .‬وبســماع أقــوال املذكــور أقــر بحيــازة مــا ضبــط‬\n     ‫مــن حبــوب محظــورة بقصــد التعاطــي وذكــر بأنــه حصــل عليهــا مــن‬\n\n‫‪67‬‬\n\f‫أخيــه‪ .‬وباســتجوابه اعتــرف بحيــازة مــا ضبــط مــن حبــوب محظــورة‬\n‫بقصــد التعاطــي وأنــه حصــل عليهــا مــن أخيــه املريــض نفســي ًا دون‬\n‫علمــه وقــد أســفرت إجــراءات التحقيــق عــن توجيــه االتهــام إلــى‪........‬‬\n‫بحيــازة (‪ )4‬أربــع حبــات مــن حبــوب البــرازوالم املهدئــة احملظــورة بقصــد‬\n‫التعاطــي املجــرم مبوجــب املــادة (الثالثــة) مــن نظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ‬\n‫‪1426/7/8‬هـ‪ .‬وذلك لألدلة والقرائن التالية‪ -1 :‬مــا تضمنــه اعترافــه‬\n‫يف محضــر ســماع األقــوال األوليــة املنــوه عنــه املــدون علــى الصفحــة‬\n‫رقــم(‪ )4‬املرفــق لفــة رقــم (‪ -2 .)1‬مــا تضمنــه محضــر القبــض املنــوه‬\n‫عنــه املرفــق لفــة رقــم (‪ -3 )2‬مــا تضمنــه التقريــر الكيميائــي الشــرعي‬\n‫املنــوه عنــه املرفــق لفــة رقــم (‪ )24‬وحيــث أن مــا أقــدم عليــه املذكــور‬\n‫فعــل محــرم ومعاقــب عليــه شــرعا ونظامـ ًا لــذا أطلــب إثبــات إدانتــه مبــا‬\n‫أســند إليــه واحلكــم عليــه بالتالــي‪ )1 :‬بالعقوبــة الــواردة بالفقــرة (‪ )1‬مــن‬\n‫املــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة لقــاء مــا‬\n‫أســند إليــه‪ )2 .‬منعــه مــن الســفر إلــى خــارج اململكــة بعــد تنفيــذ عقوبــة‬\n‫ســجنه وفقـ ًا للفقــرة (األولــى) مــن املــادة (‪ )56‬مــن ن ــفس النظــام املشــار‬\n‫إليــه هــذه دعــواي وبعــرض الدعــوى علــى املدعــى عليــه أجــاب مــا ذكــره‬\n‫املدعــي العــام صحيــح مــن ناحيــة حيازتــي (‪ )4‬ألربــع حبــات مــن حبــوب‬\n‫البــرازوالم املهدئــة وهــي ال تعــود لــي وإمنــا ألخــي املريــض النفســي كانت‬\n‫معــي لكــي ال يســتخدمها أخــي املريــض بطريقــة خاطئــة هكــذا أجــاب‬\n‫وبســؤاله هــل مت صــرف احلبــوب املذكــورة مــن جهــة مختصــة فقــال نعــم‬\n‫صرفــت لــه مــن مستشــفى وأطلــب إمهالــي إلحضــار مــا يثبــت ذلــك ثــم‬\n‫رفعــت اجللســة لذلــك ويف يــوم الثالثــاء املوافق‪1434/04/23‬ه ـ افتتحــت‬\n\n\n                                                                                      ‫‪68‬‬\n\f     ‫اجللسة الساعة ‪ 12.45‬وفيها حضر املدعي العام واملدعى عليه وبسؤال‬\n     ‫املدعــى عليــه عــن بينتــه فقــال ال بينــة لــدي علــى أن أخــي قــد صــرف لــه‬\n     ‫العــاج مــن قبــل مستشــفى حكومــي وبســؤال املدعــى عليــه عمــا ورد يف‬\n     ‫إقــراره بأنــه كان ينــوي تعاطــي احلبــوب فأجــاب بأنــي قلــت ذلــك خوفــا‬\n     ‫منهــم فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث صــادق املدعــى‬\n     ‫عليــه علــى أنــه أقــر لــدى جهــات التحقيــق أنــه كان ينــوي تعاطــي احلبــوب‬\n     ‫احملظــورة وملــا نــص عليــه التقريــر الكيميائــي املرفــق ومــا نصــت عليــه‬\n     ‫املــادة رقــم (‪ )56-41‬مــن نظــام مكافحــة املخــدرات لذلــك كلــه‬\n     ‫فقــد ثبــت لــدي إدانــة املدعــى عليــه بحيــازة (‪ )4‬أربــع حبــات مــن حبــوب‬\n     ‫البــرازوالم املهدئــة احملظــورة بقصــد التعاطــي املجــرم مبوجــب املــادة‬\n     ‫(الثالثــة) مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر‬\n     ‫باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426 / 7 / 8‬ه ـ ونظــرا لعــدم‬\n     ‫وجــود ســوابق مســجلة عليــه ولقلــة الكميــة املضبوطــة معــه وملــا نصــت‬\n     ‫عليــه املــادة رقــم (‪ )60‬مــن نظــام مكافحــة املخــدرات لذلــك كلــه فقــد‬\n     ‫حكمــت بســجنه ملــدة شــهر ومنعــه مــن الســفر خــارج اململكــة ملــدة‬\n     ‫ســنتني بعــد انتهــاء محكوميتــه وبعــرض ذلــك علــى املدعــي العــام قــرر‬\n     ‫عــدم القناعــة وطلــب متييــز احلكــم بــدون الئحــة وقــرر املدعــى عليــه‬\n     ‫القناعــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n     ‫وصحبــه وســلم‪ .‬حــرر يف ‪ 1434/04/23‬ه ـ احلمــد هلل وحــده وبعــد ففــي‬\n     ‫يــوم الثالثــاء املوافــق‪ 1434/07/18‬ه ـ افتتحــت اجللســة الســاعة ‪2.00‬‬\n     ‫وقــد عــادت املعاملــة مــن محكمــة االســتئناف بالريــاض وبرفقهــا قــرار‬\n     ‫الدائــرة اجلزائيــة الرابعــة رقــم ‪ 34246641‬يف ‪1434/6/20‬ه ـ املتضمــن‬\n     ‫أنــه لوحــظ مــا يلــي ‪ -1‬لــم يثبــت فضيلتــه اإلدانــة مــن عدمهــا ‪ -2‬لــم يبــن‬\n\n\n‫‪69‬‬\n\f‫بدايــة ســجن املدعــى عليــه ومضمــون التقريــر الكيميائــي ‪ -3‬لــم يوقــع‬\n‫الكاتــب علــى ختــم طبــق األصــل يف صــورة الضبــط أ‪.‬ه ـ عليــه أجيــب‬\n‫أصحــاب الفضيلــة أنــه مت إثبــات إدانــة املدعــى عليــه مبــا أســند إليــه‬\n‫قبــل احلكــم عليــه ‪ ،‬وباإلمــكان الرجــوع إلــى احلكــم والتحقــق مــن‬\n‫ذلــك ‪ ،‬وأمــا بدايــة الســجن فيســجن بعــد حســم مــدة إيقافــه بســبب هــذه‬\n‫القضيــة ومضمــون التقريــر الكيميائــي الشــرعي الصــادر مــن مركــز‬\n‫مراقبــة الســموم والكيميــاء الطبيــة الشــرعية بالريــاض املرفــق رقــم‬\n‫(‪ )........‬لعــام ‪1434‬ه ـ هــو احتــواء احلبــوب املضبوطــة ملركــب البــرازوالم‬\n‫وهــو مــن املــواد املهدئــة واملدرجــة باجلــدول رقم(‪)2‬فئــة (د) امللحــق بــذات‬\n‫النظــام‪ ،‬وقــد مت اتخــاذ الــازم حيــال املالحظــة الثالثــة وبــاهلل التوفيــق‪،‬‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف‬\n                                                               ‫‪1434/07/18‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدئــرة اجلزائيــة‬\n‫الرابعــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن‬\n‫فضيلــة رئيــس احملكمــة اجلزائيــة بالريــاض برقــم ‪341583501‬‬\n‫وتاريــخ ‪1434/7/26‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة‬\n‫القاضــي باحملكمــة الشــيخ ‪ ... /‬املســجل برقــم ‪ 34196715‬وتاريــخ‬\n‫‪1434/4/23‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد ‪ /‬املدعــى عليــه‬\n‫التهامــه بقضيــة مخــدرات علــى النحــو املوضــح بالقــرار املتضمــن‬\n‫حكــم فضيلتــه مبــا هــو مــدون بــه وحيــث ســبق دراســة القــرار‬\n‫وصــورة ضبطــه وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلته‬\n‫القاضــي وأحلقــه بالقــرار وصــورة ضبطــه وأوراق املعاملــة وباالطــاع‬\n‫علــى مــا أجــاب بــه فضيلتــه القاضــي أحلقــه بالقــرار وصــورة ضبطــه‬\n\n\n                                                                                     ‫‪70‬‬\n\f     ‫بنــاء علــى قرارنــا رقــم ‪ 34246641‬وتاريــخ ‪1434/6/20‬ه ـ قــررت‬\n     ‫الدائــرة باألكثريــة املصادقــة علــى احلكــم بعــد اإلجــراء األخيــر واهلل‬\n              ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪71‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":66,"source_page_end":71,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"dd20fbae8253f2199b9d70a2e140c9e11e41b7b13b30c7824222f50fc2fe53c5","normalized_text_hash":"7f28bf9188eb7d20fd728bd4788a72454ee0828f27541cc8926f2e61c6f7cc38","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p66-34196715"},{"id":"2d7110ef-fc32-5835-b146-5480dcc4c0e0","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حبة من احلبوب احملظورة بقصد التعاطي - تعاطي احلبوب احملظورة -قيادة السيارة حتت تأثير احلبوب احملظورة -عقوبة عائدة للجهة املختصة .","document_number":"34220034","case_number":"34162926","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/05/22","year":"1434","subject":"مخدرات -حيازة حبة من احلبوب احملظورة بقصد التعاطي - تعاطي احلبوب احملظورة -قيادة السيارة حتت تأثير احلبوب احملظورة -عقوبة عائدة للجهة املختصة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34220034 :‬تاريخه ‪1434/05/22 :‬هـ‬\n                    ‫رقم الدعوى ‪34162926:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34252528‬تاريخه‪1434/6/25 :‬هـ‬\n\n\n ‫مخــدرات ‪ -‬حيــازة حبــة مــن احلبــوب احملظــورة بقصــد التعاطــي ‪-‬‬\n ‫تعاطــي احلبــوب احملظــورة ‪ -‬قيــادة الســيارة حتــت تأثيــر احلبــوب‬\n                       ‫احملظــورة ‪ -‬عقوبــة عائــدة للجهــة املختصــة ‪.‬‬\n\n\n\n\n                                     ‫‪1 .1‬اإلقرار حجة شرعية على املقر‬\n        ‫‪2 .2‬املواد ‪ 41‬و ‪ 60‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n\n ‫الئحــة الدعــوى ضــد املدعــى عليــة بحيــازة حبــة مــن احلبــوب احملظــورة‬\n ‫بقصــد التعاطــي وتعاطيــه احلبــوب احملظــورة وقيــادة الســيارة حتــت‬\n ‫تأثيــر احلبــوب احملظــورة‪ ،‬وطلــب املدعــي العــام إثبــات مــا اســند إليــه‬\n ‫واحلكــم عليــه بعقوبــة الســجن واملنــع مــن الســفر واثبــات إدانتــه بقيــادة‬\n ‫الســيارة وتــرك عقابــه للجهــة املختصــة‪ ،‬مت القبــض علــى املدعــى عليــه‬\n ‫مــن قبــل مكافحــة املخــدرات بعــد االشــتباه بــه واســتيقافه وبتفتيشــه‬\n ‫عثــر معــه علــى حبــة واحــدة حتمــل عالمــة الكبتاجــون‪ ،‬إقــرار املدعــى‬\n ‫عليــة بالدعوى‪،‬تعزيــر املدعــى عليــة بالســجن واجللــد واملنــع مــن الســفر‪،‬‬\n ‫تــرك مجازاتــه لقــاء قيادتــه للســيارة حتــت تأثيــر احلبــوب احملظــورة‬\n           ‫للجهــة املختصــة‪ ،‬تصديــق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n                                                                                     ‫‪72‬‬\n\f     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬القاضــي يف احملكمــة‬\n     ‫اجلزائيــة باالحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n                                                                         ‫ّ‬\n     ‫رئيــس احملكمــة اجلزائيــة يف محافظــة االحســاء برقــم ‪34162926‬‬\n     ‫وتاريــخ ‪1434/04/09‬ه ـ املقيــدة باحملكمــة برقــم ‪34866975‬‬\n     ‫وتاريــخ ‪1434/04/09‬ه ـ حضــر املدعــي العــام ‪ ..........‬وادعــى ضــد‬\n     ‫‪ ..........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )..........‬قائــا‬\n     ‫إنــه باالطــاع علــى محضــر القبــض املعــد مــن قبــل رجــال مكافحــة‬\n     ‫املخــدرات مبحافظــة بقيــق بتاريــخ ‪1433/12/5‬ه ـ وأثنــاء مراقبــة إحدى‬\n     ‫محطــات الوقــود التــي يتــردد عليهــا أشــخاص مشــبوهون مت االشــتباه يف‬\n     ‫صاحــب ســيارة مــن نــوع ‪ .......‬بيضــاء اللــون حتمــل اللوحــة رقــم (‪)..........‬‬\n     ‫يركبهــا شــخص واحــد تظهــر عليــه عالمــات االرتبــاك وباالنتقــال إليــه‬\n     ‫للتأكــد منــه اتضــح أنــه املدعــى عليــه وبتفتيشــه شــخصي ًا ضبــط بجيــب‬\n     ‫ثوبــه األعلــى علــى حبــة بيضــاء اللــون حتمــل عالمــة الكبتاجــون املخــدر‬\n     ‫والتــي يشــتبه أن تكــون مــن احلبــوب احملظــورة فتــم اصطحابــه ومــا‬\n     ‫ضبــط بحيازتــه وســيارته إلــى مقــر إدارة املكافحــة وتســليمه لضابــط‬\n     ‫اخلفــر وبتحريــز املضبــوط بتاريــخ ‪1433/12/5‬ه ـ اتضــح أنهــا عبــارة عــن‬\n     ‫حبــة واحــدة أعطيــت الرقــم الســري (‪33/86‬س) ومت إرســالها للمركــز‬\n     ‫اإلقليمــي لتحليلهــا فــورد التقريــر الكيمــاوي الشــرعي رقــم (‪)..........‬‬\n     ‫بتاريخ‪1433/12/13‬ه ـ املتضمــن ثبــوت إيجابيــة احلبــة املضبوطــة ملــادة‬\n     ‫االمفيتامــن احملظــورة وبأخــذ عينــة مــن ســوائل املدعــى عليــه وبعثها إلى‬\n     ‫مركــز اإلقليمــي ملراقبــة الســموم قســم الكيميــاء الشــرعية لفحصهــا‬\n\n‫‪73‬‬\n\f‫ورد تقريــر الســموم الشــرعية رقــم(‪ )..........‬وتاريــخ ‪1433/12/12‬ه ـ‬\n‫متضمن ـ ًا إيجابيــة عينــة البــول املرســلة ملركــب االمفيتامــن احملظــور‬\n‫وبضبــط أقــوال املدعــى عليــه أقــر بصحــة واقعــة القبــض عليــه وأقــر‬\n‫بحيازة حبة واحدة من حبوب الكبتاجون احملظورة بقصد االســتعمال‬\n‫الشــخصي كمــا أضــاف بأنــه حصــل علــى حبتــن من احلبــوب احملظورة‬\n‫مــن شــخص ال يعرفــه أهداهــا لــه فقــام بالتعاطــي بحبــة واحــدة واألخــرى‬\n‫مت ضبــط بحوزتــه كمــا أضــاف بأنــه قــام بقيــادة الســيارة بعــد تعاطيــه‬\n‫احلبــة األولــى وأفــاد بأنــه تعاطــى حبــة واحــدة مــن احلبــوب احملظــورة قبــل‬\n‫أكثــر مــن ســنة تقريبـ ًا وأيضــا قبــل شــهر مــن تاريــخ القبــض عليــه وقــد‬\n‫أســفر التحقيــق عــن توجيــه االتهــام لــه بحيــازة حبــة واحــدة مــن حبــوب‬\n‫اإلمفيتامــن احملظــورة بقصــد االســتعمال وتعاطيــه لنوعهــا وقيادتــه‬\n‫للســيارة حتــت تأثيرهــا وذلــك لألدلــة والقرائــن التاليــة‪1 :‬ـ محضــر‬\n‫اعترافــه املنــوه عنــه واملــدون علــى الصفحــة رقــم (‪ )1‬مــن دفتــر التحقيــق‬\n‫لفــة رقــم(‪2)12‬ـ إقــرار املدعــى عليــه املنــوه عنــه واملــدون علــى الصفحــة‬\n‫رقــم(‪ )3‬مــن ملــف ضبــط إجــراءات قضيــة املخــدرات املرفــق لفــة رقــم(‪)2‬‬\n‫‪3‬ـ محضــر القبــض املنــوه عنــه واملــدون علــى الصفحــة رقــم (‪ )2‬مــن ملــف‬\n‫ضبــط إجــراءات قضيــة املخــدرات املرفــق لفــة رقــم (‪4 )1‬ـ تقريــري‬\n‫الكيمــاوي الشــرعي والســموم الشــرعية املنــوه عنهمــا املرفــق علــى‬\n‫اللفتــن رقــم (‪ )20/18‬وبالبحــث عمــا إذا كان لديــه ســوابق اتضــح‬\n‫عــدم وجــود ســوابق مســجلة ضــده وحيــث إن مــا أقــدم عليــه املدعــى عليه‬\n‫وهــو بكامــل أهليتــه املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n‫ونظامـ ًا لــذا أطلــب إثبــات إدانتــه بحيــازة مركــب اإلمفيتامــن احملظــور‬\n‫وتعاطيــه لنوعهــا ‪ ،‬وفق ـ ًا للفقــرة رقــم (‪)2‬مــن املــادة رقــم (‪)3‬مــن نظــام‬\n\n\n                                                                                       ‫‪74‬‬\n\f     ‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم‬\n     ‫(م‪ )39/‬وتاريخ‪1426/7/8‬ه ـ واحلكــم عليــه باآلتــي ‪ .1:‬عقوبــة الســجن‬\n     ‫الــواردة بالفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )41‬مــن النظــام املشــار إليــه‬\n     ‫لقــاء حيازتــه حبــة واحــدة مــن حبــوب االمفيتامــن احملظــورة بقصــد‬\n     ‫االســتعمال وتعاطيــه لنوعها‪.2‬منعــه مــن الســفر وفــق الفقــرة رقم(‪)1‬مــن‬\n     ‫املــادة رقم(‪)56‬مــن ذات النظــام‪3‬ـ ‪.‬إثبــات إدانتــه بقيــادة الســيارة حتــت‬\n     ‫تأثيــر مركــب االمفيتامــن املخــدر وفق ـ ًا للفقــرة رقــم (‪ )8‬مــن اجلــدول‬\n     ‫رقــم (‪ )1‬امللحــق بنظــام املــرور الصــادر باملرســوم امللكــي رقــم (م‪)85/‬‬\n     ‫وتاريــخ ‪1426/10/26‬هـ ـ وإفهامــه بــأن عقوبتــه الــواردة بالفقرة رقم (‪)1‬‬\n     ‫مــن املــادة رقــم (‪ )68‬و املــادة رقــم (‪ )76‬مــن النظــام املشــار إليــه آنف ـ ًا ‪،‬‬\n     ‫تقررهــا اجلهــة املختصــة وفقـ ًا للفقــرة رقــم (‪ )2‬مــن قــرار مجلــس الــوزراء‬\n     ‫رقــم (‪ )315‬يف ‪1428/10/24‬ه ـ وبعــرض تلــك الدعــوى علــى املدعــى‬\n     ‫ا أصــادق علــى مــا ذكــره املدعــي العــام مــن حيازتــي‬       ‫عليــه أجــاب قائ ـ ً‬\n     ‫حبــة مــن حبــوب اإلمفيتامــن املنبــه احملظــور وقصــدي مــن حيازتهــا‬\n     ‫االســتعمال كمــا أصــادق علــى اســتعمالي لهــا ولقيادتــي للســيارة وانــا‬\n     ‫حتــت تأثيــره وأنــا نــادم علــى ذلــك لــذا وبعــد ســماع الدعــوى واإلجابــة‬\n     ‫وتصفــح أوراق املعاملــة وحيــث طلــب املدعــي العــام إثبــات إدانــة املدعــى‬\n     ‫عليــه حليازتــة حبــة مــن احلبــوب احملظــورة بقصــد االســتعمال ومجازاتــه‬\n     ‫لقــاء ذلــك والســتعماله لهــا ولقيادتــه الســيارة وهــو حتــت تأثيــره وإن‬\n     ‫املدعــى عليــه قــد أقــر بذلــك وإن اإلقــرار حجــة شــرعية علــى املقــر وإن‬\n     ‫مــا أقــدم عليــه وإن الكميــة التــي مت ضبطهــا مــع املدعــى عليــه قليلــه‬\n     ‫وانهــا لالســتعمال الشــخصي وملــا ظهــر لنــا مــن ندمــه وانــه ال ســوابق‬\n     ‫عليــه وهــذه أســباب مخففــة للعقوبــة وان املــادة (‪ )60‬مــن نظام املخدرات‬\n\n\n‫‪75‬‬\n\f‫جتيــز للقاضــي النــزول عــن احلــد األدنــى مــن العقوبــة الــواردة يف بعــض‬\n‫مــواد ذلــك النظــام ومنهــا املــادة (‪ )41‬إذا وجــد أســباب معتبــره كمــا هــو‬\n‫احلــال هنــا لــذا فقــد تقــرر مــا يلــي أو ًال ثبــوت إدانــة املدعــى عليــه ‪..........‬‬\n‫حليازتــه حبــة مــن احلبــوب احملظــورة واحملتويــة علــى مركــب اإلمفيتامــن‬\n‫وذلــك حســبما أوضحــه التقريــر الكيمــاوي الشــرعي رقــم (‪)..........‬‬\n‫والقصــد مــن حيازتهــا االســتعمال ومجازاتــه لقــاء ذلــك بســجنه شــهرين‬\n‫تبــدأ مــن تاريــخ إيقافــه بســبب هــذه القضيــة ثانيـ ًا تعزيــره لقــاء اســتعماله‬\n‫للحبــوب احملظــورة بجلــده ســبعني جلــده علــى فترتــن متســاويتني بينهمــا‬\n‫اســبوعا ثالثــا منعــه مــن الســفر ملــدة ســنتني تبــدأ بعــد انتهــاء محكوميته‬\n‫رابعــا ثبــوت ادانتــه لقيادتــه للســيارة وهــو حتــت تأثيــر احلبــوب احملظــورة‬\n‫وتركــت مجازاتــه للجهــة املختصــة وبذلــك كلــه حكمــت وبعرضــه‬\n‫قــرر املدعــي العــام عــدم قناعتــه بــه وطلــب رفعــه حملكمــة االســتئناف‬\n‫مكتفيــا مبــا جــاء يف دعــواه عــن تقــدمي الئحــه اعتراضيــه امــا املدعــى‬\n‫عليــه فقــرر قناعتــه بــه وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد‬\n                      ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/05/22‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة االحســاء املكلــف‬\n‫الشــيخ‪ ..........‬برقــم ‪ 341194677‬وتاريــخ ‪1434/5/28‬ه ـ املقيــدة‬\n‫لــدى احملكمــة برقــم ‪ 34/1349225‬وتاريــخ ‪1434/6/5‬ه ـ املرفــق‬\n‫بهــا القــرار الصــادر مــن فضيلتــه املســجل برقــم ‪ 34220034‬وتاريــخ‬\n‫‪1434/5/22‬ه ـ اخلــاص بدعــوى‪ /‬املدعــي العــام ضــد‪ ........../‬يف قضيــة‬\n‫مخــدرات وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n\n\n                                                                                               ‫‪76‬‬\n\f     ‫فيــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة‬\n     ‫علــى احلكــم‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                         ‫وصحبــه وســلم حرريف‪1434/6/25‬ه ـ‬\n\n\n\n\n‫‪77‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":72,"source_page_end":77,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2655354e74c8fd512004f0bd6187282fbc6f71f8abfee4d32c2262f1d07e0da6","normalized_text_hash":"8e5f6613330640927fdb53a23f62d7d3ac676c87eeef00fde40268040d863054","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p72-34220034"},{"id":"587f7f7a-2795-566e-ba62-459657e587d4","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حبوب محظورة بقصد الترويج والتعاطي -محاولة هرب -تداخل عقوبات -ثبوت إدانة -تعزير بالسجن واجللد -تعزير باملصادرة واملنع من السفر.","document_number":"34241491","case_number":"34163215","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة اخلرج","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/14","year":"1434","subject":"مخدرات -حيازة حبوب محظورة بقصد الترويج والتعاطي -محاولة هرب -تداخل عقوبات -ثبوت إدانة -تعزير بالسجن واجللد -تعزير باملصادرة واملنع من السفر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34241491:‬تاريخه ‪1434/6/14:‬هـ‬\n                   ‫رقم الدعوى ‪34163215:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34267301‬تاريخه‪1434/07/12:‬هـ‬\n\n\n‫مخــدرات ‪ -‬حيــازة حبــوب محظــورة بقصــد الترويــج والتعاطــي‬\n‫‪ -‬محاولــة هــرب‪ -‬تداخــل عقوبــات ‪ -‬ثبــوت إدانــة ‪ -‬تعزيــر بالســجن‬\n                    ‫واجللــد ‪ -‬تعزيــر باملصــادرة واملنــع مــن الســفر‪.‬‬\n\n\n\n\n‫املــواد ( ‪ )62 /60 /56 /38‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                          ‫العقليــة‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بترويــج احلبــوب املخــدرة عــن‬\n‫طريــق البيــع وحيازتهــا لقصــد الترويــج وتعاطيــه لنوعهــا‪ ،‬وطلــب‬\n‫املدعــي العــام إثبــات مــا أســند إليــه و احلكــم عليــه بالعقوبــة الــواردة‬\n‫وفق ـ ًا للمــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات و املؤثــرات العقليــة‬\n‫و العقوبــة الــواردة وفق ـ ًا للمــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات و‬\n‫املؤثــرات العقليــة و منعــه مــن الســفر خــارج اململكــة و مصــادرة اجلــوال‬\n‫املســتخدم يف اجلرميــة و عــدم صــرف الشــريحة لنفــس املشــترك و تعزيــره‬\n‫لقــاء صدمــه الدوريــة و محاولــة الهــرب مــن الفرقــة القابضــة ‪ ،‬حيــث إنــه‬\n‫مت القبــض علــى املدعــى عليــه بعــد ورود بــاغ بأنــه يقــوم بترويــج احلبــوب‬\n‫احملظــورة فتــم التنســيق مــع أحــد املصــادر لإلطاحــة بــه ومت إتصــال‬\n\n                                                                                    ‫‪78‬‬\n\f     ‫املصــدر علــى املتهــم واتفقــا علــى املــكان احملــدد وحضــر املصــدر إلــى‬\n     ‫منــزل املتهــم وأعطــى اإلشــارة بإمتــام عمليــة البيــع وســلم للفرقــة القابضــة‬\n     ‫عــدد ســت حبــات حتمــل عالمــة الكبتاجــون ومتــت مراقبــة املذكــور‬\n     ‫حتــى مت القبــض عليــه وصــدر التقريــر الكيميائــي بإيجابيــة العينــة‬\n     ‫املرســلة‪ ،‬كمــا أقــر املدعــى عليــه باحليــازة لغــرض االســتخدام وأنكــر‬\n     ‫احليــازة بقصــد الترويــج وأحضــر املدعــي العــام بينــة موصلــة تثبــت‬\n     ‫احليــازة لقصــد الترويــج‪ ،‬ثبــوت إدانــة املدعــى عليــه‪ ،‬بنــاء علــى مــا تقــدم‬\n     ‫حكمــت احملكمــة بتعزيــر املدعــى عليــه بالســجن واجللــد واملنــع مــن‬\n     ‫الســفر ومصــادرة الهاتــف اجلــوال وإلغــاء الشــريحة املســتخدمان باجلرميــة‬\n     ‫ورد دعــوى املدعــي العــام بطلــب تطبيــق العقوبــة الــواردة وفقـ ًا للمــادة ‪41‬‬\n     ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وصــدق احلكــم مــن‬\n                                                               ‫محكمــة االســتئناف‪.‬‬\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..............‬القاضــي يف احملكمــة‬\n     ‫العامــة مبحافظــة اخلــرج وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n     ‫رئيــس احملكمــة العامــة باخلــرج ‪ /‬املكلــف برقــم ‪ 34163215‬وتاريــخ‬\n     ‫‪ 1434/04/09‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34868437‬وتاريــخ‬\n     ‫‪ 1434/04/09‬ه ـ ويف يــوم الثالثــاء املوافــق‪ 1434/05/21‬ه ـ افتتحــت‬\n     ‫اجللســة الســاعة ‪ 09 : 30‬وفيهــا حضــر املدعــي العــام بدائــرة التحقيــق‬\n     ‫و اإلدعــاء العــام ‪ ..............‬وادعــى علــى احلاضــر معــه ‪ ..............‬ســعودي‬\n     ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ..............‬بقولــه ‪ :‬فأنــه بتاريــخ‬\n     ‫‪1434/2/25‬ه ـ قبــض علــى املذكــور مــن قبــل مكافحــة املخــدرات‬\n\n‫‪79‬‬\n\f‫مبحافظــة اخلــرج لتوفــر معلومــات عنــه بترويــج احلبــوب املخــدرة و ُأ ِرســل‬\n‫لــه مصــدر وقــام باالتصــال بــه مبســمع مــن الفرقــة ولــم يجــب ثــم اتصــل‬\n‫عليــه وطلــب منــه املصــدر حبــوب مببلــغ (‪ )200‬مائتــن ريــال فوافقــه‬\n‫وطلــب مــن املصــدر احلضــور ملنزلــه وذهــب املصــدر ملنزلــه حتــت أنظــار‬\n‫الفرقــة واجتــه لــه وحتــدث معــه ثــم حتــرك املصــدر وأعطــى إالشــاره‬\n‫الدالــة علــى إمتــام الشــراء وســلم للفرقــة عــدد (‪ )6‬ســت حبــات حتمــل‬\n‫عالمــة الكبتاجــون احملظــور مييــل لونهــا للبيــج وهــي الكميــة املشــتراه‬\n‫ومتــت مراقبــة املذكــور وشــوهد حضــور أشــخاص لــه ومقابلتهــم وبعــد‬\n‫ســاعة ركــب ســيارته ومت اســتيقافه وحــاول الهــرب ومت إطــاق أعيــره‬\n‫ناريــة يف الهــواء فتوقــف وبتفتيشــه عثــر يف جيبــه العلــوي علــى كيــس‬\n‫بداخلــة عــدد (‪)57‬ســبع وخمســون حبــه حتمــل عالمــة الكبتاجــون‬\n‫املميــزة وكان يحــاول التخلــص منهــا وعثــر أيضــا يف جيبــه الســفلي‬\n‫األيســر مبلــغ مالــي قــدرة (‪ )1300‬ألــف وثالثمائــة ريــال وجــد مــن ضمنها‬\n‫املبلــغ احلكومــي املعــد واملرقــم جــرى اســتقطاعه كمــا ضبــط معــه‬\n‫جهــاز جــول مســتخدم يف اجلرميــة وقــد حصــل أثنــاء اســتيقافه احتــكاك‬\n                 ‫بــن ســيارته والســيارة الرســمية يف بعــض التلفيــات فيهــا‪.‬‬\n‫وقــد أثبــت التقريــر الكيميائــي الشــرعي رقــم (‪/2650‬س) إيجابيــة‬\n‫احلبــوب املضبوطــة مــع املذكــور واحتوائهــا لإلمفيتامــن وهــو مــن املــواد‬\n‫املدرجــة باجلــدول رقــم (‪ )2‬فئــة (ب) مــن نظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة ‪ .‬وبســماع أقوالــة واســتجوابه أقــر بحيازتــه للحبــوب‬\n‫احملظــورة وللمبلــغ املالــي ولتعاطيــه احلبــوب املخــدرة ولصدمــه ســيارة‬\n‫الفرقــة القابضــة وبوجــود ســابقة تعاطــي حشــيش وحيازتــه مســجلة عليه‬\n‫وأفــاد أنــه حصــل علــى احلبــوب مــن شــخص أرتيــري أدلــى مبعلومــات عنــه‬\n\n\n                                                                                    ‫‪80‬‬\n\f                ‫ومت متريرهــا إلــى إدارة مكافحــة املخــدرات إلكمــال الــازم ‪.‬‬\n                                                                            ‫ملا أشير إليه‬\n     ‫أقــرر توجيــه االتهــام للمدعــى عليــه ‪ .............. /‬بترويــج عــدد ســت حبــات‬\n     ‫مــن احلبــوب املخــدرة عــن طريــق البيــع وحيــازة عــدد (‪ )57‬حبــه بقصــد‬\n     ‫الترويــج وتعاطيــه لنوعهــا املجــرم مبوجــب املــادة الثالثــة مــن نظــام‬\n     ‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي‬\n     ‫رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ وصدمــة لســيارة الفرقــة القابضــة‬\n                        ‫ومحاولــة الهــرب منهــم ‪ .‬وذلــك لألدلــة والقرائــن التاليــة‬\n     ‫‪-1‬محضــر القبــض املــدون علــى ص (‪ )12-11‬مــن ملــف ضبــط إجراءات‬\n                                                               ‫االســتدالل لفــه رقم (‪.)1‬‬\n                                ‫‪-2‬ما ضبط بحوزته من حبوب ومبلغ مالي مرقم ‪.‬‬\n         ‫‪-3‬ماجاء يف أقواله املدونة على ص (‪ )2-1‬من ملف حتقيق رقم (‪. )1‬‬\n                                ‫‪-4‬التقرير الكيميائي الشرعي لفه رقم (‪. )........‬‬\n            ‫وببحث سوابقه تبني وجود سابقة حيازة وتعاطي احلشيش املخدر ‪.‬‬\n     ‫وحيــث إن مــا أقــدم عليــه املذكــور فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n     ‫ونظامـ ًا ممــا يتعــن إحالتــه إلــى احملكمــة العامــة بطلــب إثبــات مــا أســند‬\n     ‫إليــه واحلكــم عليــه مبــا يلــي ‪-1 -:‬بعقوبــة وفقـ ًا للمــادة (‪ )38‬مــن نظــام‬\n              ‫مكافحــة املخــدرات املشــار إليــه لقــاء ترويجــه احلبــوب املخــدرة ‪.‬‬\n     ‫‪-2‬بعقوبــة وفق ـ ًا للمــادة (‪ )41‬مــن ذات النظــام لقــاء حيازتــه للحبــوب‬\n                                                                               ‫املخــدرة ‪.‬‬\n     ‫‪-3‬منعــه مــن الســفر خــارج اململكــة وفقـ ًا للفقــرة األولــى مــن املــادة (‪)56‬‬\n     ‫مــن ذات النظــام ‪-4‬مصــادرة اجلــوال املوصــوف بالوقائع وإبالغ الشــركة‬\n     ‫مصــدر الشــريحة املســتخدمة يف الترويــج بعــدم صرفهــا لنفــس املشــترك‬\n\n\n‫‪81‬‬\n\f‫يف حــال صــدور احلكــم باملصــادرة اســتناد ًا لتعميــم صاحــب الســمو‬\n‫امللكــي وزيــر الداخليــة رقــم (‪ )9798‬يف ‪1428/2/10-9‬ه ـ وفق ـ ًا ملــا‬\n‫ورد يف املــادة (‪ )53‬مــن النظــام املشــار إليــه علــى ضــوء قــرار مجلــس‬\n                                         ‫الــوزراء رقــم (‪ )47‬يف ‪1421/2/18‬ه ـ ‪.‬‬\n    ‫‪-5‬تعزيره لقاء صدمة لسيارة الفرقة القابضة ومحاولة الهرب منهم ‪.‬‬\n‫مــع التشــديد عليــه يف احلكــم اســتناد ًا لتعميــم صاحــب الســمو امللكــي‬\n‫وزيــر الداخليــة رقــم (‪2/8346/5/1‬ش) وتاريــخ ‪1427/2/8‬ه ـ هــذه‬\n                                                                            ‫دعــواي‬\n‫وبســؤال املدعــى عليــه أجــاب بقولــه‪ :‬مــا ذكــره املدعــي العــام مــن‬\n‫حيازتــي للحبــوب احملظــورة املوصوفــة يف الدعــوى فصحيــح و لكــن‬\n‫كانــت حيازتــي لهــا بغــرض التعاطــي فأنــا أتعاطــى احلبــوب احملظــورة‬\n‫وأمــا مــا ذكــره املدعــي العــام مــن الترويــج فغيــر صحيــح وأمــا مــا ذكره‬\n‫املدعــي العــام مــن اصطدامــي بالفرقــة القابضــة فصحيــح ولكــن كان‬\n‫ذلــك بســبب توقفهــم أمامــي مباشــرة بســيارتهم فلــم أســتطع تفاديهــم‬\n‫واصطدمــت بهــم هكــذا أجــاب ثــم جــرى ســؤال املدعــي العــام عــن‬\n‫ا ‪ :‬بينتــي أحضرتهــا معــي وهــي عبــارة عــن شــاهدين‬      ‫بينتــه فأجــاب قائـ ً‬\n‫مــن الفرقــة القابضــة هكــذا قــرر و يف هــذه اجللســة حضــر ‪..............‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ..............‬و‪..............‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ..............‬ويعمــان بــإدارة‬\n‫مكافحــة املخــدرات باخلــرج وبســؤالهما عمــا لديهمــا مــن شــهادة أجــاب‬\n‫كل واحــد منهمــا منفــرد ًا بقولــه ‪ :‬أشــهد بأنــه توفــر لدينــا معلومــات‬\n‫عنــد قيــام املدعــى عليــه بترويــج احلبــوب املخــدرة فتــم اإلتفــاق مــع مصــدر‬\n‫ســري لإلطاحــة بــه فقــام املصــدر الســري باالتصــال بــه علــى مســمع منــا‬\n\n\n                                                                                       ‫‪82‬‬\n\f     ‫و طلــب منــه حبوب ـ ًا مببلــغ مائتــي ريــال فوافــق املدعــى عليــه وطلــب مــن‬\n     ‫املصــدر احلضــور ملنزلــه فتــم تفتيــش املصــدر و تســليمه مبلغـ ًا حكوميـ ًا‬\n     ‫وقــدره مائتــي ريــال ثــم اجتــه املصــدر ملنــزل املدعــى عليــه حتــت أنظارنــا‬\n     ‫و تقابــل مــع املدعــى عليــه وحتــدث معــه ثــم حتــرك املصــدر و أعطــى‬\n     ‫اإلشــارة الدالــة علــى إمتــام الشــراء ولــم نشــاهد التســليم و التســلم ثــم‬\n     ‫سـلّم لنــا املصــدر عــدد ســت حبــات حتمــل عالمــة الكبتاجــون احملظورة‬\n     ‫فتــم مراقبــة املدعــى عليــه وشــوهد حضــور أشــخاص لــه ومقابلتهــم و‬\n     ‫بعــد فتــرة ركــب ســيارته و مت اســتيقافه فحــاول الهــرب فتــم إيقــاف‬\n     ‫ســيارتنا أمامــه لئــا يهــرب فاصطــدم بنــا و توقــف فتــم تفتيشــه فعثــر‬\n     ‫يف جيبــه علــى كيــس بداخلــه ســبع و خمســون حبــة حتمــل عالمــة‬\n     ‫العينــة التــي سـلّمها لنــا املصــدر الســري كمــا‬   ‫الكبتاجــون وهــي نفــس ّ‬\n     ‫عثــر معــه علــى مبلــغ مالــي و قــدره ألــف وثالثمائــة ريــال وكان املبلــغ‬\n     ‫احلكومــي املرقــم مــن ضمنهــا كمــا وجــد بحوزتــه جهــاز جــوال هــذا‬\n     ‫مــا لدينــا مــن شــهادة هكــذا شــهدا و بعــرض الشــاهدين وشــهادتهما‬\n     ‫علــى املدعــى عليــه قــال أمــا الشــاهدين فــا أعرفهمــا و أمــا شــهادتهما‬\n     ‫فغيــر صحيحــة هكــذا قــرر و قــد جــرى تعديــل الشــاهدين مــن قبــل‬\n     ‫‪ ..............‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ..............‬و‬\n     ‫‪ ..............‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ..............‬ثــم‬\n     ‫ا ‪ :‬ال يوجــد‬   ‫جــرى ســؤال املدعــي العــام هــل لديــه زيــادة ّبينــة فأجــاب قائـ ً‬\n     ‫لــدي ســوى مــا يف أوراق املعاملــة هكــذا قــرر‪ .‬ويف جلســة أخــرى جــرى‬\n     ‫ا‬ ‫ســؤال املدعــى عليــه عــن الســابقة املذكــورة يف الدعــوى فأجــاب قائـ ً‬\n     ‫‪ :‬أمــا الســابقة فصحيحــة ولكــن لــم يصــدر فيهــا حكــم ألنــه شــملني‬\n     ‫العفــو هكــذا أجــاب جــرى تصفــح أوراق املعاملة واإلطــاع على محضر‬\n\n\n‫‪83‬‬\n\f‫القبــض والضبــط والتفتيــش املــدون مبلــف التحقيــق لفــة ‪ 1‬صــ‪12-11‬‬\n‫فوجدتــه مطابقـ ًا ملــا جــاء يف دعــوى املدعــي العــام كمــا جــرى اإلطــاع‬\n‫علــى التقريــر الكيميائــي الشــرعي رقــم ‪/2650‬س يف ‪1434/3/17‬ه ـ‬\n‫لفــة ‪ 27‬فوجدتــه مطابقـ ًا ملــا ذكــره املدعــي العــام يف دعــواه فبنــاء علــى‬\n‫مــا تقــدم ذكــره مــن الدعــوى واإلجابــة ومبــا أن املدعــى عليــه قــد أقــر‬\n‫بحيازتــه احلبــوب احملظــورة املوصوفــة يف الدعــوى وأنــه غرضــه مــن ذلــك‬\n‫التعاطــي‪ ،‬ومبــا أن املدعــى عليــه قــد أقــر باصطدامــه بالفرقــة القابضــة‬\n‫ودفــع بــأن ذلــك كان بســبب توقفهــم أمامــه مباشــرة وبنــاء علــى مــا ورد‬\n‫يف شــهادة الشــاهدين املعدلني من اتصال املصدر الســري باملدعى عليه‬\n‫وطلبــه حبوب ـ ًا مببلــغ مائتــي ريــال وأن املدعــى عليــه طلــب مــن املصــدر‬\n‫الســري احلضــور ملنزلــه وأن ذلــك كان علــى مســمع منهمــا ‪ ،‬وبنــاء علــى‬\n‫مــا ورد يف شــهادة الشــاهدين املعدلــن مــن أن املصــدر الســري قــد تقابــل‬\n‫مــع املدعــى عليــه حتــت أنظارهمــا وقــام املصــدر بإعطــاء اإلشــارة الدالــة‬\n‫على إمتام الشــراء وأن املصدر الســري قام بتســليم الفرقة القابضة ســت‬\n‫حبــات حتمــل عالمــة الكبتاجــون احملظــورة وأنهمــا لــم يشــاهدا عمليــة‬\n‫التســلم واالســتالم وأنــه مت اســتيقاف املدعــى عليــه فحــاول الهــرب فتــم‬\n‫التوقــف أمامــه مباشــرة ممــا أدى إلــى اصطدامــه بهــم وأنــه عثــر يف جيبــه‬\n‫علــى كيــس بــه ســبع وخمســن حبــة حتمــل عالمــة الكبتاجــون وأنهــا‬\n‫العينــة التــي س ـلّمها لهــم املصــدر الســري كمــا عثــر مــع املدعــى‬\n                                                                        ‫نفــس ّ‬\n                 ‫عليــه علــى املبلــغ احلكومــي املرقــم وكذلــك جهــاز جــوال‪.‬‬\n‫وبنــاء علــى مــا ورد يف التقريــر الكيميائــي الشــرعي املنــوه عنــه آنف ـ ًا‬\n‫ونظــر ًا لوجــود ســابقة حيــازة وتعاطــي حشــيش مخــدر علــى املدعــى عليــه‬\n‫واســتناد ًا إلــى مــا ورد يف الشــريعة مــن حرمــة املخــدرات ملــا فيهــا مــن‬\n\n\n                                                                                     ‫‪84‬‬\n\f     ‫الضــرر البــن علــى األفــراد واملجتمعــات وملــا قــرره أهــل العلــم مــن العمــل‬\n     ‫بالقرائــن إذا قويــت وبنــاء علــى املــادة الثامنــة والثالثــن واملــادة السادســة‬\n     ‫واخلمســن واملــادة الســتني واملــادة الثانيــة والســتني ( أن احملاكمــة‬\n     ‫تكــون علــى العقوبــة األشــد ويحكــم بعقوبتهــا دون غيرهــا ) مــن نظــام‬\n     ‫مكافحــة املخــدرات واملؤثــرات العقليــة ولكــون العقوبــات تتداخــل إذا‬\n     ‫كانــت مــن جنــس واحــد وملــا يظهــر مــن أخــاق املدعــى عليــه لــكل مــا‬\n     ‫ســبق فقــد ثبــت لــدي إدانــة املدعــى عليــه بحيازتــه ســبع وخمســن حبــة‬\n     ‫مــن حبــوب االمفيتامــن املنبــه احملظــور بقصد التعاطــي وتعاطيه لنوعها‬\n     ‫يف الســابق كمــا ثبــت لــدي إدانــة املدعــى عليــه بترويــج ســت حبــات‬\n     ‫مــن احلبــوب احملظــورة كمــا ثبــت لــدي محاولــة املدعــى عليــه للهــرب‬\n     ‫مــن الفرقــة القابضــة كمــا ثبــت لــدي اصطــدام املدعــى عليــه بســيارة‬\n     ‫الفرقــة القابضــة وقــررت مــا يلــي ‪ :‬أو ًال ‪ :‬ســجن املدعــى عليــه ملــدة ثــاث‬\n     ‫ســنوات يحتســب منهــا مــدة إيقافــه بنــاء علــى املــادة الســتني مــن نظــام‬\n     ‫مكافحــة املخــدرات وجلــده مائتــي جلــدة مفرقــة علــى أربــع دفعــات‬\n     ‫متســاوية بــن الدفعــة واألخــرى عشــرين يوم ـ ًا وإلزامــه بدفــع غرامــة‬\n     ‫وقدرهــا ألــف ريــال تــودع يف بيــت املــال ‪ .‬ثانيـ ًا ‪ :‬رد دعــوى املدعــي العــام‬\n     ‫فيمــا يتعلــق بطلبــه تطبيــق العقوبــة الــواردة يف املــادة احلاديــة واألربعــن‬\n     ‫مــن نظــام مكافحــة املخــدرات وذلــك بنــاء علــى املــادة الثانيــة والســتني‬\n     ‫مــن ذات النظــام ‪ .‬ثالثـ ًا ‪ :‬منــع املدعــى عليــه مــن الســفر خــارج اململكــة‬\n     ‫ملــدة ثــاث ســنوات بعــد انتهــاء تنفيــذ عقوبــة الســجن بنــاء علــى املــادة‬\n     ‫السادســة واخلمســن مــن نظــام مكافحــة املخــدرات ‪ .‬رابع ـ ًا ‪ :‬مصــادرة‬\n     ‫الهاتــف اجلــوال العائــد للمدعــى عليــه واملوصــوف يف الوقائــع وإلغــاء‬\n     ‫الشــريحة الهاتفيــة العائــدة لــه واملســتخدمة يف عمليــة الترويــج وعــدم‬\n\n\n‫‪85‬‬\n\f‫صرفهــا لنفــس املشــترك وإبــاغ الشــركة مصــدرة الشــريحة بذلــك ‪،‬‬\n‫خامس ـ ًا ‪ :‬االكتفــاء مبــا ُحكــم بــه يف الفقــرة أو ًال فيمــا يتعلــق بتعزيــر‬\n‫املدعــى عليــه لقــاء محاولــة املدعــى عليــه الهــرب واصطدامــه بســيارة‬\n‫الفرقــة القابضــة ومبــا ســبق حكمــت وبعــرض احلكــم علــى الطرفــن‬\n‫قنــع املدعــى عليــه و قــرر املدعــي العــام اعتراضــه علــى احلكــم وطلــب‬\n‫رفــع املعاملــة حملكمــة االســتئناف بــدون الئحــة فأجيــب لطلبــه ختمــت‬\n‫يف الســاعة احلاديــة عشــرة والنصــف وعليــه جــرى التوقيــع وصلــى اهلل‬\n                          ‫وســلم علــى نبينــا محمــد حــرر يف ‪1434/6/13‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة‬\n‫لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة باخلــرج برقــم ‪34868437‬‬\n‫وتاريــخ ‪1434/6/18‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضي‬\n‫باحملكمــة الشــيخ‪ .............. /‬املســجل برقــم ‪ 34241491‬وتاريــخ‬\n‫‪1434/6/14‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد‪ .............. /‬التهامــه‬\n‫بقضيــة مخــدرات علــى النحــو املوضــح بالقــرار املتضمــن حكــم‬\n‫فضيلتــه مبــا هــو مــدون ومفصــل بــه‪ .‬وبدراســة القــرار وصــورة ضبطــه‬\n‫وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل‬\n                                       ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                      ‫‪86‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":78,"source_page_end":86,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ccee7671c1c1b11ff7ffd9af4a94591165cff9214c792f16d6346de14796fc6a","normalized_text_hash":"1640918b027f523caf8bcede3246372947f3f755792dec82563c982fd8a067fd","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p78-34241491"},{"id":"7a6f1004-1596-5816-a97c-ffab4e5e4325","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة احلشيش بقصد الترويج والتعاطي -إقرار حتقيق ا -رجوع عن إقرار -نزول عن احلد األدنى للعقوبة -تعزير بالسجن واجللد واإلبعاد.","document_number":"34204877","case_number":"34164499","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/4","year":"1434","subject":"مخدرات -حيازة احلشيش بقصد الترويج والتعاطي -إقرار حتقيق ا -رجوع عن إقرار -نزول عن احلد األدنى للعقوبة -تعزير بالسجن واجللد واإلبعاد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪ 34204877 :‬تاريخه ‪1434/5/4 :‬هـ‬\n                         ‫رقم الدعوى‪34164499 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34874635‬تاريخه‪1434/01/01:‬هـ‬\n\n\n     ‫مخــدرات ‪ -‬حيــازة احلشــيش بقصــد الترويــج والتعاطــي ‪ -‬إقــرار‬\n     ‫حتقيقـ ًا ‪ -‬رجــوع عــن إقــرار ‪ -‬نــزول عــن احلــد األدنــى للعقوبــة ‪ -‬تعزيــر‬\n                                                     ‫بالســجن واجللــد واإلبعــاد‪.‬‬\n\n\n\n       ‫املواد ( ‪ ) 56 - 41 - 60‬من نظام مكافحة املخدرات واملؤثرات العقلية‬\n\n\n\n\n     ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بتوجيــه االتهــام لــه بحيــازة‬\n     ‫احلشــيش املخــدر بقصــد الترويــج وتعاطيــه لــه‪ ،‬وطلــب املدعــي العــام‬\n     ‫إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة الســجن واجللــد والغرامــة‬\n     ‫واإلبعــاد عــن البــاد وعــدم الســماح لــه بالعــودة وإلغــاء شــريحه اجلــوال‬\n     ‫املســتخدمة بالترويــج ‪ ،‬حيــث أنــه مت القبــض علــى املدعــى عليــه متلبسـ ًا‬\n     ‫باجلرميــة بعــد إخباريــة مفادهــا أن املدعــى عليــه يقــوم بالتوســط والترويــج‬\n     ‫ملــادة احلشــيش املخــدر ومت التنســيق مــع إحــدى املصادر الســرية لإلطاحة‬\n     ‫بــه ‪ ،‬إنــكار املدعــى عليــه‪ ،‬أحضــر املدعــي العــام البينــة وهــم شــهود‬\n     ‫القبــض ‪ ،‬أقــر املدعــى عليــه حتقيقــا وأنكــر أمــام احملكمــة وثبتــت‬\n     ‫إدانتــه باحليــازة لغــرض االســتخدام وعــدم ثبــوت احليازة لغــرض الترويج‪،‬‬\n     ‫بنــاء علــى مــا تقــدم حكمــت احملكمــة بتعزيــر املدعــى عليــه بالســجن‬\n\n‫‪87‬‬\n\f             ‫واجللــد واإلبعــاد وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبكــة املكرمــة ‪ ............‬وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة مبكــة املكرمــة برقــم ‪ 34164499‬وتاريــخ‬\n‫‪1434/04/09‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34874635‬وتاريــخ‬\n‫‪1434/04/09‬ه ـ ففــي يــوم األربعــاء املوافق‪1434/04/10‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 02 : 00‬وفيهــا حضــر املدعــي العــام مبوجــب خطــاب‬\n‫التعميــد رقــم ه ـ م ‪ / 2 /‬أ ‪ 341 /‬وتاريــخ ‪1424/1/24‬ه ـ وحضــر‬\n‫حلضــوره املدعــى عليــه ‪ ........‬مينــي اجلنســية مبوجــب اإلقامة رقــم ‪..............‬‬\n‫وادعــى املدعــي العــام قائــا إنــه بتاريــخ ‪1434/3/12‬ه ـ وردت معلومــات‬\n‫مــن أحــد املصــادر إلدارة مكافحــة املخــدرات بالعاصمــة املقدســة‬\n‫مفادهــا قيــام املدعــى عليــه بالتوســط والترويــج يف مــادة احلشــيش‬\n‫املخــدر واســتعد املصــدر الشــراء املباشــر منــه وذكــر بانــه يســتخدم‬\n‫الرقــم(‪ ،)...................‬وعلــى الفــور مت متكــن املصــدر مــن االتصــال‬\n‫علــى جــوال املدعــى عليــه املنــوه عنــه‪ ،‬حتــت ســماع أفــراد الفرقــة‬\n‫القابضــة وطلــب منــه ان يؤمــن لــه كميــه مــن احلشــيش املخــدر مببلــغ‬\n‫(‪ )200‬مأتــي ريــال فاســتعد املدعــى عليــه بتأمينهــا وطلب من املصدر ان‬\n‫يحضــر لــه بجــوار قصــر الزمــردة علــى الشــارع العــام وباالنتقــال للموقــع‬\n‫شــوهد املدعــى عليــه فتوجــه لــه املصــدر وضابــط الفرقــة وبنزولهمــا مــن‬\n‫الســيارة قــام املدعــى عليــه بتســليم املصــدر قطعــه يشــتبه ان تكــون‬\n‫مــن احلشــيش املخــدر وزنها(‪)10‬عشــره جرامــات ‪ ،‬وعنــد تســليمه املبلــغ‬\n\n                                                                                          ‫‪88‬‬\n\f     ‫املالــي املرقــم غــادر مســرعا لداخــل احلــي‪ ،‬وعنــد تتبعــه‪ ،‬لــم يعثــر عليــه‪،‬‬\n     ‫فتــم وضعــه حتــت املراقبــة و بتاريــخ ‪1434/3/15‬هــ‪ ،‬شــوهد املدعــى‬\n     ‫عليــه يخــرج مــن منزلــه‪ ،‬فتــم القبــض عليــه(مت التعــرف عليــه مــن قبــل‬\n     ‫أفــراد الفرقــة القابضــة وأعــد محضــر بذلــك ) وباصطحابــه ملنزلــه مت‬\n     ‫تفتيــش الغرفــة اخلــاص بــه وضبــط حتــت الكنبــة علــى قطعــه بنيــه اللــون‬\n     ‫وزنها(‪)0,50‬خمســون باملئــة مــن اجلــرام‪ ،‬يشــتبه أن تكــون مــن احلشــيش‬\n     ‫املخــدر اثبــت التقريــر الكيميائــي الصــادر مــن مركــز الســموم‬\n     ‫والكيميــاء الشــرعية مبكــة املكرمــة رقم(‪/4747‬س‪1434/2‬هــ)‬\n     ‫إيجابيــة العينتــن(أ‪،‬ب) املروجــة واملضبوطــة ملــادة احلشــيش املخــدر‬\n     ‫واحتوائهمــا علــى املــادة الفعالــة لــه ‪ .،‬وهــو مــن املــواد املخــدرة املدرجــة‬\n     ‫باجلــدول رقــم(‪ )1‬فئــة (أ) امللحــق بنظــام مكافحــة املخــدرات واملؤثرات‬\n     ‫العقليــة الصــادر باملرســوم امللكــي الكــرمي رقــم م‪ 39/‬يف ‪1426/7/8‬‬\n     ‫ه ـ بالتحقيــق مــع املدعــى عليــه ‪ :‬أفــاد بانــه تلقــى اتصــا ًال مــن املصــدر‬\n     ‫علــى هاتــف جوالــه رقــم (‪ ) ..............‬طالب ـ ًا منــه أن يبيعــه عســل مببلــغ‬\n     ‫وقــدره (‪ )200‬مائتــي ريــال فوافــق وعنــد حضــوره لــه يف يــوم اخلميــس‬\n     ‫وقــت العشــاء تقابــل مــع املصــدر وكان يرافقــه شــخص آخــر وحتدثــا‬\n     ‫ولــم يعطيــه قيمــة العســل وغــادر ‪ ،‬وأقــر بانــه ضبــط قطعــه مــن احلشــيش‬\n     ‫املخــدر وزنهــا(‪ )0,50‬خمســون باملئــة مــن اجلــرام عائــدة لــه شــخصي ًا‬\n     ‫بقصــد االســتعمال وحصــل عليهــا مــن شــخص ال يعرفــه ‪ ،‬وان اجلــوال‬\n     ‫املضبــوط بحوزتــه عائــد لــه وهــو الــذي تلقــى االتصــال عليــه مــن املصــدر‬\n     ‫وفقــده عنــد القبــض عليــه وقــد انتهــى التحقيــق إلــى توجيــه االتهــام‬\n     ‫للمدعــى عليــه ‪ :‬بترويــج (‪ )10‬عشــرة جرامــات مــن مــادة احلشــيش‬\n     ‫املخــدر عــن طريــق البيــع ‪ ،‬وحيــازة (‪ ),50‬خمســون باملئــة مــن اجلــرام مــن‬\n\n\n‫‪89‬‬\n\f‫ذات النــوع بقصــد الترويــج والتعاطــي وذلــك لألدلــة والقرائــن التاليــة ‪:‬‬\n‫‪ -1‬مــا ورد بإقــراره املنــوه عنــه صفحــه رقــم(‪ )4‬لفــه رقــم(‪ -2 )12‬مــا ورد‬\n        ‫مبحضــر القبــض املنــوه عنــه صفحــه رقــم(‪ )13-12‬لفــه رقــم(‪)1‬‬\n‫‪ -3‬مــا ورد مبحضــر التعــرف مــن رجــال األمــن املنوه عنــه صفحه رقم(‪)4‬‬\n‫لفــه رقــم(‪ -4 )1‬مــا ورد بالتقريــر الكيميائــي املنــوه عنــه لفــه رقــم(‪)11‬‬\n‫وحيــث أن مــا قــام بــه املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة‬\n‫شــرع ًا فعــل محــرم شــرعا ومعاقــب عليــه وفق ـ ًا لنظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم (م‪)39/‬‬\n‫يف ‪1426/7/8‬هــ‪ ،‬وفق ـ ًا للفقــرة (‪ )2‬مــن املــادة(‪ )3‬مــن ذات النظــام‬\n‫لــذا أطلــب إ ثبــات إدانتــه مبــا اســند إليــه واحلكــم عليــه بالعقوبــات‬\n‫األصليــة والتكميليــة التاليــة ‪-1 :‬الســجن واجللــد والغرامــة املنصــوص‬\n‫عليهــا يف الفقــرة (‪ )1‬مــن املــادة( ‪ ) 38‬مــن نظــام مكافحــة املخــدرات‬\n‫املشــار إليــه ‪ 2‬بعــاده عــن اململكــة بعــد تنفيــذ العقوبــة احملكــوم بهــا‬\n‫عليــه وال يســمح لــه بالعــودة إليهــا يف ماعــدا مــا تســمح بــه تعليمــات‬\n‫احلــج والعمــرة وفقــا للفقــرة (‪ )2‬مــن املــادة(‪ )56‬مــن نظــام مكافحــة‬\n‫املخــدرات املشــار إليــه ‪-3‬إلغــاء الشــريحة املســتخدمة يف الترويــج وعــدم‬\n‫صرفهــا للمدعــى عليــه مــرة أخــرى اســتنادا لتعميــم صاحــب الســمو‬\n‫امللكــي نائــب رئيــس مجلــس الــوزراء وزيــر الداخليــة رقــم (‪ )9798‬يف‬\n‫‪1428/2/10-9‬ه ـ وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائــا مــا‬\n‫ذكــره املدعــي العــام كلــه غيــر صحيــح جملــة وتفصيــا ولــم يكــن‬\n‫لــدي وال بحوزتــي حشــيش أبــد ًا والشــخص الــذي اتصــل بــي كان‬\n‫يطلــب منــي عســل فقــط واتهمونــي باحلشــيش هكــذا أجــاب املدعــى‬\n‫عليــه وبســؤال املدعــي العــام هــل لديــه بينــه علــى صحــة الدعــوى‬\n\n\n                                                                                   ‫‪90‬‬\n\f     ‫فقــال نعــم لــدي البينــة وأطلــب إمهالــي إلحضارهــا لكــم يف اجللســة‬\n     ‫القادمــة لــذا قــررت رفــع اجللســة وقــد حــدد لهــا موعــد يف يــوم األربعــاء‬\n     ‫‪1434/4/17‬ه ـ ويف جلســة أخــرى حضــر املدعــي العــام ولــم يحضــر‬\n     ‫املدعــى عليــه وبســؤال املدعــي العــام عــن البينــة التــي وعــد بإحضارهــا‬\n     ‫فاحضــر ‪ ........‬ســعودي بالســجل املدنــي رقــم ‪ ........‬وشــهد قائــا اشــهد‬\n     ‫هلل تعالــى أنــه يف يــوم مــن األيــام ورد لــإدارة بــاغ علــى أن املدعــى عليــه‬\n     ‫يقــوم بترويــج احلشــيش فتــم االتصــال باملدعــى عليــه عــن طريــق أحــد‬\n     ‫مصادرنــا وكنــت أســمع املكاملــة عندمــا طلــب املصــدر مــن املدعــى‬\n     ‫عليــه كميــة مــن احلشــيش مببلــغ مائتــي ريــال فاســتعد املدعــى عليــه‬\n     ‫بذلــك وقــال لــه قابلنــي عنــد قاعــة ‪ ............‬فذهــب إليــه املصــدر ومعــه‬\n     ‫أحــد زمالئــي أمــا أنــا فكنــت متخفــي ال أشــاهدهم ولــم أرى االســتالم‬\n     ‫وال التســليم وبعــد يومــن انتقلنــا إلــى منــزل املدعــى عليــه فوجدنــا يف‬\n     ‫غرفتــه ‪ %50‬مــن اجلــرام مــن احلشــيش هــذا مــا لــدي مــن شــهادة كمــا‬\n     ‫أحضــر للشــهادة وأدائهــا ‪ ........‬ســعودي بالســجل املدنــي رقــم ‪................‬‬\n     ‫وشــهد قائــا أشــهد هلل تعالــى أننــي كنــت أراقــب املصــدر عندمــا قابــل‬\n     ‫املدعــى عليــه وقــام بالســام عليــه ومصافحتــه علمــا أننــي لــم أشــاهد‬\n     ‫الكميــة ولــم يقــم املصــدر بتســليم املبلــغ للمدعــى عليــه حلــذره وخوفــه‬\n     ‫وقــد عــاد املصــدر لنــا ومعــه كميــة احلشــيش مــع أننــا ســبق وان قمنــا‬\n     ‫بتفتيــش املصــدر تفتيشــا دقيقــا هكــذا شــهد الشــاهد كمــا احضــر‬\n     ‫للشــهادة وأدائهــا ‪ ........‬ســعودي بالســجل املدنــي رقــم ‪ .................‬وشــهد‬\n     ‫قائــا اشــهد هلل تعالــى أننــي ســمعت املكاملــة مــع املدعــى عليــه عندمــا‬\n     ‫أســتعد بإحضــار كميــة مــن احلشــيش مببلــغ مائتــن ريــال كمــا كنــت‬\n     ‫أشــاهد املصــدر عندمــا احتــك مــع املدعــى عليــه وقــام بالســام عليــه‬\n\n\n‫‪91‬‬\n\f‫ولــم أشــاهد الكميــة بعينهــا ولــم أشــاهد اســتالم املبلــغ وقــد انتقلنــا‬\n‫للشــقة ووجدنــا بهــا قطعــة مــن احلشــيش هكــذا شــهد الشــاهد ونظــرا‬\n‫لعــدم حضــور املدعــى عليــه قــررت رفــع اجللســة إلحضــار املدعــى عليــه‬\n‫وأفهمــت الشــهود باحلضــور يف اجللســة القادمــة وبرفقتهــم مــن يعدلهــم‬\n‫وقــد حــدد لهــا موعــد يف يــوم الســبت املوافــق ‪1434/05/04‬ه ـ وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                            ‫حــرر يف ‪ 1434/04/28‬ه ـ‬\n‫ويف جلســة أخرى حضر املدعي العام واملدعى عليه ولم يحضر الشــهود‬\n‫يف هــذه اجللســة وبعــرض مــا جــاء يف شــهادة الشــهود علــى املدعــى عليــه‬\n‫فقــال شــهادتهم غيــر صحيحــة كمــا جــرى الرجــوع إلــى ملــف التحقيــق‬\n‫املرفــق باملعاملــة علــى اللفــة رقــم ‪ 16‬ووجــدت علــى الصفحــة رقــم‬\n‫‪4‬اقــرارا للمدعــى عليــه ونصــه اقــر انــا املدعــو ‪ ..................‬مينــي اجلنســية‬\n‫مبوجــب إقامــة رقــم ‪ ..............‬وأنــا بكامــل قــواي العقليــة املعتبــرة شــرعا‬\n‫مــن غيــر أكــراه أو أجبــار مــن احــد بأنــه قبــض علــي وضبــط بغرفتــي‬\n‫اخلاصــة باملنــزل علــى قطعــة مــن احلشــيش املخــدر بلــغ وزنهــا خمســون‬\n‫باملائــة مــن اجلــرام عائــدة لــي شــخصيا واقصــد مــن حيازتهــا االســتخدام‬\n‫كمــا أقــر بــأن اجلــوال رقــم ‪ ...................‬عائــد لــي وهــو اجلــوال الــذي‬\n‫تلقيــت عليــه االتصــال مــن املصــدر ولقــد فقــدت اجلــوال املذكــور حينمــا‬\n‫مت القبــض علــي وعلــى ذلــك اقــر ولقــد اتفقــت مــع املصــدر ان البيعــة‬\n‫عســل مببلــغ ‪ 200‬ريــال حينمــا اتصــل علــي انتهــى نصــة وبعرضــه عليــه‬\n‫فقــال أن هــذا اإلقــرار كنــت مكــره عليــه اجبرونــي بالقــوة علــى هــذا‬\n‫االعتــراف وبســؤاله هــل لديــه بينــة علــى اإلكــراه فقــال ليســت لــدي‬\n‫بينــة وقــد جــرى الرجــوع علــى أوراق املعاملــة ومنهــا التقريــر الكيميائــي‬\n\n\n                                                                                            ‫‪92‬‬\n\f     ‫وصحيفــة ســوابق املدعــى عليــه ولــم أجــد مســجل بصحيفتــه ســوابق‬\n     ‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة واالطــاع علــى أوراق املعاملــة‬\n     ‫وبنــاء علــى مــا جــاء يف إقــرار املدعــى عليــه املــدون علــى ملــف التحقيــق‬\n     ‫ومــا جــاء يف شــهادة الشــهود املذكوريــن أعــاه ولكــون شــهادة الشــهود‬\n     ‫غيــر موصلــة إلدانــة املدعــى عليــه بتهمــة حيــازة كميــة مــن احلشــيش‬\n     ‫املذكــورة أعــاه بقصــد الترويــج لذلــك كلــه فقــد ثبــت لــدي إدانــة‬\n     ‫املدعــى عليــه بحيــازة ‪ %50‬مــن اجلــرام بقصــد االســتعمال الشــخصي ولــم‬\n     ‫يثبــت لــدي ســوى ذلــك وقــررت مــا يلــي أوال ـ ـ اســتنادا ملــا جــاء يف املــادة‬\n     ‫الســتني مــن نظــام مكافحــة املخــدرات ونظــرا لعــدم وجــود ســوابق‬\n     ‫بحــق املدعــى عليــه ولقلــة الكميــة فقــد نزلــت عــن احلــد األدنــى لعقوبــة‬\n     ‫الســجن احملــددة يف املــادة الواحــد واألربعــن وحكمــت بســجنه ملــدة‬\n     ‫شــهر اعتبــارا مــن تاريــخ توقيفــه علــى ذمــة هــذه القضيــة ثانيــا ـ ـ إبعــاده‬\n     ‫عــن البــاد اســتنادا للمــادة ‪ 56‬مــن نظــام مكافحــة املخــدرات ثالثــا ـ ـ‬\n     ‫ســجنه ملــدة أربعــة اشــهر اعتبــارا مــن تاريــخ انتهــاء مــدة الســجن الســابقة‬\n     ‫املذكــورة يف أوال وجلــده تعزيــرا خمســن جلــدة دفعــة واحــدة وذلــك‬\n     ‫لقــاء توجــه الشــبهة إليــه بترويــج عشــرة جرامــات مــن مــادة احلشــيش‬\n     ‫عــن طريــق البيــع وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه‬\n     ‫االعتــراض علــى إبعــاده عــن البــاد بــدون الئحــة كمــا قــرر املدعــي‬\n     ‫العــام االعتــراض علــى احلكــم بالئحــة فأفهــم بإجــراءات االســتئناف‬\n     ‫وبــاهلل التوفيــق وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                  ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/05/04‬ه ـ‬\n     ‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد ‪ ...‬نحــن رئيــس‬\n     ‫وقضــاة الدائــرة اجلزائيــة الرابعــة يف محكمــة االســتئناف مبنطقة مكة‬\n\n\n‫‪93‬‬\n\f‫املكرمــة جــرى منــا االطــاع علــى القــرار رقــم ‪ 34204877‬وتاريــخ‬\n‫‪1434/5/4‬ه ـ الصــادر مــن فضيلــة الشــيخ‪ ........‬القاضــي باحملكمــة‬\n‫اجلزائيــة مبكــة املكرمــة ‪ ،‬املتضمــن دعــوى املدعــي العــام ضــد‪........‬‬\n‫مينــي اجلنســية‪ ،‬املتهــم يف مخــدرات ‪ ،‬احملكــوم فيــه مبــا دون باطنــه ‪.‬‬\n‫وبدراســة القــرار وصــورة ضبطــه والالئحــة االعتراضيــة تقــررت املوافقــة‬\n‫علــى احلكــم ‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                             ‫وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                               ‫‪94‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":87,"source_page_end":94,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"8713af8645c436a198e28db40f5c5b535650fd31c6f17119146c95784f74e5d5","normalized_text_hash":"b96725e0a3b3695c6a0bd5d46fbb481a1ab2698d4a57d029478734bb8956cb84","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p87-34204877"},{"id":"cf5cc3a2-8e8b-52d2-99c9-3954166ad1c2","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -شراء وحيازة احلشيش املخدر بقصد التعاطي -شراء سيجارة ممزوجة باحلشيش املخدر بقصد التعاطي -حيازة حبوب الترامادول احملظورة بقصد التعاطي -تعاطي احلشيش املخدر واحلبوب احملظورة -التستر على مصدر املخدرات -إشتراك احلشيش مع اخلمر يف مناط احلكم -إقامة حد املسكر -تعزير املدعى عليه بالسجن واإلبعاد عن الباد -النزول عن احلد األدنى يف عقوبة السجن لقلة الكمية -رد دعوى.","document_number":"34191446","case_number":"34165108","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف باملنطقة الشرقية","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/17","year":"1434","subject":"مخدرات -شراء وحيازة احلشيش املخدر بقصد التعاطي -شراء سيجارة ممزوجة باحلشيش املخدر بقصد التعاطي -حيازة حبوب الترامادول احملظورة بقصد التعاطي -تعاطي احلشيش املخدر واحلبوب احملظورة -التستر على مصدر املخدرات -إشتراك احلشيش مع اخلمر يف مناط احلكم -إقامة حد املسكر -تعزير املدعى عليه بالسجن واإلبعاد عن الباد -النزول عن احلد األدنى يف عقوبة السجن لقلة الكمية -رد دعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪ 34191446:‬تاريخه‪1434/4/17:‬هـ‬\n                       ‫رقم الدعوى‪34165108:‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 341072759‬تاريخه‪1434/05/22 :‬هـ‬\n\n\n     ‫مخــدرات ‪ -‬شــراء وحيــازة احلشــيش املخــدر بقصــد التعاطــي‪ -‬شــراء‬\n     ‫ســيجارة ممزوجــة باحلشــيش املخــدر بقصــد التعاطــي ‪ -‬حيــازة حبــوب‬\n     ‫الترامــادول احملظــورة بقصــد التعاطــي ‪ -‬تعاطــي احلشــيش املخــدر‬\n     ‫واحلبــوب احملظــورة ‪ -‬التســتر علــى مصــدر املخــدرات ‪ -‬إشــتراك‬\n     ‫احلشــيش مــع اخلمــر يف منــاط احلكــم ‪ -‬إقامــة حــد املســكر‪ -‬تعزيــر‬\n     ‫املدعــى عليــه بالســجن واإلبعــاد عــن البــاد ‪ -‬النــزول عــن احلــد األدنــى‬\n                                 ‫يف عقوبــة الســجن لقلــة الكميــة ‪ -‬رد دعــوى‪.‬‬\n\n\n\n\n                     ‫قول الرسول صلى اهلل عليه وسلم ( كل مسكر حرام )‬\n                      ‫املادة ‪ 60‬من نظام مكافحة املخدرات واملؤثرات العقلية‬\n     ‫الفقــرة الثانيــة مــن املــادة ‪ 56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                           ‫العقليــة‬\n\n\n\n     ‫الئحــة الدعــوى العامــة ضــد املدعــى عليــه مقيــم بشــراء وحيــازة احلشــيش‬\n     ‫املخــدر وســيجارة ممزوجــة باحلشــيش املخــدر وحيــازة خمــس حبــات‬\n     ‫مــن حبــوب الترامــادول احملظــور بقصــد التعاطــي‪ ،‬تعاطــي احلشــيش‬\n     ‫املخــدر واحلبــوب احملظــورة‪ ،‬تســتر املدعــى عليــه علــى مصــدر املخــدرات‬\n\n‫‪95‬‬\n\f‫‪ -‬وطلــب املدعــي العــام إثبــات مــا أســند إليــه واحلكــم عليــه بالعقوبــة‬\n‫الــواردة يف الفقــرة األولــى مــن املــادة (‪ )41‬مــن نظــام مكافحة املخدرات‬\n‫واملؤثــرات العقليــة وإبعــاده خــارج البــاد بعــد تنفيــذ احلكــم بحقــه‬\n‫وبعقوبــة تعزيريــة لقــاء تســتره علــى مصــدر املخــدرات‪ ،‬مت القبــض علــى‬\n‫املدعــى عليــه بعــد االشــتباه بــه وبتفتيشــه عثــر معــه علــى ســجائر محتويــة‬\n‫علــى احلشــيش املخــدر وقطعتــن مــن احلشــيش املخــدر‪ ،‬إقــرار املدعــى‬\n‫عليــه بشــراء وحيــازة احلشــيش املخــدر والســيجارة املمزوجــة باحلشــيش‬\n‫وحيــازة احلبــوب احملظــورة بقصــد التعاطــي وتعاطيــه للحشــيش واحلبــوب‬\n‫احملظــورة‪ ،‬إنــكاره التســتر علــى مصدر املخــدرات‪ ،‬ثبوت إدانة املدعى‬\n‫عليــه بشــراء وحيــازة احلشــيش املخــدر والســيجارة املمزوجــة باحلشــيش‬\n‫املخــدر وتعاطيــه للحشــيش واحلبــوب احملظــورة‪ ،‬احلكــم بإقامــة حــد‬\n‫املســكر‪ ،‬تعزيــر املدعــى عليــه بالســجن واإلبعــاد عــن البــاد والنــزول‬\n‫عــن العقوبــة املقــررة نظام ـ ًا بالســجن لقلــة الكميــة‪ ،‬رد الدعــوى عــن‬\n‫طلــب إثبــات إدانــة املدعــى عليــه بالتســتر لعــدم ثبوتهــا‪ ،‬تصديــق احلكــم‬\n                            ‫مــن محكمــة االســتئناف باملنطقــة الشــرقية ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .............‬القاضــي يف احملكمــة‬\n‫اجلزائيــة باالحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n                                                                           ‫ّ‬\n‫احملكمــة اجلزائيــة يف محافظــة االحســاء برقــم ‪ 34165108‬وتاريــخ‬\n‫‪1434/04/10‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34879320‬وتاريــخ‬\n‫‪1434/04/10‬ه ـ ففــي يــوم األربعــاء املوافــق‪ 1434/04/17‬ه ـ افتتحت‬\n‫اجللســة الســاعة ‪ 09 : 00‬ووفيهــا حضــر املدعــي العــام ‪ .............‬املعمــد‬\n\n                                                                                      ‫‪96‬‬\n\f     ‫بالترافــع أمــام هــذه احملكمــة مبوجــب خطــاب ســعادة رئيــس دائــرة‬\n     ‫التحقيق واالدعاء العام مبحافظة االحســاء ذي الرقم ‪ .............‬والتاريخ‬\n     ‫‪ 1433/12/01‬ه ـ وادعــى ضــد احلاضــر معــه‪ .............‬مصــري اجلنســية‬\n     ‫مبوجــب رخصــة اقامــة رقــم ‪.............‬أنــه بتاريــخ ‪1434/2/17‬ه ـ وأثنــاء‬\n     ‫قيــام الدوريــات األمنيــة بعملهــا علــى طريــق الدمــام الريــاض الســريع مت‬\n     ‫اســتيقاف ســيارة مــن نــوع ‪ .......‬صنــع عــام ( ‪.......‬م ) حتمــل اللوحــة رقــم‬\n     ‫(‪ ).............‬بقيــادة املدعــى عليــه ‪ ،‬وبطلــب إثباتــه اتضــح عليــه االرتبــاك‬\n     ‫الشــديد ‪ ،‬وبتفيــش املركبــة ضبــط يف الــدرج الــذي بــن املرتبتــن علــى‬\n     ‫ســيجارة يحتمــل أن تكــون ممزوجــة باحلشــيش املخــدر تــزن ( ‪1‬جــم )‬\n     ‫جــرام واحــد ‪ ،‬وقطعتــن يحتمــل أن تكونــا مــن احلشــيش املخــدر بلــغ‬\n     ‫وزنهمــا ( ‪ 3‬جــم ) ثالثــة جرامــات‪ ،‬وعــدد (‪ )5‬خمــس حبــات يحتمــل أن‬\n                                                   ‫تكــون مــن حبــوب الترامــادول‪.‬‬\n     ‫وباســتجوابه أقــر بصحــة واقعــة القبــض والضبــط وبشــرائه و حيازتــه‬\n     ‫للحشــيش املخــدر وحبــوب الترامــادول مــن شــخص اليعــرف اســمه‬\n                               ‫بقصــد التعاطــي وتعاطيــه لنوعهمــا يف الســابق‪.‬‬\n     ‫وقــد أثبــت التقريــر الكيمــاوي الشــرعي رقــم (‪957‬ك ش) لعام ‪1434‬هـ‬\n     ‫إيجابيــة عينــة القطعتــن املضبوطتــن والســجارة املضبوطــة للحشــيش‬\n     ‫املخــدر املــدرج يف اجلــدول(‪ )1‬فئــة (أ) مــن نظــام مكافحــة املخــدرات‬\n     ‫واملؤثــرات العقليــة ‪ ،‬كمــا أثبــت التقريــر إيجابيــة احلبــوب املضبوطــة‬\n     ‫لعقــار الترامــادول احملظــور واملــدرج يف اجلــدول (‪ )1‬فئــة (هــ) مــن نظــام‬\n                                        ‫مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n     ‫وانتهــى التحقيــق معــه إلــى توجيــه االتهــام ل ــه بشــراء وحيــازة قطعتــن‬\n     ‫مــن احلشــيش املخــدر بلــغ وزنهمــا (‪ )3‬ثالثــة جرامــات وســيجارة ممزوجــة‬\n\n\n‫‪97‬‬\n\f‫جرامــا واحـ ًـدا وحيــازة عــدد (‪ )5‬خمــس‬  ‫ً‬     ‫باحلشــيش املخــدر بلــغ وزنهــا (‪)1‬‬\n‫حبــات مــن حبــوب الترامــادول احملظــورة بقصــد التعاطــي وتعاطيــه‬\n‫لنوعهمــا يف الســابق‪ ،‬املجــرم مبوجــب املــادة ( الثالثــة) مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم‬\n        ‫(م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ وتســتره علــى مصــدر املخــدرات‪.‬‬\n                                                   ‫وذلك لألدلة والقرائن التالية ‪:‬‬\n‫‪ -1‬إقــراره املنــوه عنــه املــدون علــى الصفحــة رقــم ( ‪ )2،1‬مــن دفتــر‬\n                                                       ‫التحقيــق لفــة رقــم(‪.)........‬‬\n                          ‫‪ -2‬ماجاء يف محضر الضبط املرفق لفة رقم (‪.)4‬‬\n‫‪ -3‬التقريــر الكيمــاوي الشــرعي املنــوه عنــه ‪ ،‬واملرفــق علــى اللفــة رقــم‬\n                                                                               ‫(‪. )........‬‬\n‫وحيــث إن مــا أقــدم عليــه املذكــور ‪ ،‬وهــو بكامــل أهليتــه املعتبــرة‬\n‫شــرع ًا ‪ ،‬فعــل مجــرم ومعاقــب علي ــه نظامـ ًا ؛ لــذا أطلــب إثبــات مــا أســند‬\n                                                   ‫إليــه واحلكــم عليــه مبــا يلــي‪-:‬‬\n‫‪-1‬بالعقوبــة الــواردة يف الفقــرة األولــى مــن املــادة (‪ )41‬مــن النظــام املشــار‬\n        ‫إليــه لقــاء مــا أســند إليــه باســتثناء التســتر علــى مصــدر املخــدرات ‪.‬‬\n‫‪2‬ـ بالعقوبــة الــواردة يف الفقــرة الثانيــة مــن املــادة (‪ )56‬مــن النظــام بإبعــاده‬\n                                         ‫خــارج البــاد بعــد تنفيــذ احلكــم بحقــه ‪.‬‬\n                       ‫‪-3‬بعقوبة تعزيرية لقاء تستره على مصدر املخدرات‪.‬‬\n‫وبســؤال املدعــى عليــه أجــاب قائــا مــا ذكــره املدعــي العــام مــن أنــه‬\n‫بتاريخ‪1434/2/17‬ه ـ مت اســتيقاف ســيارتي نــوع ‪ ......‬علــى طريــق‬\n‫الدمــام الريــاض وأنــه مت تفتيشــها وأنــه عثــر فيهــا علــى ســيجارة‬\n‫حشــيش تــزن جــرام واحــد وكذلــك علــى قطعتــي حشــيش يبلــغ وزنهــا‬\n\n\n                                                                                              ‫‪98‬‬\n\f     ‫ثــاث جرامــات وأنــه عثــر كذلــك علــى عــدد خمــس حبــات مــن حبــوب‬\n     ‫الترامــادول احملظــورة فهــذا كلــه صحيــح وهــي تعــود لــي وقصــدي مــن‬\n     ‫حيازتهــا االســتعمال وأنــا أســتعملها وأمــا مــا ذكــره املدعــي العــام مــن‬\n     ‫أننــي تســترت علــى مصدرهــا فهــذا غيــر صحيــح حيــث إننــي أخبرتهــم‬\n     ‫أننــي أخــذت مــن شــخص يف الريــاض ال أعــرف اســمه هكــذا أجــاب‬\n     ‫وبســؤال املدعــي العــام هــل لديــه بينــه علــى أن املدعــى عليــه تســتر علــى‬\n     ‫مصــدر هــذه احلبــوب فأجــاب قائــا نعــم لــدي بينــه وهــي أن املدعــى‬\n     ‫عليــه عندمــا مت ســؤاله عــن مصدرهــا يف دفتــر التحقيــق أجــاب بأنــه ال‬\n     ‫يعرفــه هكــذا أجــاب كمــا جــرى االطــاع علــى التقريــر الكيمائــي‬\n     ‫الشــرعي رقــم ‪.............‬واملتضمــن إيجابيــة العينــات جميعهــا للحشــيش‬\n     ‫حلبــوب الترامــادول احملظــورة واســتهالك جميــع العينــات يف التحليــل أ‪.‬هـ‬\n     ‫فبنــاء علــى مــا تقــدم مــن الدعــوى واالجابــه وإقــرار املدعــى عليــه باحليــازه‬\n     ‫للحشــيش واحلبــوب احملظــورة بقصــد االســتعمال وإنــكاره للتستســر‬\n     ‫علــى مصدرهــا وحيــث إن املدعــي العــام ال بينــه لــه علــى تســتره وحيــث‬\n     ‫إن احلشــيش يشــترك مــع اخلمــر يف منــاط احلكــم وللتقريــر الكيمــاوي‬\n     ‫الشــرعي ولقــول صلــى اهلل عليــه وســلم كل مســكر حــرام للذلــك‬\n     ‫كلــه فقــد ثبــت لــدي إدانــه املدعــى عليــه بحيــازة عــدد خمــس حبــات‬\n     ‫محظــورة وســيجارة حشــيش تــزن جــرام واحــد وقطعتــي حشــيش تــزن‬\n     ‫ثالثــة جرامــات بقصــد االســتعمال ولــم يثبــت لــدي إدانتــه بالتســتر علــى‬\n     ‫مصــدر احلبــوب وحكمــت عليــه مبــا يلــي أوال‪ :‬جلــد املدعــى عليــه ثمانــن‬\n     ‫جلــدة دفعــة واحــدة حــد املســكر ثانيــا‪ :‬ســجن املدعــى عليــه مــدة أربعــة‬\n     ‫أشــهر يحتســب منهــا مــده بقائــه بالســجن بخصــوص هــذه القضيــة وقــد‬\n     ‫نزلــت عــن العقوبــة املقــرره نظامــا وذلــك مبوجــب املــادة ‪ 60‬مــن نظــام‬\n\n\n‫‪99‬‬\n\f‫مكافحــة املخــدرات واملؤثــرات العقليــة نظــرا لقلــة الكميه ثالثــا‪ :‬إبعاد‬\n‫املدعــى عليــه مــن البــاد بعــد تنفيــذ مــدة محكوميتــه وذلــك مبوجــب‬\n‫الفقــرة الثانيــة مــن املــادة ‪ 56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة رابعــا‪ :‬رد دعــوى املدعــي العــام بخصــوص معاقبــه املدعــى عليــه‬\n‫علــى التســتر لعــدم ثبوتهــا هــذا مــا ظهــر لــي وبــه حكمــت وبعــرض ذلــك‬\n‫علــى املدعــي العــام قــرر املدعــي العــام اعتراضــه عليــه وطلــب رفعــه إلــى‬\n‫محكمــة االســتئناف بــدون الئحــه فأجبتــه لطلبــه وأمــا املدعــى عليــه‬\n               ‫فقــرر قناعتــه بــه وبــه ختمــت اجللســة يف متــام الســاعة ‪09: 30‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n‫لــدى احملكمــة برقــم ‪/341072759‬ج‪ 2‬وتاريــخ ‪1434/5/1‬ه ـ الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة اجلزائية مبحافظة األحســاء املكلف برقم‬\n‫‪ 34/879320‬وتاريــخ ‪1434/4/28‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشيخ‪.............‬املســجل برقــم ‪34191446‬‬\n‫وتاريــخ ‪1434/4/17‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد‪.............‬‬\n‫(مصــري اجلنســية) يف قضيــة مخــدرات وقــد تضمــن القــرار حكــم‬\n‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه‬\n‫وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم‪ .‬واهلل املوفــق وصلــى اهلل‬\n           ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/5/7‬هــ‪.‬‬\n\n\n\n\n                                                                                         ‫‪100‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":95,"source_page_end":100,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"a5fe3af12bb760346b00e617839d4b5cfd55efce027d2bf9c2d530574768b816","normalized_text_hash":"577d3f5408ea8bd688c5bd02d132478dd887fc6c5af44f68a2e9b8be4f829848","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p95-34191446"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"81094d5a-692d-5052-9873-46573ed6d816","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش بقصد التعاطي -تستر على مصدره - محاولة إدخال احلشيش إلى السجن -بينة غير موصلة -األصل براءة الذمة -عدم ثبوت الدعوى.","document_number":"34183868","case_number":"34154644","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/04/03","year":"1434","subject":"مخدرات -حيازة حشيش بقصد التعاطي -تستر على مصدره - محاولة إدخال احلشيش إلى السجن -بينة غير موصلة -األصل براءة الذمة -عدم ثبوت الدعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34183868:‬تاريخه ‪1434/04/03:‬هـ‬\n                  ‫رقم الدعوى ‪34154644:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34293613‬تاريخه‪1434/08/10:‬ه‬\n\n\n‫مخــدرات‪ -‬حيــازة حشــيش بقصــد التعاطــي ‪ -‬تســتر علــى مصــدره ‪-‬‬\n‫محاولــة إدخــال احلشــيش إلــى الســجن‪ -‬بينــة غيــر موصلــة‪ -‬األصــل‬\n                                 ‫بــراءة الذمــة ‪ -‬عــدم ثبــوت الدعــوى‪.‬‬\n\n\n\n\n                                                       ‫األصل براءة الذمة‪.‬‬\n\n\n\n‫دعــوى املدعــي العــام ضــد املدعــى عليــه تتضمــن طلــب إثبــات إدانتــه‬\n‫بحيــازة احلشــيش املخــدر بقصــد التعاطــي وإدخالــه الســجن والتســتر‬\n‫علــى مصــدره ‪ ،‬واحلكــم عليــه بعقوبــة الســجن طبقــا لنظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة ونظــام الســجن والتوقيــف وعقوبــة تعزيريــة‬\n‫للتســتر ‪ ،‬حيــث أنــه مت االشــتباه بحــركات غيــر طبيعيــة صــدرت مــن‬\n‫الســجني املدعــى عليــه أثنــاء نقلــه مت تفتيــش املنطقــة احمليطــة مبــكان‬\n‫وقوفــه فعثــر فيهــا علــى ثالثــة أصابــع من احلشــيش املخدر وأثبــت التقرير‬\n‫الكيميائــي الشــرعي إيجابيــة العينــة املرســلة للحشــيش املخدر‪،‬كمــا‬\n‫أنكــر أمــام احملكمــة مــا أســنده إليــه املدعي العــام‪ ،‬فطلبت احملكمة‬\n‫مــن املدعــي العــام تقــدمي بيناتــه وقــررت ســماع شــهادة شــهود محضــر‬\n‫القبــض فشــهد أحدهــم بــأن املضبوطــات كانــت مرميــة علــى األرض‬\n\n                                                                                 ‫‪60‬‬\n\f     ‫وتبعــد ثالثــة أمتــار عــن املدعــى عليــه‪ ،‬فقضــت احملكمــة بعــدم ثبــوت‬\n     ‫دعــوى املدعــي العــام جتــاه املدعــى عليــه‪ ،‬وقنــع املدعــى عليــه باحلكــم‬\n     ‫وعــارض املدعــي العــام عليــه‪ ،‬قــررت محكمــة االســتئناف املصادقــة‬\n                                                                     ‫علــى احلكــم‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي‬\n     ‫أنــا ‪ ........‬القاضــي باحملكمــة اجلزائيــة باخلبــر وبنــاء علــى املعاملــة‬\n     ‫احملالــة لنــا مــن فضيلــة رئيــس احملكمــة اجلزائيــة يف محافظــة اخلبــر‬\n     ‫برقــم ‪ 34154644‬وتاريــخ ‪1434/04/03‬ه ـ املقيــدة باحملكمــة‬\n     ‫برقــم ‪ 34823368‬وتاريــخ ‪1434/04/03‬ه ـ ففــي يــوم االثنــن املوافــق‬\n     ‫‪1434/04/08‬ه ـ افتتحــت اجللســة الســاعة ‪ 08 :00‬وفيهــا قــدم املدعــي‬\n     ‫العــام الئحــة دعــوى عامــه ضــد ‪ ........‬ســعودي اجلنســية بالســجل املدنــي‬\n     ‫ا فيهــا إنــه باالطــاع علــى احملضــر املعــد مــن قبــل وحــدة‬\n                                                                     ‫رقــم ‪ ........‬قائـ ً‬\n     ‫األمــن واحلمايــة بشــعبة ســجن اخلبــر تبــن أنــه يف يــوم الثالثــاء املوافــق‬\n     ‫‪1434/2/5‬ه ـ توفــرت معلومــة بــأن الســجني‪ ........‬يف جنــاح ‪ 2‬يعتــزم‬\n     ‫إدخــال كميــة مخــدرات إلــى العنابــر اجلديــدة عنــد نقــل الســجناء وعليــه‬\n     ‫مت اســتدعاء الســجني املشــار إليــه أعــاه أثنــاء نقــل الســجناء ولوحــظ‬\n     ‫عليــه االرتبــاك واحلركــة غيــر طبيعيــة حيــث جلــس ونهــض بشــكل‬\n     ‫ســريع عــدت مــرات وعنــد تفتيشــه وتفتيــش املنطقــة احمليطــة بــه وجــد‬\n     ‫ثــاث أصابــع قــد ألصقــت بالصــق نايلون يشــتبه أن تكون من احلشــيش‬\n     ‫املخــدر بلــغ وزنهــا (‪ )52.5‬جــرام باإلضافــة لعــدد مــن ورق الشــام وقــد مت‬\n     ‫ضبــط الكميــة املشــار إليهــا قبــل دخولهــا العنابــر اجلديــدة‪ ،‬وقــد ورد‬\n\n‫‪61‬‬\n\f‫التقرير الكيماوي الشرعي رقم ( ‪ 954‬ك ش) وتاريخ ‪1434/2/27‬هـ‬\n‫املتضمــن إيجابيــة عينــة القطــع املضبوطــة مــادة احلشــيش املخــدر واملدرج‬\n‫يف اجلــدول األول فئــة (أ) امللحــق بنظــام مكافحــة املخــدرات وبســماع‬\n‫أقــوال املتهــم األوليــة أنكــر عائديــه احلشــيش املضبــوط لــه وذكــر بأنــه‬\n‫يتعاطــى الهرويــن املخــدر منــذ اثنــا عشــر ســنة تقريب ـ ًا وأن آخــر مــرة‬\n‫تعاطــى فيهــا الهرويــن قبــل ســجنه وانتهــى التحقيــق إلــى توجيــه االتهــام‬\n‫لــه‪ ،‬بحيــازة ثالثــة أصابــع بلــغ وزنهــا (‪ )52.5‬اثنــان وخمســون جرام ـ ًا‬\n‫وخمســة مــن عشــرة مــن اجلــرام مــن احلشــيش املخــدر بقصــد التعاطــي‬\n‫وإدخالهــا الســجن والتســتر علــى مصدرهــا وذلــك لألدلــة والقرائــن‬\n‫التاليــة‪ -1 :‬محضــر البــاغ والقبــض والتفتيــش املعــد مــن قبــل وحــدة‬\n‫األمــن واحلمايــة بشــعبة ســجن اخلبــر املشــار إليــه لفــة رقــم (‪ -2)2‬التقريــر‬\n‫الكيمــاوي الشــرعي املشــار إليــه واملرفــق علــى اللفــة رقــم (‪)13‬وحيــث‬\n‫إن مــا أقــدم عليــه املتهــم املذكــور ‪-‬وهــو بكامــل أهليتــه املعتبــرة‬\n‫شــرعا‪ -‬فعــل محــرم ومعاقــب عليــه شــرع ًا ونظام ـ ًا اطلــب اآلتــي‪ :‬أوالً‪:‬‬\n‫وفقــا للفقــرة رقــم (‪ )2‬مــن املــادة رقــم (‪ )3‬مــن نظــام‬\n                                                          ‫إثبــات مــا أســند إليــه ً‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة واملــادة رقــم (‪ )29‬مــن نظــام‬\n‫الســجن والتوقيــف واحلكــم عليــه باالتــي‪ -1:‬بعقوبــة الســجن الــواردة‬\n‫بالفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )41‬مــن النظــام مع مراعــات ما تقضي‬\n‫بــه املــادة (‪ )29‬مــن نظــام الســجن والتوقيــف واحلكــم بالعقوبــة األشــد‬\n‫وفــق مــا ورد بالفقــرة (‪ )2‬مــن املــادة (‪ )62‬مــن نظــام املخــدرات ‪ -2‬بعقوبــة‬\n‫تعزيريــة لقــاء تســتره علــى مصــدر احلشــيش املخــدر ‪ -3‬تشــديد العقوبــة‬\n‫عليــه لكثــرة ســوابقه اســتنادا لبرقيــة صاحــب الســمو امللكــي نائــب‬\n‫وزيــر الداخليــة رقــم (‪ )93958/5/1‬وتاريخ ‪1429/8/23‬هـ هذه دعواي‬\n\n\n                                                                                         ‫‪62‬‬\n\f     ‫وبســؤال املدعــى عليــه عــن الدعــوى أجــاب بقولــه مــا جــاء يف الدعــوى من‬\n     ‫حيازتــي ثــاث أصابــع مــن احلشــيش املخــدر بقصــد التعاطــي وإدخالهــا‬\n     ‫للســجن والتســتر علــى مصدرهــا هــذا غيــر صحيــح والصحيــح أنــه يف‬\n     ‫يــوم احلادثــة مت إخــراج جميــع الســجناء يف جنــاح رقم(‪)2‬وكذلــك بعــض‬\n     ‫الســجناء يف جنــاح رقــم(‪)3‬و(‪)4‬مت إخراجهــم إلــى الســاحة اخلارجيــة وأنــا‬\n     ‫كنــت يف اجلنــاح رقم(‪)2‬وذلــك ألجــل تفتيــش الســجناء واحــد ًا واحــد ًا‬\n     ‫ثــم نقلنــا إلــى عنابــر جديــدة وقــد مت تفتيــش الســجناء وكنــت أنــا آخــر‬\n     ‫واحد مت تفتيشــه ولم يجدوا معي أي شــيء من املمنوعات عند تفتيشــي‬\n     ‫كمــا لــم يعثــروا مبفرشــي الــذي كنــت أحملــه معــي علــى أي شــيء مــن‬\n     ‫املمنوعــات وبعــد حتركــي ألجــل االنتقــال للعنبــر اجلديــد ذكــر أحــد‬\n     ‫العســاكر أنــه وجــد أصابــع حشــيش مخــدر يف املمــر املجــاور للســاحة‬\n     ‫وهــذا احلشــيش ليــس لــي عالقــة بــه فهــو ال يعــود لــي وال أعلــم ملــن يعــود‬\n     ‫وقــد يكــون أحــد الســجناء قــام برمــي هــذا احلشــيش املخــدر قبــل مــروره‬\n     ‫عنــد التفتيــش علمـ ًا بأنــي موقــوف يف قضيــة اســتعمال هيرويــن هكــذا‬\n     ‫أجــاب وبســؤال املدعــي العــام البينــة علــى دعــواه قــال بينتــي مــا ذكــرت‬\n     ‫فأقفلــت اجللســة عنــد الســاعة الثامنــة والنصــف لطلــب معــدي محضــر‬\n     ‫القبــض والتفتيــش وصلــى اهلل وســلم علــى نبينــا محمــد احلمــد هلل وحــده‬\n     ‫وبعــد ثــم إنــه يف هــذا اليــوم الثالثــاء ‪1434/4/9‬ه ـ الســاعة العاشــرة‬\n     ‫إال ربــع افتتحــت اجللســة بحضــور املدعــى عليــه كمــا حضــر الشــاهد‬\n     ‫‪ ........‬ســعودي بالســجل املدنــي رقــم (‪ )........‬وهــو أحــد معــدي محضــر‬\n     ‫القبــض والتفتيــش وبســؤاله عمــا لديــه مــن شــهادة قــال إنــي أعمــل‬\n     ‫عســكري يف ســجن اخلبــر يف قســم مكافحــة املخــدرات وأشــهد هلل‬\n     ‫أنــه يف تاريــخ ‪1434/2/23‬ه ـ مت إخــراج ســجناء اجلنــاح رقــم (‪ )2‬ورقــم‬\n\n\n‫‪63‬‬\n\f‫(‪ )3‬إلــى ســاحة الســجن ألجــل تفتيشــهم ثــم نقلهــم مــن العنابــر القدميــة‬\n‫إلــى العنابــر اجلديــدة وقــد قمــت أنــا بتفتيــش املدعــى عليــه وكان مــن‬\n‫أواخــر الســجناء الذيــن مت تفتيشــهم وأثنــاء تفتيشــي لــه وجــدت ثــاث‬\n‫أصابــع حشــيش مخــدر مــع ورق شــام كانــت مرميــة علــى األرض علــى‬\n‫بعــد ثــاث أمتــار تقريب ـ ًا مــن املدعــى عليــه لكنــي ال أعلــم هــل مــن‬\n‫قــام برميهــا املدعــى عليــه أم شــخص آخــر مــن الســجناء املوجوديــن يف‬\n‫الســاحة وعنــد ذلــك قمــت باســتدعاء زمالئــي هــذا مــا لــدي مــن شــهادة‬\n‫فاحلشــيش املخــدر أنــا مــن وجــده ولــم يكــن بحــوزة املدعــى عليــه إمنــا‬\n‫كان مرمي ـ ًا علــى األرض علــى بعــد ثالثــة أمتــار مــن املدعــى عليــه‬\n‫وأمــا زميلــي فقــد حضــرا بعــد أن عثــرت علــى احلشــيش املخــدر هكــذا‬\n‫شــهد وبعــرض الشــاهد وشــهادته علــى املدعــى عليــه قــال الشــاهد رجــل‬\n‫مســتقيم وشــهادته صحيحــة فاحلشــيش املخــدر لــم يكــن بحوزتــي وإمنــا‬\n‫كان مرميـ ًا علــى األرض علــى بعــد ثالثــة أمتــار عنــي وليــس عائــد ًا لــي‬\n‫وال أعلــم ملــن يعــود وقــد ذكــر الشــاهد بأنــه لــم يشــاهدني أرمــي هــذا‬\n‫احلشــيش هكــذا قــرر بعــد ذلــك جــرى الرجــوع إلــى اللفــة رقــم (‪)13‬‬\n‫وتضمنــت التقريــر الكيمــاوي الشــرعي وهــو كمــا ذكــر املدعــي‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى اإلجابــة وحيــث أنكــر‬ ‫العــام يف دعــواه فبنـ ً‬\n‫املدعــى عليــه مــا نســب إليــه وحيــث إنــه ال بينــة علــى الدعــوى وقــد حضــر‬\n‫الشــاهد وأفــاد بأنــه هــو مــن وجــد قطعــة احلشــيش املخــدر ولــم تكــن‬\n‫بحــوزة املدعــى عليــه إمنــا كانــت مرميــة عنــه علــى بعــد ثالثــة أمتــار وال‬\n‫يعلــم الشــاهد مــن قــام برمــي هــذا احلشــيش املخــدر كمــا أفــاد بــأن‬\n‫زميليــه حضــرا بعــد أن وجــد هــو قطعــة احلشــيش املخــدر وحيــث إن‬\n‫األصــل بــراءة الذمــة والســاحة التــي وجــد بهــا احلشــيش املخــدر كان‬\n\n\n                                                                                        ‫‪64‬‬\n\f     ‫يتواجــد بهــا مجموعــة مــن الســجناء ألجــل تفتيشــهم لــذا فقــد حكمــت‬\n     ‫بعــدم ثبــوت دعــوى املدعــي العــام جتــاه املدعــى عليــه ‪ .......‬مــن حيــازة‬\n     ‫احلشــيش املخــدر وإدخالــه الســجن والتســتر علــى مصــدره وبعــرض‬\n     ‫احلكــم قنــع املدعــى عليــه ولــم يقنــع املدعــي العــام مكتفيـ ًا مبــا قــدم يف‬\n     ‫الئحــة الدعــوى وأقفلــت اجللســة الســاعة العاشــرة والنصــف وصلــى اهلل‬\n                                                            ‫وســلم علــى نبينــا محمــد‪.‬‬\n     ‫احلمــدهلل وحــده وبعــد ‪ ...‬فقــد أطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n     ‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة‬\n     ‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة اخلبــر برقــم‬\n     ‫‪ 34/823368‬وتاريــخ ‪1434/4/13‬ه ـ املقيــدة لــدى احملكمــة برقــم‬\n     ‫‪ 34/929321‬وتاريــخ ‪1434/4/15‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n     ‫فضيلــة القاضــي باحملكمــة الشــيخ‪ .......‬املســجل برقــم ‪34183868‬‬\n     ‫وتاريــخ ‪1434/4/9‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد ‪ ....... /‬يف‬\n     ‫قضيــة مخــدرات وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون‬\n     ‫ومفصــل فيــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه واوراق املعاملــة قررنــا‬\n     ‫املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/5/14‬ه ـ ‪.‬‬\n\n\n\n\n‫‪65‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":60,"source_page_end":65,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c49372c8a6a1b43bf29a629de148453b521cea939de2a3d6a15bee183e1fc3f3","normalized_text_hash":"5511a159c9fc65f724d490cb2531d351a1e4d5e9b6b8697cda2a5b2937d36205","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p60-34183868"},{"id":"248ab98a-9416-5a89-bc96-bc3bf8fe5a8d","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حبوب محظورة بقصد التعاطي -إدانة -نزول عن احلد األدنى للعقوبة.","document_number":"34196715","case_number":"34161373","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":"الدائرة اجلزائية الرابعة رقم 34246641يف 1434/6/20ه املتضمن","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/04/23","year":"1434","subject":"مخدرات -حيازة حبوب محظورة بقصد التعاطي -إدانة -نزول عن احلد األدنى للعقوبة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34196715:‬تاريخه ‪1434/04/23:‬هـ‬\n                   ‫رقم الدعوى ‪34161373:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34293613‬تاريخه‪1434/08/10:‬هـ‬\n\n\n‫مخــدرات‪ -‬حيــازة حبــوب محظــورة بقصــد التعاطــي‪ -‬إدانــة‪ -‬نــزول عــن‬\n                                                 ‫احلــد األدنــى للعقوبــة‪.‬‬\n\n\n\n\n‫املــواد (‪ )3‬و(‪ )41‬و(‪ )56‬و(‪ )60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                              ‫العقليــة‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بإدانتــه بحيازة حبــوب الزنكس‬\n‫احملظــورة بقصــد التعاطــي ‪ ،‬واحلكــم عليــه بعقوبــة الســجن واملنــع مــن‬\n‫الســفر طبقــا لنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ ،‬حيــث إنــه‬\n‫مت تفتيــش املدعــى عليــه بعــد اســتيقاف الســيارة التــي كان يركبهــا‬\n‫فعثــر بحوزتــه علــى حبــوب يشــتبه أن تكــون محظــورة‪ ،‬أثبــت التقريــر‬\n‫الكيميائــي الشــرعي إيجابيــة العينــة املرســلة ملركــب البــرازوالم‬\n‫احملظــور‪ ،‬أقــر حتقيقـ ًا بحيازتــه للحبــوب املضبوطــة بقصــد التعاطــي‪،‬‬\n‫وأنكــر أمــام احملكمــة مــا أســنده إليــه املدعــي العــام ودفــع بــأن احلبــة‬\n‫عائــدة ألخيــه املريــض نفســيا وأنــه يحوزهــا ملنعــه مــن اســتخدامها‬\n‫بطريقــة خاطئــة‪ ،‬وطلبــت احملكمــة مــن املدعــى عليــه تقــدمي إثبــات علــى‬\n‫مــا دفــع بــه فعجــز عــن ذلــك‪ ،‬فقضــت احملكمــة بإدانــة املدعــى عليــه مبا‬\n\n                                                                                     ‫‪66‬‬\n\f     ‫نســب إليــه وقــررت ســجنه ملــدة شــهر ومنعــه مــن الســفر خــارج اململكــة‬\n     ‫ملــدة ســنتني‪ ،‬قنــع املدعــى عليــه باحلكــم وعــارض املدعــي العــام عليــه‬\n                        ‫وقــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة اجلزائيــة‬\n     ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n     ‫اجلزائيــة بالريــاض برقــم ‪ 34161373‬وتاريــخ ‪1434/04/08‬ه ـ املقيــدة‬\n     ‫باحملكمــة برقــم ‪ 34858791‬وتاريــخ ‪1434/04/08‬ه ـ ففــي يــوم‬\n     ‫األربعــاء املوافق‪1434/04/17‬ه ـ افتتحــت اجللســة الســاعة ‪01 :00‬‬\n     ‫وفيهــا حضــر املدعــي العــام وادعــى علــى ‪ ........‬ســعودي اجلنســية بقولــه‬\n     ‫انــه بتاريــخ ‪1434/2/18‬ه ـ مت القبــض علــى املذكــور مــن قبــل إحــدى‬\n     ‫فــرق دوريــات األمــن مبدينــة الريــاض حيــث شــاهدت ســيارة مــن نــوع‬\n     ‫(‪ )........‬حتمــل اللوحــة رقــم(‪ ).....‬بقيــادة املدعــو‪ ........‬ويرافقــه املذكــور‬\n     ‫وباالشــتباه بهــا مت اســتيقافها ولوحــظ انبعــاث رائحــة منهــا يشــتبه أن‬\n     ‫تكــون حشــيش مخــدر وبتفتيــش املذكــور عثــر بحوزتــه علــى قصديــرة‬\n     ‫بداخلهــا (‪ )4‬أربــع حبــات مكتــوب عليهــا (زينكــس) يشــتبه أن‬\n     ‫تكــون محظــورة وقــد أثبــت التقريــر الكيميائــي الشــرعي الصــادر‬\n     ‫مــن مركــز مراقبــة الســموم والكيميــاء الطبيــة الشــرعية بالريــاض‬\n     ‫املرفــق رقــم (‪ )........‬لعــام ‪1434‬ه ـ احتــواء احلبــوب املضبوطــة ملركــب‬\n     ‫البــرازوالم وهــو مــن املــواد املهدئــة واملدرجــة باجلــدول رقم(‪)2‬فئــة (د)‬\n     ‫امللحــق بــذات النظــام‪ .‬وبســماع أقــوال املذكــور أقــر بحيــازة مــا ضبــط‬\n     ‫مــن حبــوب محظــورة بقصــد التعاطــي وذكــر بأنــه حصــل عليهــا مــن‬\n\n‫‪67‬‬\n\f‫أخيــه‪ .‬وباســتجوابه اعتــرف بحيــازة مــا ضبــط مــن حبــوب محظــورة‬\n‫بقصــد التعاطــي وأنــه حصــل عليهــا مــن أخيــه املريــض نفســي ًا دون‬\n‫علمــه وقــد أســفرت إجــراءات التحقيــق عــن توجيــه االتهــام إلــى‪........‬‬\n‫بحيــازة (‪ )4‬أربــع حبــات مــن حبــوب البــرازوالم املهدئــة احملظــورة بقصــد‬\n‫التعاطــي املجــرم مبوجــب املــادة (الثالثــة) مــن نظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ‬\n‫‪1426/7/8‬هـ‪ .‬وذلك لألدلة والقرائن التالية‪ -1 :‬مــا تضمنــه اعترافــه‬\n‫يف محضــر ســماع األقــوال األوليــة املنــوه عنــه املــدون علــى الصفحــة‬\n‫رقــم(‪ )4‬املرفــق لفــة رقــم (‪ -2 .)1‬مــا تضمنــه محضــر القبــض املنــوه‬\n‫عنــه املرفــق لفــة رقــم (‪ -3 )2‬مــا تضمنــه التقريــر الكيميائــي الشــرعي‬\n‫املنــوه عنــه املرفــق لفــة رقــم (‪ )24‬وحيــث أن مــا أقــدم عليــه املذكــور‬\n‫فعــل محــرم ومعاقــب عليــه شــرعا ونظامـ ًا لــذا أطلــب إثبــات إدانتــه مبــا‬\n‫أســند إليــه واحلكــم عليــه بالتالــي‪ )1 :‬بالعقوبــة الــواردة بالفقــرة (‪ )1‬مــن‬\n‫املــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة لقــاء مــا‬\n‫أســند إليــه‪ )2 .‬منعــه مــن الســفر إلــى خــارج اململكــة بعــد تنفيــذ عقوبــة‬\n‫ســجنه وفقـ ًا للفقــرة (األولــى) مــن املــادة (‪ )56‬مــن ن ــفس النظــام املشــار‬\n‫إليــه هــذه دعــواي وبعــرض الدعــوى علــى املدعــى عليــه أجــاب مــا ذكــره‬\n‫املدعــي العــام صحيــح مــن ناحيــة حيازتــي (‪ )4‬ألربــع حبــات مــن حبــوب‬\n‫البــرازوالم املهدئــة وهــي ال تعــود لــي وإمنــا ألخــي املريــض النفســي كانت‬\n‫معــي لكــي ال يســتخدمها أخــي املريــض بطريقــة خاطئــة هكــذا أجــاب‬\n‫وبســؤاله هــل مت صــرف احلبــوب املذكــورة مــن جهــة مختصــة فقــال نعــم‬\n‫صرفــت لــه مــن مستشــفى وأطلــب إمهالــي إلحضــار مــا يثبــت ذلــك ثــم‬\n‫رفعــت اجللســة لذلــك ويف يــوم الثالثــاء املوافق‪1434/04/23‬ه ـ افتتحــت‬\n\n\n                                                                                      ‫‪68‬‬\n\f     ‫اجللسة الساعة ‪ 12.45‬وفيها حضر املدعي العام واملدعى عليه وبسؤال‬\n     ‫املدعــى عليــه عــن بينتــه فقــال ال بينــة لــدي علــى أن أخــي قــد صــرف لــه‬\n     ‫العــاج مــن قبــل مستشــفى حكومــي وبســؤال املدعــى عليــه عمــا ورد يف‬\n     ‫إقــراره بأنــه كان ينــوي تعاطــي احلبــوب فأجــاب بأنــي قلــت ذلــك خوفــا‬\n     ‫منهــم فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث صــادق املدعــى‬\n     ‫عليــه علــى أنــه أقــر لــدى جهــات التحقيــق أنــه كان ينــوي تعاطــي احلبــوب‬\n     ‫احملظــورة وملــا نــص عليــه التقريــر الكيميائــي املرفــق ومــا نصــت عليــه‬\n     ‫املــادة رقــم (‪ )56-41‬مــن نظــام مكافحــة املخــدرات لذلــك كلــه‬\n     ‫فقــد ثبــت لــدي إدانــة املدعــى عليــه بحيــازة (‪ )4‬أربــع حبــات مــن حبــوب‬\n     ‫البــرازوالم املهدئــة احملظــورة بقصــد التعاطــي املجــرم مبوجــب املــادة‬\n     ‫(الثالثــة) مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر‬\n     ‫باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426 / 7 / 8‬ه ـ ونظــرا لعــدم‬\n     ‫وجــود ســوابق مســجلة عليــه ولقلــة الكميــة املضبوطــة معــه وملــا نصــت‬\n     ‫عليــه املــادة رقــم (‪ )60‬مــن نظــام مكافحــة املخــدرات لذلــك كلــه فقــد‬\n     ‫حكمــت بســجنه ملــدة شــهر ومنعــه مــن الســفر خــارج اململكــة ملــدة‬\n     ‫ســنتني بعــد انتهــاء محكوميتــه وبعــرض ذلــك علــى املدعــي العــام قــرر‬\n     ‫عــدم القناعــة وطلــب متييــز احلكــم بــدون الئحــة وقــرر املدعــى عليــه‬\n     ‫القناعــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n     ‫وصحبــه وســلم‪ .‬حــرر يف ‪ 1434/04/23‬ه ـ احلمــد هلل وحــده وبعــد ففــي‬\n     ‫يــوم الثالثــاء املوافــق‪ 1434/07/18‬ه ـ افتتحــت اجللســة الســاعة ‪2.00‬‬\n     ‫وقــد عــادت املعاملــة مــن محكمــة االســتئناف بالريــاض وبرفقهــا قــرار‬\n     ‫الدائــرة اجلزائيــة الرابعــة رقــم ‪ 34246641‬يف ‪1434/6/20‬ه ـ املتضمــن‬\n     ‫أنــه لوحــظ مــا يلــي ‪ -1‬لــم يثبــت فضيلتــه اإلدانــة مــن عدمهــا ‪ -2‬لــم يبــن‬\n\n\n‫‪69‬‬\n\f‫بدايــة ســجن املدعــى عليــه ومضمــون التقريــر الكيميائــي ‪ -3‬لــم يوقــع‬\n‫الكاتــب علــى ختــم طبــق األصــل يف صــورة الضبــط أ‪.‬ه ـ عليــه أجيــب‬\n‫أصحــاب الفضيلــة أنــه مت إثبــات إدانــة املدعــى عليــه مبــا أســند إليــه‬\n‫قبــل احلكــم عليــه ‪ ،‬وباإلمــكان الرجــوع إلــى احلكــم والتحقــق مــن‬\n‫ذلــك ‪ ،‬وأمــا بدايــة الســجن فيســجن بعــد حســم مــدة إيقافــه بســبب هــذه‬\n‫القضيــة ومضمــون التقريــر الكيميائــي الشــرعي الصــادر مــن مركــز‬\n‫مراقبــة الســموم والكيميــاء الطبيــة الشــرعية بالريــاض املرفــق رقــم‬\n‫(‪ )........‬لعــام ‪1434‬ه ـ هــو احتــواء احلبــوب املضبوطــة ملركــب البــرازوالم‬\n‫وهــو مــن املــواد املهدئــة واملدرجــة باجلــدول رقم(‪)2‬فئــة (د) امللحــق بــذات‬\n‫النظــام‪ ،‬وقــد مت اتخــاذ الــازم حيــال املالحظــة الثالثــة وبــاهلل التوفيــق‪،‬‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف‬\n                                                               ‫‪1434/07/18‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدئــرة اجلزائيــة‬\n‫الرابعــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن‬\n‫فضيلــة رئيــس احملكمــة اجلزائيــة بالريــاض برقــم ‪341583501‬‬\n‫وتاريــخ ‪1434/7/26‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة‬\n‫القاضــي باحملكمــة الشــيخ ‪ ... /‬املســجل برقــم ‪ 34196715‬وتاريــخ‬\n‫‪1434/4/23‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد ‪ /‬املدعــى عليــه‬\n‫التهامــه بقضيــة مخــدرات علــى النحــو املوضــح بالقــرار املتضمــن‬\n‫حكــم فضيلتــه مبــا هــو مــدون بــه وحيــث ســبق دراســة القــرار‬\n‫وصــورة ضبطــه وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلته‬\n‫القاضــي وأحلقــه بالقــرار وصــورة ضبطــه وأوراق املعاملــة وباالطــاع‬\n‫علــى مــا أجــاب بــه فضيلتــه القاضــي أحلقــه بالقــرار وصــورة ضبطــه‬\n\n\n                                                                                     ‫‪70‬‬\n\f     ‫بنــاء علــى قرارنــا رقــم ‪ 34246641‬وتاريــخ ‪1434/6/20‬ه ـ قــررت‬\n     ‫الدائــرة باألكثريــة املصادقــة علــى احلكــم بعــد اإلجــراء األخيــر واهلل‬\n              ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪71‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":66,"source_page_end":71,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"dd20fbae8253f2199b9d70a2e140c9e11e41b7b13b30c7824222f50fc2fe53c5","normalized_text_hash":"7f28bf9188eb7d20fd728bd4788a72454ee0828f27541cc8926f2e61c6f7cc38","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p66-34196715"},{"id":"2d7110ef-fc32-5835-b146-5480dcc4c0e0","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حبة من احلبوب احملظورة بقصد التعاطي - تعاطي احلبوب احملظورة -قيادة السيارة حتت تأثير احلبوب احملظورة -عقوبة عائدة للجهة املختصة .","document_number":"34220034","case_number":"34162926","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/05/22","year":"1434","subject":"مخدرات -حيازة حبة من احلبوب احملظورة بقصد التعاطي - تعاطي احلبوب احملظورة -قيادة السيارة حتت تأثير احلبوب احملظورة -عقوبة عائدة للجهة املختصة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34220034 :‬تاريخه ‪1434/05/22 :‬هـ‬\n                    ‫رقم الدعوى ‪34162926:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34252528‬تاريخه‪1434/6/25 :‬هـ‬\n\n\n ‫مخــدرات ‪ -‬حيــازة حبــة مــن احلبــوب احملظــورة بقصــد التعاطــي ‪-‬‬\n ‫تعاطــي احلبــوب احملظــورة ‪ -‬قيــادة الســيارة حتــت تأثيــر احلبــوب‬\n                       ‫احملظــورة ‪ -‬عقوبــة عائــدة للجهــة املختصــة ‪.‬‬\n\n\n\n\n                                     ‫‪1 .1‬اإلقرار حجة شرعية على املقر‬\n        ‫‪2 .2‬املواد ‪ 41‬و ‪ 60‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n\n ‫الئحــة الدعــوى ضــد املدعــى عليــة بحيــازة حبــة مــن احلبــوب احملظــورة‬\n ‫بقصــد التعاطــي وتعاطيــه احلبــوب احملظــورة وقيــادة الســيارة حتــت‬\n ‫تأثيــر احلبــوب احملظــورة‪ ،‬وطلــب املدعــي العــام إثبــات مــا اســند إليــه‬\n ‫واحلكــم عليــه بعقوبــة الســجن واملنــع مــن الســفر واثبــات إدانتــه بقيــادة‬\n ‫الســيارة وتــرك عقابــه للجهــة املختصــة‪ ،‬مت القبــض علــى املدعــى عليــه‬\n ‫مــن قبــل مكافحــة املخــدرات بعــد االشــتباه بــه واســتيقافه وبتفتيشــه‬\n ‫عثــر معــه علــى حبــة واحــدة حتمــل عالمــة الكبتاجــون‪ ،‬إقــرار املدعــى‬\n ‫عليــة بالدعوى‪،‬تعزيــر املدعــى عليــة بالســجن واجللــد واملنــع مــن الســفر‪،‬‬\n ‫تــرك مجازاتــه لقــاء قيادتــه للســيارة حتــت تأثيــر احلبــوب احملظــورة‬\n           ‫للجهــة املختصــة‪ ،‬تصديــق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n                                                                                     ‫‪72‬‬\n\f     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬القاضــي يف احملكمــة‬\n     ‫اجلزائيــة باالحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n                                                                         ‫ّ‬\n     ‫رئيــس احملكمــة اجلزائيــة يف محافظــة االحســاء برقــم ‪34162926‬‬\n     ‫وتاريــخ ‪1434/04/09‬ه ـ املقيــدة باحملكمــة برقــم ‪34866975‬‬\n     ‫وتاريــخ ‪1434/04/09‬ه ـ حضــر املدعــي العــام ‪ ..........‬وادعــى ضــد‬\n     ‫‪ ..........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )..........‬قائــا‬\n     ‫إنــه باالطــاع علــى محضــر القبــض املعــد مــن قبــل رجــال مكافحــة‬\n     ‫املخــدرات مبحافظــة بقيــق بتاريــخ ‪1433/12/5‬ه ـ وأثنــاء مراقبــة إحدى‬\n     ‫محطــات الوقــود التــي يتــردد عليهــا أشــخاص مشــبوهون مت االشــتباه يف‬\n     ‫صاحــب ســيارة مــن نــوع ‪ .......‬بيضــاء اللــون حتمــل اللوحــة رقــم (‪)..........‬‬\n     ‫يركبهــا شــخص واحــد تظهــر عليــه عالمــات االرتبــاك وباالنتقــال إليــه‬\n     ‫للتأكــد منــه اتضــح أنــه املدعــى عليــه وبتفتيشــه شــخصي ًا ضبــط بجيــب‬\n     ‫ثوبــه األعلــى علــى حبــة بيضــاء اللــون حتمــل عالمــة الكبتاجــون املخــدر‬\n     ‫والتــي يشــتبه أن تكــون مــن احلبــوب احملظــورة فتــم اصطحابــه ومــا‬\n     ‫ضبــط بحيازتــه وســيارته إلــى مقــر إدارة املكافحــة وتســليمه لضابــط‬\n     ‫اخلفــر وبتحريــز املضبــوط بتاريــخ ‪1433/12/5‬ه ـ اتضــح أنهــا عبــارة عــن‬\n     ‫حبــة واحــدة أعطيــت الرقــم الســري (‪33/86‬س) ومت إرســالها للمركــز‬\n     ‫اإلقليمــي لتحليلهــا فــورد التقريــر الكيمــاوي الشــرعي رقــم (‪)..........‬‬\n     ‫بتاريخ‪1433/12/13‬ه ـ املتضمــن ثبــوت إيجابيــة احلبــة املضبوطــة ملــادة‬\n     ‫االمفيتامــن احملظــورة وبأخــذ عينــة مــن ســوائل املدعــى عليــه وبعثها إلى‬\n     ‫مركــز اإلقليمــي ملراقبــة الســموم قســم الكيميــاء الشــرعية لفحصهــا‬\n\n‫‪73‬‬\n\f‫ورد تقريــر الســموم الشــرعية رقــم(‪ )..........‬وتاريــخ ‪1433/12/12‬ه ـ‬\n‫متضمن ـ ًا إيجابيــة عينــة البــول املرســلة ملركــب االمفيتامــن احملظــور‬\n‫وبضبــط أقــوال املدعــى عليــه أقــر بصحــة واقعــة القبــض عليــه وأقــر‬\n‫بحيازة حبة واحدة من حبوب الكبتاجون احملظورة بقصد االســتعمال‬\n‫الشــخصي كمــا أضــاف بأنــه حصــل علــى حبتــن من احلبــوب احملظورة‬\n‫مــن شــخص ال يعرفــه أهداهــا لــه فقــام بالتعاطــي بحبــة واحــدة واألخــرى‬\n‫مت ضبــط بحوزتــه كمــا أضــاف بأنــه قــام بقيــادة الســيارة بعــد تعاطيــه‬\n‫احلبــة األولــى وأفــاد بأنــه تعاطــى حبــة واحــدة مــن احلبــوب احملظــورة قبــل‬\n‫أكثــر مــن ســنة تقريبـ ًا وأيضــا قبــل شــهر مــن تاريــخ القبــض عليــه وقــد‬\n‫أســفر التحقيــق عــن توجيــه االتهــام لــه بحيــازة حبــة واحــدة مــن حبــوب‬\n‫اإلمفيتامــن احملظــورة بقصــد االســتعمال وتعاطيــه لنوعهــا وقيادتــه‬\n‫للســيارة حتــت تأثيرهــا وذلــك لألدلــة والقرائــن التاليــة‪1 :‬ـ محضــر‬\n‫اعترافــه املنــوه عنــه واملــدون علــى الصفحــة رقــم (‪ )1‬مــن دفتــر التحقيــق‬\n‫لفــة رقــم(‪2)12‬ـ إقــرار املدعــى عليــه املنــوه عنــه واملــدون علــى الصفحــة‬\n‫رقــم(‪ )3‬مــن ملــف ضبــط إجــراءات قضيــة املخــدرات املرفــق لفــة رقــم(‪)2‬‬\n‫‪3‬ـ محضــر القبــض املنــوه عنــه واملــدون علــى الصفحــة رقــم (‪ )2‬مــن ملــف‬\n‫ضبــط إجــراءات قضيــة املخــدرات املرفــق لفــة رقــم (‪4 )1‬ـ تقريــري‬\n‫الكيمــاوي الشــرعي والســموم الشــرعية املنــوه عنهمــا املرفــق علــى‬\n‫اللفتــن رقــم (‪ )20/18‬وبالبحــث عمــا إذا كان لديــه ســوابق اتضــح‬\n‫عــدم وجــود ســوابق مســجلة ضــده وحيــث إن مــا أقــدم عليــه املدعــى عليه‬\n‫وهــو بكامــل أهليتــه املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n‫ونظامـ ًا لــذا أطلــب إثبــات إدانتــه بحيــازة مركــب اإلمفيتامــن احملظــور‬\n‫وتعاطيــه لنوعهــا ‪ ،‬وفق ـ ًا للفقــرة رقــم (‪)2‬مــن املــادة رقــم (‪)3‬مــن نظــام‬\n\n\n                                                                                       ‫‪74‬‬\n\f     ‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم‬\n     ‫(م‪ )39/‬وتاريخ‪1426/7/8‬ه ـ واحلكــم عليــه باآلتــي ‪ .1:‬عقوبــة الســجن‬\n     ‫الــواردة بالفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )41‬مــن النظــام املشــار إليــه‬\n     ‫لقــاء حيازتــه حبــة واحــدة مــن حبــوب االمفيتامــن احملظــورة بقصــد‬\n     ‫االســتعمال وتعاطيــه لنوعها‪.2‬منعــه مــن الســفر وفــق الفقــرة رقم(‪)1‬مــن‬\n     ‫املــادة رقم(‪)56‬مــن ذات النظــام‪3‬ـ ‪.‬إثبــات إدانتــه بقيــادة الســيارة حتــت‬\n     ‫تأثيــر مركــب االمفيتامــن املخــدر وفق ـ ًا للفقــرة رقــم (‪ )8‬مــن اجلــدول‬\n     ‫رقــم (‪ )1‬امللحــق بنظــام املــرور الصــادر باملرســوم امللكــي رقــم (م‪)85/‬‬\n     ‫وتاريــخ ‪1426/10/26‬هـ ـ وإفهامــه بــأن عقوبتــه الــواردة بالفقرة رقم (‪)1‬‬\n     ‫مــن املــادة رقــم (‪ )68‬و املــادة رقــم (‪ )76‬مــن النظــام املشــار إليــه آنف ـ ًا ‪،‬‬\n     ‫تقررهــا اجلهــة املختصــة وفقـ ًا للفقــرة رقــم (‪ )2‬مــن قــرار مجلــس الــوزراء‬\n     ‫رقــم (‪ )315‬يف ‪1428/10/24‬ه ـ وبعــرض تلــك الدعــوى علــى املدعــى‬\n     ‫ا أصــادق علــى مــا ذكــره املدعــي العــام مــن حيازتــي‬       ‫عليــه أجــاب قائ ـ ً‬\n     ‫حبــة مــن حبــوب اإلمفيتامــن املنبــه احملظــور وقصــدي مــن حيازتهــا‬\n     ‫االســتعمال كمــا أصــادق علــى اســتعمالي لهــا ولقيادتــي للســيارة وانــا‬\n     ‫حتــت تأثيــره وأنــا نــادم علــى ذلــك لــذا وبعــد ســماع الدعــوى واإلجابــة‬\n     ‫وتصفــح أوراق املعاملــة وحيــث طلــب املدعــي العــام إثبــات إدانــة املدعــى‬\n     ‫عليــه حليازتــة حبــة مــن احلبــوب احملظــورة بقصــد االســتعمال ومجازاتــه‬\n     ‫لقــاء ذلــك والســتعماله لهــا ولقيادتــه الســيارة وهــو حتــت تأثيــره وإن‬\n     ‫املدعــى عليــه قــد أقــر بذلــك وإن اإلقــرار حجــة شــرعية علــى املقــر وإن‬\n     ‫مــا أقــدم عليــه وإن الكميــة التــي مت ضبطهــا مــع املدعــى عليــه قليلــه‬\n     ‫وانهــا لالســتعمال الشــخصي وملــا ظهــر لنــا مــن ندمــه وانــه ال ســوابق‬\n     ‫عليــه وهــذه أســباب مخففــة للعقوبــة وان املــادة (‪ )60‬مــن نظام املخدرات‬\n\n\n‫‪75‬‬\n\f‫جتيــز للقاضــي النــزول عــن احلــد األدنــى مــن العقوبــة الــواردة يف بعــض‬\n‫مــواد ذلــك النظــام ومنهــا املــادة (‪ )41‬إذا وجــد أســباب معتبــره كمــا هــو‬\n‫احلــال هنــا لــذا فقــد تقــرر مــا يلــي أو ًال ثبــوت إدانــة املدعــى عليــه ‪..........‬‬\n‫حليازتــه حبــة مــن احلبــوب احملظــورة واحملتويــة علــى مركــب اإلمفيتامــن‬\n‫وذلــك حســبما أوضحــه التقريــر الكيمــاوي الشــرعي رقــم (‪)..........‬‬\n‫والقصــد مــن حيازتهــا االســتعمال ومجازاتــه لقــاء ذلــك بســجنه شــهرين‬\n‫تبــدأ مــن تاريــخ إيقافــه بســبب هــذه القضيــة ثانيـ ًا تعزيــره لقــاء اســتعماله‬\n‫للحبــوب احملظــورة بجلــده ســبعني جلــده علــى فترتــن متســاويتني بينهمــا‬\n‫اســبوعا ثالثــا منعــه مــن الســفر ملــدة ســنتني تبــدأ بعــد انتهــاء محكوميته‬\n‫رابعــا ثبــوت ادانتــه لقيادتــه للســيارة وهــو حتــت تأثيــر احلبــوب احملظــورة‬\n‫وتركــت مجازاتــه للجهــة املختصــة وبذلــك كلــه حكمــت وبعرضــه‬\n‫قــرر املدعــي العــام عــدم قناعتــه بــه وطلــب رفعــه حملكمــة االســتئناف‬\n‫مكتفيــا مبــا جــاء يف دعــواه عــن تقــدمي الئحــه اعتراضيــه امــا املدعــى‬\n‫عليــه فقــرر قناعتــه بــه وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد‬\n                      ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/05/22‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة االحســاء املكلــف‬\n‫الشــيخ‪ ..........‬برقــم ‪ 341194677‬وتاريــخ ‪1434/5/28‬ه ـ املقيــدة‬\n‫لــدى احملكمــة برقــم ‪ 34/1349225‬وتاريــخ ‪1434/6/5‬ه ـ املرفــق‬\n‫بهــا القــرار الصــادر مــن فضيلتــه املســجل برقــم ‪ 34220034‬وتاريــخ‬\n‫‪1434/5/22‬ه ـ اخلــاص بدعــوى‪ /‬املدعــي العــام ضــد‪ ........../‬يف قضيــة‬\n‫مخــدرات وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n\n\n                                                                                               ‫‪76‬‬\n\f     ‫فيــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة‬\n     ‫علــى احلكــم‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                         ‫وصحبــه وســلم حرريف‪1434/6/25‬ه ـ‬\n\n\n\n\n‫‪77‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":72,"source_page_end":77,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2655354e74c8fd512004f0bd6187282fbc6f71f8abfee4d32c2262f1d07e0da6","normalized_text_hash":"8e5f6613330640927fdb53a23f62d7d3ac676c87eeef00fde40268040d863054","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p72-34220034"},{"id":"587f7f7a-2795-566e-ba62-459657e587d4","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حبوب محظورة بقصد الترويج والتعاطي -محاولة هرب -تداخل عقوبات -ثبوت إدانة -تعزير بالسجن واجللد -تعزير باملصادرة واملنع من السفر.","document_number":"34241491","case_number":"34163215","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة اخلرج","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/14","year":"1434","subject":"مخدرات -حيازة حبوب محظورة بقصد الترويج والتعاطي -محاولة هرب -تداخل عقوبات -ثبوت إدانة -تعزير بالسجن واجللد -تعزير باملصادرة واملنع من السفر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34241491:‬تاريخه ‪1434/6/14:‬هـ‬\n                   ‫رقم الدعوى ‪34163215:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34267301‬تاريخه‪1434/07/12:‬هـ‬\n\n\n‫مخــدرات ‪ -‬حيــازة حبــوب محظــورة بقصــد الترويــج والتعاطــي‬\n‫‪ -‬محاولــة هــرب‪ -‬تداخــل عقوبــات ‪ -‬ثبــوت إدانــة ‪ -‬تعزيــر بالســجن‬\n                    ‫واجللــد ‪ -‬تعزيــر باملصــادرة واملنــع مــن الســفر‪.‬‬\n\n\n\n\n‫املــواد ( ‪ )62 /60 /56 /38‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                          ‫العقليــة‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بترويــج احلبــوب املخــدرة عــن‬\n‫طريــق البيــع وحيازتهــا لقصــد الترويــج وتعاطيــه لنوعهــا‪ ،‬وطلــب‬\n‫املدعــي العــام إثبــات مــا أســند إليــه و احلكــم عليــه بالعقوبــة الــواردة‬\n‫وفق ـ ًا للمــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات و املؤثــرات العقليــة‬\n‫و العقوبــة الــواردة وفق ـ ًا للمــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات و‬\n‫املؤثــرات العقليــة و منعــه مــن الســفر خــارج اململكــة و مصــادرة اجلــوال‬\n‫املســتخدم يف اجلرميــة و عــدم صــرف الشــريحة لنفــس املشــترك و تعزيــره‬\n‫لقــاء صدمــه الدوريــة و محاولــة الهــرب مــن الفرقــة القابضــة ‪ ،‬حيــث إنــه‬\n‫مت القبــض علــى املدعــى عليــه بعــد ورود بــاغ بأنــه يقــوم بترويــج احلبــوب‬\n‫احملظــورة فتــم التنســيق مــع أحــد املصــادر لإلطاحــة بــه ومت إتصــال‬\n\n                                                                                    ‫‪78‬‬\n\f     ‫املصــدر علــى املتهــم واتفقــا علــى املــكان احملــدد وحضــر املصــدر إلــى‬\n     ‫منــزل املتهــم وأعطــى اإلشــارة بإمتــام عمليــة البيــع وســلم للفرقــة القابضــة‬\n     ‫عــدد ســت حبــات حتمــل عالمــة الكبتاجــون ومتــت مراقبــة املذكــور‬\n     ‫حتــى مت القبــض عليــه وصــدر التقريــر الكيميائــي بإيجابيــة العينــة‬\n     ‫املرســلة‪ ،‬كمــا أقــر املدعــى عليــه باحليــازة لغــرض االســتخدام وأنكــر‬\n     ‫احليــازة بقصــد الترويــج وأحضــر املدعــي العــام بينــة موصلــة تثبــت‬\n     ‫احليــازة لقصــد الترويــج‪ ،‬ثبــوت إدانــة املدعــى عليــه‪ ،‬بنــاء علــى مــا تقــدم‬\n     ‫حكمــت احملكمــة بتعزيــر املدعــى عليــه بالســجن واجللــد واملنــع مــن‬\n     ‫الســفر ومصــادرة الهاتــف اجلــوال وإلغــاء الشــريحة املســتخدمان باجلرميــة‬\n     ‫ورد دعــوى املدعــي العــام بطلــب تطبيــق العقوبــة الــواردة وفقـ ًا للمــادة ‪41‬‬\n     ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وصــدق احلكــم مــن‬\n                                                               ‫محكمــة االســتئناف‪.‬‬\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..............‬القاضــي يف احملكمــة‬\n     ‫العامــة مبحافظــة اخلــرج وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n     ‫رئيــس احملكمــة العامــة باخلــرج ‪ /‬املكلــف برقــم ‪ 34163215‬وتاريــخ‬\n     ‫‪ 1434/04/09‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34868437‬وتاريــخ‬\n     ‫‪ 1434/04/09‬ه ـ ويف يــوم الثالثــاء املوافــق‪ 1434/05/21‬ه ـ افتتحــت‬\n     ‫اجللســة الســاعة ‪ 09 : 30‬وفيهــا حضــر املدعــي العــام بدائــرة التحقيــق‬\n     ‫و اإلدعــاء العــام ‪ ..............‬وادعــى علــى احلاضــر معــه ‪ ..............‬ســعودي‬\n     ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ..............‬بقولــه ‪ :‬فأنــه بتاريــخ‬\n     ‫‪1434/2/25‬ه ـ قبــض علــى املذكــور مــن قبــل مكافحــة املخــدرات‬\n\n‫‪79‬‬\n\f‫مبحافظــة اخلــرج لتوفــر معلومــات عنــه بترويــج احلبــوب املخــدرة و ُأ ِرســل‬\n‫لــه مصــدر وقــام باالتصــال بــه مبســمع مــن الفرقــة ولــم يجــب ثــم اتصــل‬\n‫عليــه وطلــب منــه املصــدر حبــوب مببلــغ (‪ )200‬مائتــن ريــال فوافقــه‬\n‫وطلــب مــن املصــدر احلضــور ملنزلــه وذهــب املصــدر ملنزلــه حتــت أنظــار‬\n‫الفرقــة واجتــه لــه وحتــدث معــه ثــم حتــرك املصــدر وأعطــى إالشــاره‬\n‫الدالــة علــى إمتــام الشــراء وســلم للفرقــة عــدد (‪ )6‬ســت حبــات حتمــل‬\n‫عالمــة الكبتاجــون احملظــور مييــل لونهــا للبيــج وهــي الكميــة املشــتراه‬\n‫ومتــت مراقبــة املذكــور وشــوهد حضــور أشــخاص لــه ومقابلتهــم وبعــد‬\n‫ســاعة ركــب ســيارته ومت اســتيقافه وحــاول الهــرب ومت إطــاق أعيــره‬\n‫ناريــة يف الهــواء فتوقــف وبتفتيشــه عثــر يف جيبــه العلــوي علــى كيــس‬\n‫بداخلــة عــدد (‪)57‬ســبع وخمســون حبــه حتمــل عالمــة الكبتاجــون‬\n‫املميــزة وكان يحــاول التخلــص منهــا وعثــر أيضــا يف جيبــه الســفلي‬\n‫األيســر مبلــغ مالــي قــدرة (‪ )1300‬ألــف وثالثمائــة ريــال وجــد مــن ضمنها‬\n‫املبلــغ احلكومــي املعــد واملرقــم جــرى اســتقطاعه كمــا ضبــط معــه‬\n‫جهــاز جــول مســتخدم يف اجلرميــة وقــد حصــل أثنــاء اســتيقافه احتــكاك‬\n                 ‫بــن ســيارته والســيارة الرســمية يف بعــض التلفيــات فيهــا‪.‬‬\n‫وقــد أثبــت التقريــر الكيميائــي الشــرعي رقــم (‪/2650‬س) إيجابيــة‬\n‫احلبــوب املضبوطــة مــع املذكــور واحتوائهــا لإلمفيتامــن وهــو مــن املــواد‬\n‫املدرجــة باجلــدول رقــم (‪ )2‬فئــة (ب) مــن نظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة ‪ .‬وبســماع أقوالــة واســتجوابه أقــر بحيازتــه للحبــوب‬\n‫احملظــورة وللمبلــغ املالــي ولتعاطيــه احلبــوب املخــدرة ولصدمــه ســيارة‬\n‫الفرقــة القابضــة وبوجــود ســابقة تعاطــي حشــيش وحيازتــه مســجلة عليه‬\n‫وأفــاد أنــه حصــل علــى احلبــوب مــن شــخص أرتيــري أدلــى مبعلومــات عنــه‬\n\n\n                                                                                    ‫‪80‬‬\n\f                ‫ومت متريرهــا إلــى إدارة مكافحــة املخــدرات إلكمــال الــازم ‪.‬‬\n                                                                            ‫ملا أشير إليه‬\n     ‫أقــرر توجيــه االتهــام للمدعــى عليــه ‪ .............. /‬بترويــج عــدد ســت حبــات‬\n     ‫مــن احلبــوب املخــدرة عــن طريــق البيــع وحيــازة عــدد (‪ )57‬حبــه بقصــد‬\n     ‫الترويــج وتعاطيــه لنوعهــا املجــرم مبوجــب املــادة الثالثــة مــن نظــام‬\n     ‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي‬\n     ‫رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ وصدمــة لســيارة الفرقــة القابضــة‬\n                        ‫ومحاولــة الهــرب منهــم ‪ .‬وذلــك لألدلــة والقرائــن التاليــة‬\n     ‫‪-1‬محضــر القبــض املــدون علــى ص (‪ )12-11‬مــن ملــف ضبــط إجراءات‬\n                                                               ‫االســتدالل لفــه رقم (‪.)1‬‬\n                                ‫‪-2‬ما ضبط بحوزته من حبوب ومبلغ مالي مرقم ‪.‬‬\n         ‫‪-3‬ماجاء يف أقواله املدونة على ص (‪ )2-1‬من ملف حتقيق رقم (‪. )1‬‬\n                                ‫‪-4‬التقرير الكيميائي الشرعي لفه رقم (‪. )........‬‬\n            ‫وببحث سوابقه تبني وجود سابقة حيازة وتعاطي احلشيش املخدر ‪.‬‬\n     ‫وحيــث إن مــا أقــدم عليــه املذكــور فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n     ‫ونظامـ ًا ممــا يتعــن إحالتــه إلــى احملكمــة العامــة بطلــب إثبــات مــا أســند‬\n     ‫إليــه واحلكــم عليــه مبــا يلــي ‪-1 -:‬بعقوبــة وفقـ ًا للمــادة (‪ )38‬مــن نظــام‬\n              ‫مكافحــة املخــدرات املشــار إليــه لقــاء ترويجــه احلبــوب املخــدرة ‪.‬‬\n     ‫‪-2‬بعقوبــة وفق ـ ًا للمــادة (‪ )41‬مــن ذات النظــام لقــاء حيازتــه للحبــوب‬\n                                                                               ‫املخــدرة ‪.‬‬\n     ‫‪-3‬منعــه مــن الســفر خــارج اململكــة وفقـ ًا للفقــرة األولــى مــن املــادة (‪)56‬‬\n     ‫مــن ذات النظــام ‪-4‬مصــادرة اجلــوال املوصــوف بالوقائع وإبالغ الشــركة‬\n     ‫مصــدر الشــريحة املســتخدمة يف الترويــج بعــدم صرفهــا لنفــس املشــترك‬\n\n\n‫‪81‬‬\n\f‫يف حــال صــدور احلكــم باملصــادرة اســتناد ًا لتعميــم صاحــب الســمو‬\n‫امللكــي وزيــر الداخليــة رقــم (‪ )9798‬يف ‪1428/2/10-9‬ه ـ وفق ـ ًا ملــا‬\n‫ورد يف املــادة (‪ )53‬مــن النظــام املشــار إليــه علــى ضــوء قــرار مجلــس‬\n                                         ‫الــوزراء رقــم (‪ )47‬يف ‪1421/2/18‬ه ـ ‪.‬‬\n    ‫‪-5‬تعزيره لقاء صدمة لسيارة الفرقة القابضة ومحاولة الهرب منهم ‪.‬‬\n‫مــع التشــديد عليــه يف احلكــم اســتناد ًا لتعميــم صاحــب الســمو امللكــي‬\n‫وزيــر الداخليــة رقــم (‪2/8346/5/1‬ش) وتاريــخ ‪1427/2/8‬ه ـ هــذه‬\n                                                                            ‫دعــواي‬\n‫وبســؤال املدعــى عليــه أجــاب بقولــه‪ :‬مــا ذكــره املدعــي العــام مــن‬\n‫حيازتــي للحبــوب احملظــورة املوصوفــة يف الدعــوى فصحيــح و لكــن‬\n‫كانــت حيازتــي لهــا بغــرض التعاطــي فأنــا أتعاطــى احلبــوب احملظــورة‬\n‫وأمــا مــا ذكــره املدعــي العــام مــن الترويــج فغيــر صحيــح وأمــا مــا ذكره‬\n‫املدعــي العــام مــن اصطدامــي بالفرقــة القابضــة فصحيــح ولكــن كان‬\n‫ذلــك بســبب توقفهــم أمامــي مباشــرة بســيارتهم فلــم أســتطع تفاديهــم‬\n‫واصطدمــت بهــم هكــذا أجــاب ثــم جــرى ســؤال املدعــي العــام عــن‬\n‫ا ‪ :‬بينتــي أحضرتهــا معــي وهــي عبــارة عــن شــاهدين‬      ‫بينتــه فأجــاب قائـ ً‬\n‫مــن الفرقــة القابضــة هكــذا قــرر و يف هــذه اجللســة حضــر ‪..............‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ..............‬و‪..............‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ..............‬ويعمــان بــإدارة‬\n‫مكافحــة املخــدرات باخلــرج وبســؤالهما عمــا لديهمــا مــن شــهادة أجــاب‬\n‫كل واحــد منهمــا منفــرد ًا بقولــه ‪ :‬أشــهد بأنــه توفــر لدينــا معلومــات‬\n‫عنــد قيــام املدعــى عليــه بترويــج احلبــوب املخــدرة فتــم اإلتفــاق مــع مصــدر‬\n‫ســري لإلطاحــة بــه فقــام املصــدر الســري باالتصــال بــه علــى مســمع منــا‬\n\n\n                                                                                       ‫‪82‬‬\n\f     ‫و طلــب منــه حبوب ـ ًا مببلــغ مائتــي ريــال فوافــق املدعــى عليــه وطلــب مــن‬\n     ‫املصــدر احلضــور ملنزلــه فتــم تفتيــش املصــدر و تســليمه مبلغـ ًا حكوميـ ًا‬\n     ‫وقــدره مائتــي ريــال ثــم اجتــه املصــدر ملنــزل املدعــى عليــه حتــت أنظارنــا‬\n     ‫و تقابــل مــع املدعــى عليــه وحتــدث معــه ثــم حتــرك املصــدر و أعطــى‬\n     ‫اإلشــارة الدالــة علــى إمتــام الشــراء ولــم نشــاهد التســليم و التســلم ثــم‬\n     ‫سـلّم لنــا املصــدر عــدد ســت حبــات حتمــل عالمــة الكبتاجــون احملظورة‬\n     ‫فتــم مراقبــة املدعــى عليــه وشــوهد حضــور أشــخاص لــه ومقابلتهــم و‬\n     ‫بعــد فتــرة ركــب ســيارته و مت اســتيقافه فحــاول الهــرب فتــم إيقــاف‬\n     ‫ســيارتنا أمامــه لئــا يهــرب فاصطــدم بنــا و توقــف فتــم تفتيشــه فعثــر‬\n     ‫يف جيبــه علــى كيــس بداخلــه ســبع و خمســون حبــة حتمــل عالمــة‬\n     ‫العينــة التــي سـلّمها لنــا املصــدر الســري كمــا‬   ‫الكبتاجــون وهــي نفــس ّ‬\n     ‫عثــر معــه علــى مبلــغ مالــي و قــدره ألــف وثالثمائــة ريــال وكان املبلــغ‬\n     ‫احلكومــي املرقــم مــن ضمنهــا كمــا وجــد بحوزتــه جهــاز جــوال هــذا‬\n     ‫مــا لدينــا مــن شــهادة هكــذا شــهدا و بعــرض الشــاهدين وشــهادتهما‬\n     ‫علــى املدعــى عليــه قــال أمــا الشــاهدين فــا أعرفهمــا و أمــا شــهادتهما‬\n     ‫فغيــر صحيحــة هكــذا قــرر و قــد جــرى تعديــل الشــاهدين مــن قبــل‬\n     ‫‪ ..............‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ..............‬و‬\n     ‫‪ ..............‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ..............‬ثــم‬\n     ‫ا ‪ :‬ال يوجــد‬   ‫جــرى ســؤال املدعــي العــام هــل لديــه زيــادة ّبينــة فأجــاب قائـ ً‬\n     ‫لــدي ســوى مــا يف أوراق املعاملــة هكــذا قــرر‪ .‬ويف جلســة أخــرى جــرى‬\n     ‫ا‬ ‫ســؤال املدعــى عليــه عــن الســابقة املذكــورة يف الدعــوى فأجــاب قائـ ً‬\n     ‫‪ :‬أمــا الســابقة فصحيحــة ولكــن لــم يصــدر فيهــا حكــم ألنــه شــملني‬\n     ‫العفــو هكــذا أجــاب جــرى تصفــح أوراق املعاملة واإلطــاع على محضر‬\n\n\n‫‪83‬‬\n\f‫القبــض والضبــط والتفتيــش املــدون مبلــف التحقيــق لفــة ‪ 1‬صــ‪12-11‬‬\n‫فوجدتــه مطابقـ ًا ملــا جــاء يف دعــوى املدعــي العــام كمــا جــرى اإلطــاع‬\n‫علــى التقريــر الكيميائــي الشــرعي رقــم ‪/2650‬س يف ‪1434/3/17‬ه ـ‬\n‫لفــة ‪ 27‬فوجدتــه مطابقـ ًا ملــا ذكــره املدعــي العــام يف دعــواه فبنــاء علــى‬\n‫مــا تقــدم ذكــره مــن الدعــوى واإلجابــة ومبــا أن املدعــى عليــه قــد أقــر‬\n‫بحيازتــه احلبــوب احملظــورة املوصوفــة يف الدعــوى وأنــه غرضــه مــن ذلــك‬\n‫التعاطــي‪ ،‬ومبــا أن املدعــى عليــه قــد أقــر باصطدامــه بالفرقــة القابضــة‬\n‫ودفــع بــأن ذلــك كان بســبب توقفهــم أمامــه مباشــرة وبنــاء علــى مــا ورد‬\n‫يف شــهادة الشــاهدين املعدلني من اتصال املصدر الســري باملدعى عليه‬\n‫وطلبــه حبوب ـ ًا مببلــغ مائتــي ريــال وأن املدعــى عليــه طلــب مــن املصــدر‬\n‫الســري احلضــور ملنزلــه وأن ذلــك كان علــى مســمع منهمــا ‪ ،‬وبنــاء علــى‬\n‫مــا ورد يف شــهادة الشــاهدين املعدلــن مــن أن املصــدر الســري قــد تقابــل‬\n‫مــع املدعــى عليــه حتــت أنظارهمــا وقــام املصــدر بإعطــاء اإلشــارة الدالــة‬\n‫على إمتام الشــراء وأن املصدر الســري قام بتســليم الفرقة القابضة ســت‬\n‫حبــات حتمــل عالمــة الكبتاجــون احملظــورة وأنهمــا لــم يشــاهدا عمليــة‬\n‫التســلم واالســتالم وأنــه مت اســتيقاف املدعــى عليــه فحــاول الهــرب فتــم‬\n‫التوقــف أمامــه مباشــرة ممــا أدى إلــى اصطدامــه بهــم وأنــه عثــر يف جيبــه‬\n‫علــى كيــس بــه ســبع وخمســن حبــة حتمــل عالمــة الكبتاجــون وأنهــا‬\n‫العينــة التــي س ـلّمها لهــم املصــدر الســري كمــا عثــر مــع املدعــى‬\n                                                                        ‫نفــس ّ‬\n                 ‫عليــه علــى املبلــغ احلكومــي املرقــم وكذلــك جهــاز جــوال‪.‬‬\n‫وبنــاء علــى مــا ورد يف التقريــر الكيميائــي الشــرعي املنــوه عنــه آنف ـ ًا‬\n‫ونظــر ًا لوجــود ســابقة حيــازة وتعاطــي حشــيش مخــدر علــى املدعــى عليــه‬\n‫واســتناد ًا إلــى مــا ورد يف الشــريعة مــن حرمــة املخــدرات ملــا فيهــا مــن‬\n\n\n                                                                                     ‫‪84‬‬\n\f     ‫الضــرر البــن علــى األفــراد واملجتمعــات وملــا قــرره أهــل العلــم مــن العمــل‬\n     ‫بالقرائــن إذا قويــت وبنــاء علــى املــادة الثامنــة والثالثــن واملــادة السادســة‬\n     ‫واخلمســن واملــادة الســتني واملــادة الثانيــة والســتني ( أن احملاكمــة‬\n     ‫تكــون علــى العقوبــة األشــد ويحكــم بعقوبتهــا دون غيرهــا ) مــن نظــام‬\n     ‫مكافحــة املخــدرات واملؤثــرات العقليــة ولكــون العقوبــات تتداخــل إذا‬\n     ‫كانــت مــن جنــس واحــد وملــا يظهــر مــن أخــاق املدعــى عليــه لــكل مــا‬\n     ‫ســبق فقــد ثبــت لــدي إدانــة املدعــى عليــه بحيازتــه ســبع وخمســن حبــة‬\n     ‫مــن حبــوب االمفيتامــن املنبــه احملظــور بقصد التعاطــي وتعاطيه لنوعها‬\n     ‫يف الســابق كمــا ثبــت لــدي إدانــة املدعــى عليــه بترويــج ســت حبــات‬\n     ‫مــن احلبــوب احملظــورة كمــا ثبــت لــدي محاولــة املدعــى عليــه للهــرب‬\n     ‫مــن الفرقــة القابضــة كمــا ثبــت لــدي اصطــدام املدعــى عليــه بســيارة‬\n     ‫الفرقــة القابضــة وقــررت مــا يلــي ‪ :‬أو ًال ‪ :‬ســجن املدعــى عليــه ملــدة ثــاث‬\n     ‫ســنوات يحتســب منهــا مــدة إيقافــه بنــاء علــى املــادة الســتني مــن نظــام‬\n     ‫مكافحــة املخــدرات وجلــده مائتــي جلــدة مفرقــة علــى أربــع دفعــات‬\n     ‫متســاوية بــن الدفعــة واألخــرى عشــرين يوم ـ ًا وإلزامــه بدفــع غرامــة‬\n     ‫وقدرهــا ألــف ريــال تــودع يف بيــت املــال ‪ .‬ثانيـ ًا ‪ :‬رد دعــوى املدعــي العــام‬\n     ‫فيمــا يتعلــق بطلبــه تطبيــق العقوبــة الــواردة يف املــادة احلاديــة واألربعــن‬\n     ‫مــن نظــام مكافحــة املخــدرات وذلــك بنــاء علــى املــادة الثانيــة والســتني‬\n     ‫مــن ذات النظــام ‪ .‬ثالثـ ًا ‪ :‬منــع املدعــى عليــه مــن الســفر خــارج اململكــة‬\n     ‫ملــدة ثــاث ســنوات بعــد انتهــاء تنفيــذ عقوبــة الســجن بنــاء علــى املــادة‬\n     ‫السادســة واخلمســن مــن نظــام مكافحــة املخــدرات ‪ .‬رابع ـ ًا ‪ :‬مصــادرة‬\n     ‫الهاتــف اجلــوال العائــد للمدعــى عليــه واملوصــوف يف الوقائــع وإلغــاء‬\n     ‫الشــريحة الهاتفيــة العائــدة لــه واملســتخدمة يف عمليــة الترويــج وعــدم‬\n\n\n‫‪85‬‬\n\f‫صرفهــا لنفــس املشــترك وإبــاغ الشــركة مصــدرة الشــريحة بذلــك ‪،‬‬\n‫خامس ـ ًا ‪ :‬االكتفــاء مبــا ُحكــم بــه يف الفقــرة أو ًال فيمــا يتعلــق بتعزيــر‬\n‫املدعــى عليــه لقــاء محاولــة املدعــى عليــه الهــرب واصطدامــه بســيارة‬\n‫الفرقــة القابضــة ومبــا ســبق حكمــت وبعــرض احلكــم علــى الطرفــن‬\n‫قنــع املدعــى عليــه و قــرر املدعــي العــام اعتراضــه علــى احلكــم وطلــب‬\n‫رفــع املعاملــة حملكمــة االســتئناف بــدون الئحــة فأجيــب لطلبــه ختمــت‬\n‫يف الســاعة احلاديــة عشــرة والنصــف وعليــه جــرى التوقيــع وصلــى اهلل‬\n                          ‫وســلم علــى نبينــا محمــد حــرر يف ‪1434/6/13‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة‬\n‫لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة باخلــرج برقــم ‪34868437‬‬\n‫وتاريــخ ‪1434/6/18‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضي‬\n‫باحملكمــة الشــيخ‪ .............. /‬املســجل برقــم ‪ 34241491‬وتاريــخ‬\n‫‪1434/6/14‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد‪ .............. /‬التهامــه‬\n‫بقضيــة مخــدرات علــى النحــو املوضــح بالقــرار املتضمــن حكــم‬\n‫فضيلتــه مبــا هــو مــدون ومفصــل بــه‪ .‬وبدراســة القــرار وصــورة ضبطــه‬\n‫وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل‬\n                                       ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                      ‫‪86‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":78,"source_page_end":86,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ccee7671c1c1b11ff7ffd9af4a94591165cff9214c792f16d6346de14796fc6a","normalized_text_hash":"1640918b027f523caf8bcede3246372947f3f755792dec82563c982fd8a067fd","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p78-34241491"},{"id":"7a6f1004-1596-5816-a97c-ffab4e5e4325","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة احلشيش بقصد الترويج والتعاطي -إقرار حتقيق ا -رجوع عن إقرار -نزول عن احلد األدنى للعقوبة -تعزير بالسجن واجللد واإلبعاد.","document_number":"34204877","case_number":"34164499","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/4","year":"1434","subject":"مخدرات -حيازة احلشيش بقصد الترويج والتعاطي -إقرار حتقيق ا -رجوع عن إقرار -نزول عن احلد األدنى للعقوبة -تعزير بالسجن واجللد واإلبعاد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪ 34204877 :‬تاريخه ‪1434/5/4 :‬هـ‬\n                         ‫رقم الدعوى‪34164499 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34874635‬تاريخه‪1434/01/01:‬هـ‬\n\n\n     ‫مخــدرات ‪ -‬حيــازة احلشــيش بقصــد الترويــج والتعاطــي ‪ -‬إقــرار‬\n     ‫حتقيقـ ًا ‪ -‬رجــوع عــن إقــرار ‪ -‬نــزول عــن احلــد األدنــى للعقوبــة ‪ -‬تعزيــر‬\n                                                     ‫بالســجن واجللــد واإلبعــاد‪.‬‬\n\n\n\n       ‫املواد ( ‪ ) 56 - 41 - 60‬من نظام مكافحة املخدرات واملؤثرات العقلية‬\n\n\n\n\n     ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بتوجيــه االتهــام لــه بحيــازة‬\n     ‫احلشــيش املخــدر بقصــد الترويــج وتعاطيــه لــه‪ ،‬وطلــب املدعــي العــام‬\n     ‫إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة الســجن واجللــد والغرامــة‬\n     ‫واإلبعــاد عــن البــاد وعــدم الســماح لــه بالعــودة وإلغــاء شــريحه اجلــوال‬\n     ‫املســتخدمة بالترويــج ‪ ،‬حيــث أنــه مت القبــض علــى املدعــى عليــه متلبسـ ًا‬\n     ‫باجلرميــة بعــد إخباريــة مفادهــا أن املدعــى عليــه يقــوم بالتوســط والترويــج‬\n     ‫ملــادة احلشــيش املخــدر ومت التنســيق مــع إحــدى املصادر الســرية لإلطاحة‬\n     ‫بــه ‪ ،‬إنــكار املدعــى عليــه‪ ،‬أحضــر املدعــي العــام البينــة وهــم شــهود‬\n     ‫القبــض ‪ ،‬أقــر املدعــى عليــه حتقيقــا وأنكــر أمــام احملكمــة وثبتــت‬\n     ‫إدانتــه باحليــازة لغــرض االســتخدام وعــدم ثبــوت احليازة لغــرض الترويج‪،‬‬\n     ‫بنــاء علــى مــا تقــدم حكمــت احملكمــة بتعزيــر املدعــى عليــه بالســجن‬\n\n‫‪87‬‬\n\f             ‫واجللــد واإلبعــاد وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبكــة املكرمــة ‪ ............‬وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة مبكــة املكرمــة برقــم ‪ 34164499‬وتاريــخ‬\n‫‪1434/04/09‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34874635‬وتاريــخ‬\n‫‪1434/04/09‬ه ـ ففــي يــوم األربعــاء املوافق‪1434/04/10‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 02 : 00‬وفيهــا حضــر املدعــي العــام مبوجــب خطــاب‬\n‫التعميــد رقــم ه ـ م ‪ / 2 /‬أ ‪ 341 /‬وتاريــخ ‪1424/1/24‬ه ـ وحضــر‬\n‫حلضــوره املدعــى عليــه ‪ ........‬مينــي اجلنســية مبوجــب اإلقامة رقــم ‪..............‬‬\n‫وادعــى املدعــي العــام قائــا إنــه بتاريــخ ‪1434/3/12‬ه ـ وردت معلومــات‬\n‫مــن أحــد املصــادر إلدارة مكافحــة املخــدرات بالعاصمــة املقدســة‬\n‫مفادهــا قيــام املدعــى عليــه بالتوســط والترويــج يف مــادة احلشــيش‬\n‫املخــدر واســتعد املصــدر الشــراء املباشــر منــه وذكــر بانــه يســتخدم‬\n‫الرقــم(‪ ،)...................‬وعلــى الفــور مت متكــن املصــدر مــن االتصــال‬\n‫علــى جــوال املدعــى عليــه املنــوه عنــه‪ ،‬حتــت ســماع أفــراد الفرقــة‬\n‫القابضــة وطلــب منــه ان يؤمــن لــه كميــه مــن احلشــيش املخــدر مببلــغ‬\n‫(‪ )200‬مأتــي ريــال فاســتعد املدعــى عليــه بتأمينهــا وطلب من املصدر ان‬\n‫يحضــر لــه بجــوار قصــر الزمــردة علــى الشــارع العــام وباالنتقــال للموقــع‬\n‫شــوهد املدعــى عليــه فتوجــه لــه املصــدر وضابــط الفرقــة وبنزولهمــا مــن‬\n‫الســيارة قــام املدعــى عليــه بتســليم املصــدر قطعــه يشــتبه ان تكــون‬\n‫مــن احلشــيش املخــدر وزنها(‪)10‬عشــره جرامــات ‪ ،‬وعنــد تســليمه املبلــغ‬\n\n                                                                                          ‫‪88‬‬\n\f     ‫املالــي املرقــم غــادر مســرعا لداخــل احلــي‪ ،‬وعنــد تتبعــه‪ ،‬لــم يعثــر عليــه‪،‬‬\n     ‫فتــم وضعــه حتــت املراقبــة و بتاريــخ ‪1434/3/15‬هــ‪ ،‬شــوهد املدعــى‬\n     ‫عليــه يخــرج مــن منزلــه‪ ،‬فتــم القبــض عليــه(مت التعــرف عليــه مــن قبــل‬\n     ‫أفــراد الفرقــة القابضــة وأعــد محضــر بذلــك ) وباصطحابــه ملنزلــه مت‬\n     ‫تفتيــش الغرفــة اخلــاص بــه وضبــط حتــت الكنبــة علــى قطعــه بنيــه اللــون‬\n     ‫وزنها(‪)0,50‬خمســون باملئــة مــن اجلــرام‪ ،‬يشــتبه أن تكــون مــن احلشــيش‬\n     ‫املخــدر اثبــت التقريــر الكيميائــي الصــادر مــن مركــز الســموم‬\n     ‫والكيميــاء الشــرعية مبكــة املكرمــة رقم(‪/4747‬س‪1434/2‬هــ)‬\n     ‫إيجابيــة العينتــن(أ‪،‬ب) املروجــة واملضبوطــة ملــادة احلشــيش املخــدر‬\n     ‫واحتوائهمــا علــى املــادة الفعالــة لــه ‪ .،‬وهــو مــن املــواد املخــدرة املدرجــة‬\n     ‫باجلــدول رقــم(‪ )1‬فئــة (أ) امللحــق بنظــام مكافحــة املخــدرات واملؤثرات‬\n     ‫العقليــة الصــادر باملرســوم امللكــي الكــرمي رقــم م‪ 39/‬يف ‪1426/7/8‬‬\n     ‫ه ـ بالتحقيــق مــع املدعــى عليــه ‪ :‬أفــاد بانــه تلقــى اتصــا ًال مــن املصــدر‬\n     ‫علــى هاتــف جوالــه رقــم (‪ ) ..............‬طالب ـ ًا منــه أن يبيعــه عســل مببلــغ‬\n     ‫وقــدره (‪ )200‬مائتــي ريــال فوافــق وعنــد حضــوره لــه يف يــوم اخلميــس‬\n     ‫وقــت العشــاء تقابــل مــع املصــدر وكان يرافقــه شــخص آخــر وحتدثــا‬\n     ‫ولــم يعطيــه قيمــة العســل وغــادر ‪ ،‬وأقــر بانــه ضبــط قطعــه مــن احلشــيش‬\n     ‫املخــدر وزنهــا(‪ )0,50‬خمســون باملئــة مــن اجلــرام عائــدة لــه شــخصي ًا‬\n     ‫بقصــد االســتعمال وحصــل عليهــا مــن شــخص ال يعرفــه ‪ ،‬وان اجلــوال‬\n     ‫املضبــوط بحوزتــه عائــد لــه وهــو الــذي تلقــى االتصــال عليــه مــن املصــدر‬\n     ‫وفقــده عنــد القبــض عليــه وقــد انتهــى التحقيــق إلــى توجيــه االتهــام‬\n     ‫للمدعــى عليــه ‪ :‬بترويــج (‪ )10‬عشــرة جرامــات مــن مــادة احلشــيش‬\n     ‫املخــدر عــن طريــق البيــع ‪ ،‬وحيــازة (‪ ),50‬خمســون باملئــة مــن اجلــرام مــن‬\n\n\n‫‪89‬‬\n\f‫ذات النــوع بقصــد الترويــج والتعاطــي وذلــك لألدلــة والقرائــن التاليــة ‪:‬‬\n‫‪ -1‬مــا ورد بإقــراره املنــوه عنــه صفحــه رقــم(‪ )4‬لفــه رقــم(‪ -2 )12‬مــا ورد‬\n        ‫مبحضــر القبــض املنــوه عنــه صفحــه رقــم(‪ )13-12‬لفــه رقــم(‪)1‬‬\n‫‪ -3‬مــا ورد مبحضــر التعــرف مــن رجــال األمــن املنوه عنــه صفحه رقم(‪)4‬‬\n‫لفــه رقــم(‪ -4 )1‬مــا ورد بالتقريــر الكيميائــي املنــوه عنــه لفــه رقــم(‪)11‬‬\n‫وحيــث أن مــا قــام بــه املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة‬\n‫شــرع ًا فعــل محــرم شــرعا ومعاقــب عليــه وفق ـ ًا لنظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم (م‪)39/‬‬\n‫يف ‪1426/7/8‬هــ‪ ،‬وفق ـ ًا للفقــرة (‪ )2‬مــن املــادة(‪ )3‬مــن ذات النظــام‬\n‫لــذا أطلــب إ ثبــات إدانتــه مبــا اســند إليــه واحلكــم عليــه بالعقوبــات‬\n‫األصليــة والتكميليــة التاليــة ‪-1 :‬الســجن واجللــد والغرامــة املنصــوص‬\n‫عليهــا يف الفقــرة (‪ )1‬مــن املــادة( ‪ ) 38‬مــن نظــام مكافحــة املخــدرات‬\n‫املشــار إليــه ‪ 2‬بعــاده عــن اململكــة بعــد تنفيــذ العقوبــة احملكــوم بهــا‬\n‫عليــه وال يســمح لــه بالعــودة إليهــا يف ماعــدا مــا تســمح بــه تعليمــات‬\n‫احلــج والعمــرة وفقــا للفقــرة (‪ )2‬مــن املــادة(‪ )56‬مــن نظــام مكافحــة‬\n‫املخــدرات املشــار إليــه ‪-3‬إلغــاء الشــريحة املســتخدمة يف الترويــج وعــدم‬\n‫صرفهــا للمدعــى عليــه مــرة أخــرى اســتنادا لتعميــم صاحــب الســمو‬\n‫امللكــي نائــب رئيــس مجلــس الــوزراء وزيــر الداخليــة رقــم (‪ )9798‬يف‬\n‫‪1428/2/10-9‬ه ـ وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائــا مــا‬\n‫ذكــره املدعــي العــام كلــه غيــر صحيــح جملــة وتفصيــا ولــم يكــن‬\n‫لــدي وال بحوزتــي حشــيش أبــد ًا والشــخص الــذي اتصــل بــي كان‬\n‫يطلــب منــي عســل فقــط واتهمونــي باحلشــيش هكــذا أجــاب املدعــى‬\n‫عليــه وبســؤال املدعــي العــام هــل لديــه بينــه علــى صحــة الدعــوى‬\n\n\n                                                                                   ‫‪90‬‬\n\f     ‫فقــال نعــم لــدي البينــة وأطلــب إمهالــي إلحضارهــا لكــم يف اجللســة‬\n     ‫القادمــة لــذا قــررت رفــع اجللســة وقــد حــدد لهــا موعــد يف يــوم األربعــاء‬\n     ‫‪1434/4/17‬ه ـ ويف جلســة أخــرى حضــر املدعــي العــام ولــم يحضــر‬\n     ‫املدعــى عليــه وبســؤال املدعــي العــام عــن البينــة التــي وعــد بإحضارهــا‬\n     ‫فاحضــر ‪ ........‬ســعودي بالســجل املدنــي رقــم ‪ ........‬وشــهد قائــا اشــهد‬\n     ‫هلل تعالــى أنــه يف يــوم مــن األيــام ورد لــإدارة بــاغ علــى أن املدعــى عليــه‬\n     ‫يقــوم بترويــج احلشــيش فتــم االتصــال باملدعــى عليــه عــن طريــق أحــد‬\n     ‫مصادرنــا وكنــت أســمع املكاملــة عندمــا طلــب املصــدر مــن املدعــى‬\n     ‫عليــه كميــة مــن احلشــيش مببلــغ مائتــي ريــال فاســتعد املدعــى عليــه‬\n     ‫بذلــك وقــال لــه قابلنــي عنــد قاعــة ‪ ............‬فذهــب إليــه املصــدر ومعــه‬\n     ‫أحــد زمالئــي أمــا أنــا فكنــت متخفــي ال أشــاهدهم ولــم أرى االســتالم‬\n     ‫وال التســليم وبعــد يومــن انتقلنــا إلــى منــزل املدعــى عليــه فوجدنــا يف‬\n     ‫غرفتــه ‪ %50‬مــن اجلــرام مــن احلشــيش هــذا مــا لــدي مــن شــهادة كمــا‬\n     ‫أحضــر للشــهادة وأدائهــا ‪ ........‬ســعودي بالســجل املدنــي رقــم ‪................‬‬\n     ‫وشــهد قائــا أشــهد هلل تعالــى أننــي كنــت أراقــب املصــدر عندمــا قابــل‬\n     ‫املدعــى عليــه وقــام بالســام عليــه ومصافحتــه علمــا أننــي لــم أشــاهد‬\n     ‫الكميــة ولــم يقــم املصــدر بتســليم املبلــغ للمدعــى عليــه حلــذره وخوفــه‬\n     ‫وقــد عــاد املصــدر لنــا ومعــه كميــة احلشــيش مــع أننــا ســبق وان قمنــا‬\n     ‫بتفتيــش املصــدر تفتيشــا دقيقــا هكــذا شــهد الشــاهد كمــا احضــر‬\n     ‫للشــهادة وأدائهــا ‪ ........‬ســعودي بالســجل املدنــي رقــم ‪ .................‬وشــهد‬\n     ‫قائــا اشــهد هلل تعالــى أننــي ســمعت املكاملــة مــع املدعــى عليــه عندمــا‬\n     ‫أســتعد بإحضــار كميــة مــن احلشــيش مببلــغ مائتــن ريــال كمــا كنــت‬\n     ‫أشــاهد املصــدر عندمــا احتــك مــع املدعــى عليــه وقــام بالســام عليــه‬\n\n\n‫‪91‬‬\n\f‫ولــم أشــاهد الكميــة بعينهــا ولــم أشــاهد اســتالم املبلــغ وقــد انتقلنــا‬\n‫للشــقة ووجدنــا بهــا قطعــة مــن احلشــيش هكــذا شــهد الشــاهد ونظــرا‬\n‫لعــدم حضــور املدعــى عليــه قــررت رفــع اجللســة إلحضــار املدعــى عليــه‬\n‫وأفهمــت الشــهود باحلضــور يف اجللســة القادمــة وبرفقتهــم مــن يعدلهــم‬\n‫وقــد حــدد لهــا موعــد يف يــوم الســبت املوافــق ‪1434/05/04‬ه ـ وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                            ‫حــرر يف ‪ 1434/04/28‬ه ـ‬\n‫ويف جلســة أخرى حضر املدعي العام واملدعى عليه ولم يحضر الشــهود‬\n‫يف هــذه اجللســة وبعــرض مــا جــاء يف شــهادة الشــهود علــى املدعــى عليــه‬\n‫فقــال شــهادتهم غيــر صحيحــة كمــا جــرى الرجــوع إلــى ملــف التحقيــق‬\n‫املرفــق باملعاملــة علــى اللفــة رقــم ‪ 16‬ووجــدت علــى الصفحــة رقــم‬\n‫‪4‬اقــرارا للمدعــى عليــه ونصــه اقــر انــا املدعــو ‪ ..................‬مينــي اجلنســية‬\n‫مبوجــب إقامــة رقــم ‪ ..............‬وأنــا بكامــل قــواي العقليــة املعتبــرة شــرعا‬\n‫مــن غيــر أكــراه أو أجبــار مــن احــد بأنــه قبــض علــي وضبــط بغرفتــي‬\n‫اخلاصــة باملنــزل علــى قطعــة مــن احلشــيش املخــدر بلــغ وزنهــا خمســون‬\n‫باملائــة مــن اجلــرام عائــدة لــي شــخصيا واقصــد مــن حيازتهــا االســتخدام‬\n‫كمــا أقــر بــأن اجلــوال رقــم ‪ ...................‬عائــد لــي وهــو اجلــوال الــذي‬\n‫تلقيــت عليــه االتصــال مــن املصــدر ولقــد فقــدت اجلــوال املذكــور حينمــا‬\n‫مت القبــض علــي وعلــى ذلــك اقــر ولقــد اتفقــت مــع املصــدر ان البيعــة‬\n‫عســل مببلــغ ‪ 200‬ريــال حينمــا اتصــل علــي انتهــى نصــة وبعرضــه عليــه‬\n‫فقــال أن هــذا اإلقــرار كنــت مكــره عليــه اجبرونــي بالقــوة علــى هــذا‬\n‫االعتــراف وبســؤاله هــل لديــه بينــة علــى اإلكــراه فقــال ليســت لــدي‬\n‫بينــة وقــد جــرى الرجــوع علــى أوراق املعاملــة ومنهــا التقريــر الكيميائــي‬\n\n\n                                                                                            ‫‪92‬‬\n\f     ‫وصحيفــة ســوابق املدعــى عليــه ولــم أجــد مســجل بصحيفتــه ســوابق‬\n     ‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة واالطــاع علــى أوراق املعاملــة‬\n     ‫وبنــاء علــى مــا جــاء يف إقــرار املدعــى عليــه املــدون علــى ملــف التحقيــق‬\n     ‫ومــا جــاء يف شــهادة الشــهود املذكوريــن أعــاه ولكــون شــهادة الشــهود‬\n     ‫غيــر موصلــة إلدانــة املدعــى عليــه بتهمــة حيــازة كميــة مــن احلشــيش‬\n     ‫املذكــورة أعــاه بقصــد الترويــج لذلــك كلــه فقــد ثبــت لــدي إدانــة‬\n     ‫املدعــى عليــه بحيــازة ‪ %50‬مــن اجلــرام بقصــد االســتعمال الشــخصي ولــم‬\n     ‫يثبــت لــدي ســوى ذلــك وقــررت مــا يلــي أوال ـ ـ اســتنادا ملــا جــاء يف املــادة‬\n     ‫الســتني مــن نظــام مكافحــة املخــدرات ونظــرا لعــدم وجــود ســوابق‬\n     ‫بحــق املدعــى عليــه ولقلــة الكميــة فقــد نزلــت عــن احلــد األدنــى لعقوبــة‬\n     ‫الســجن احملــددة يف املــادة الواحــد واألربعــن وحكمــت بســجنه ملــدة‬\n     ‫شــهر اعتبــارا مــن تاريــخ توقيفــه علــى ذمــة هــذه القضيــة ثانيــا ـ ـ إبعــاده‬\n     ‫عــن البــاد اســتنادا للمــادة ‪ 56‬مــن نظــام مكافحــة املخــدرات ثالثــا ـ ـ‬\n     ‫ســجنه ملــدة أربعــة اشــهر اعتبــارا مــن تاريــخ انتهــاء مــدة الســجن الســابقة‬\n     ‫املذكــورة يف أوال وجلــده تعزيــرا خمســن جلــدة دفعــة واحــدة وذلــك‬\n     ‫لقــاء توجــه الشــبهة إليــه بترويــج عشــرة جرامــات مــن مــادة احلشــيش‬\n     ‫عــن طريــق البيــع وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه‬\n     ‫االعتــراض علــى إبعــاده عــن البــاد بــدون الئحــة كمــا قــرر املدعــي‬\n     ‫العــام االعتــراض علــى احلكــم بالئحــة فأفهــم بإجــراءات االســتئناف‬\n     ‫وبــاهلل التوفيــق وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                  ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/05/04‬ه ـ‬\n     ‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد ‪ ...‬نحــن رئيــس‬\n     ‫وقضــاة الدائــرة اجلزائيــة الرابعــة يف محكمــة االســتئناف مبنطقة مكة‬\n\n\n‫‪93‬‬\n\f‫املكرمــة جــرى منــا االطــاع علــى القــرار رقــم ‪ 34204877‬وتاريــخ‬\n‫‪1434/5/4‬ه ـ الصــادر مــن فضيلــة الشــيخ‪ ........‬القاضــي باحملكمــة‬\n‫اجلزائيــة مبكــة املكرمــة ‪ ،‬املتضمــن دعــوى املدعــي العــام ضــد‪........‬‬\n‫مينــي اجلنســية‪ ،‬املتهــم يف مخــدرات ‪ ،‬احملكــوم فيــه مبــا دون باطنــه ‪.‬‬\n‫وبدراســة القــرار وصــورة ضبطــه والالئحــة االعتراضيــة تقــررت املوافقــة‬\n‫علــى احلكــم ‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                             ‫وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                               ‫‪94‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":87,"source_page_end":94,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"8713af8645c436a198e28db40f5c5b535650fd31c6f17119146c95784f74e5d5","normalized_text_hash":"b96725e0a3b3695c6a0bd5d46fbb481a1ab2698d4a57d029478734bb8956cb84","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p87-34204877"},{"id":"cf5cc3a2-8e8b-52d2-99c9-3954166ad1c2","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -شراء وحيازة احلشيش املخدر بقصد التعاطي -شراء سيجارة ممزوجة باحلشيش املخدر بقصد التعاطي -حيازة حبوب الترامادول احملظورة بقصد التعاطي -تعاطي احلشيش املخدر واحلبوب احملظورة -التستر على مصدر املخدرات -إشتراك احلشيش مع اخلمر يف مناط احلكم -إقامة حد املسكر -تعزير املدعى عليه بالسجن واإلبعاد عن الباد -النزول عن احلد األدنى يف عقوبة السجن لقلة الكمية -رد دعوى.","document_number":"34191446","case_number":"34165108","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف باملنطقة الشرقية","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/17","year":"1434","subject":"مخدرات -شراء وحيازة احلشيش املخدر بقصد التعاطي -شراء سيجارة ممزوجة باحلشيش املخدر بقصد التعاطي -حيازة حبوب الترامادول احملظورة بقصد التعاطي -تعاطي احلشيش املخدر واحلبوب احملظورة -التستر على مصدر املخدرات -إشتراك احلشيش مع اخلمر يف مناط احلكم -إقامة حد املسكر -تعزير املدعى عليه بالسجن واإلبعاد عن الباد -النزول عن احلد األدنى يف عقوبة السجن لقلة الكمية -رد دعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪ 34191446:‬تاريخه‪1434/4/17:‬هـ‬\n                       ‫رقم الدعوى‪34165108:‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 341072759‬تاريخه‪1434/05/22 :‬هـ‬\n\n\n     ‫مخــدرات ‪ -‬شــراء وحيــازة احلشــيش املخــدر بقصــد التعاطــي‪ -‬شــراء‬\n     ‫ســيجارة ممزوجــة باحلشــيش املخــدر بقصــد التعاطــي ‪ -‬حيــازة حبــوب‬\n     ‫الترامــادول احملظــورة بقصــد التعاطــي ‪ -‬تعاطــي احلشــيش املخــدر‬\n     ‫واحلبــوب احملظــورة ‪ -‬التســتر علــى مصــدر املخــدرات ‪ -‬إشــتراك‬\n     ‫احلشــيش مــع اخلمــر يف منــاط احلكــم ‪ -‬إقامــة حــد املســكر‪ -‬تعزيــر‬\n     ‫املدعــى عليــه بالســجن واإلبعــاد عــن البــاد ‪ -‬النــزول عــن احلــد األدنــى‬\n                                 ‫يف عقوبــة الســجن لقلــة الكميــة ‪ -‬رد دعــوى‪.‬‬\n\n\n\n\n                     ‫قول الرسول صلى اهلل عليه وسلم ( كل مسكر حرام )‬\n                      ‫املادة ‪ 60‬من نظام مكافحة املخدرات واملؤثرات العقلية‬\n     ‫الفقــرة الثانيــة مــن املــادة ‪ 56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                           ‫العقليــة‬\n\n\n\n     ‫الئحــة الدعــوى العامــة ضــد املدعــى عليــه مقيــم بشــراء وحيــازة احلشــيش‬\n     ‫املخــدر وســيجارة ممزوجــة باحلشــيش املخــدر وحيــازة خمــس حبــات‬\n     ‫مــن حبــوب الترامــادول احملظــور بقصــد التعاطــي‪ ،‬تعاطــي احلشــيش‬\n     ‫املخــدر واحلبــوب احملظــورة‪ ،‬تســتر املدعــى عليــه علــى مصــدر املخــدرات‬\n\n‫‪95‬‬\n\f‫‪ -‬وطلــب املدعــي العــام إثبــات مــا أســند إليــه واحلكــم عليــه بالعقوبــة‬\n‫الــواردة يف الفقــرة األولــى مــن املــادة (‪ )41‬مــن نظــام مكافحة املخدرات‬\n‫واملؤثــرات العقليــة وإبعــاده خــارج البــاد بعــد تنفيــذ احلكــم بحقــه‬\n‫وبعقوبــة تعزيريــة لقــاء تســتره علــى مصــدر املخــدرات‪ ،‬مت القبــض علــى‬\n‫املدعــى عليــه بعــد االشــتباه بــه وبتفتيشــه عثــر معــه علــى ســجائر محتويــة‬\n‫علــى احلشــيش املخــدر وقطعتــن مــن احلشــيش املخــدر‪ ،‬إقــرار املدعــى‬\n‫عليــه بشــراء وحيــازة احلشــيش املخــدر والســيجارة املمزوجــة باحلشــيش‬\n‫وحيــازة احلبــوب احملظــورة بقصــد التعاطــي وتعاطيــه للحشــيش واحلبــوب‬\n‫احملظــورة‪ ،‬إنــكاره التســتر علــى مصدر املخــدرات‪ ،‬ثبوت إدانة املدعى‬\n‫عليــه بشــراء وحيــازة احلشــيش املخــدر والســيجارة املمزوجــة باحلشــيش‬\n‫املخــدر وتعاطيــه للحشــيش واحلبــوب احملظــورة‪ ،‬احلكــم بإقامــة حــد‬\n‫املســكر‪ ،‬تعزيــر املدعــى عليــه بالســجن واإلبعــاد عــن البــاد والنــزول‬\n‫عــن العقوبــة املقــررة نظام ـ ًا بالســجن لقلــة الكميــة‪ ،‬رد الدعــوى عــن‬\n‫طلــب إثبــات إدانــة املدعــى عليــه بالتســتر لعــدم ثبوتهــا‪ ،‬تصديــق احلكــم‬\n                            ‫مــن محكمــة االســتئناف باملنطقــة الشــرقية ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .............‬القاضــي يف احملكمــة‬\n‫اجلزائيــة باالحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n                                                                           ‫ّ‬\n‫احملكمــة اجلزائيــة يف محافظــة االحســاء برقــم ‪ 34165108‬وتاريــخ‬\n‫‪1434/04/10‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34879320‬وتاريــخ‬\n‫‪1434/04/10‬ه ـ ففــي يــوم األربعــاء املوافــق‪ 1434/04/17‬ه ـ افتتحت‬\n‫اجللســة الســاعة ‪ 09 : 00‬ووفيهــا حضــر املدعــي العــام ‪ .............‬املعمــد‬\n\n                                                                                      ‫‪96‬‬\n\f     ‫بالترافــع أمــام هــذه احملكمــة مبوجــب خطــاب ســعادة رئيــس دائــرة‬\n     ‫التحقيق واالدعاء العام مبحافظة االحســاء ذي الرقم ‪ .............‬والتاريخ‬\n     ‫‪ 1433/12/01‬ه ـ وادعــى ضــد احلاضــر معــه‪ .............‬مصــري اجلنســية‬\n     ‫مبوجــب رخصــة اقامــة رقــم ‪.............‬أنــه بتاريــخ ‪1434/2/17‬ه ـ وأثنــاء‬\n     ‫قيــام الدوريــات األمنيــة بعملهــا علــى طريــق الدمــام الريــاض الســريع مت‬\n     ‫اســتيقاف ســيارة مــن نــوع ‪ .......‬صنــع عــام ( ‪.......‬م ) حتمــل اللوحــة رقــم‬\n     ‫(‪ ).............‬بقيــادة املدعــى عليــه ‪ ،‬وبطلــب إثباتــه اتضــح عليــه االرتبــاك‬\n     ‫الشــديد ‪ ،‬وبتفيــش املركبــة ضبــط يف الــدرج الــذي بــن املرتبتــن علــى‬\n     ‫ســيجارة يحتمــل أن تكــون ممزوجــة باحلشــيش املخــدر تــزن ( ‪1‬جــم )‬\n     ‫جــرام واحــد ‪ ،‬وقطعتــن يحتمــل أن تكونــا مــن احلشــيش املخــدر بلــغ‬\n     ‫وزنهمــا ( ‪ 3‬جــم ) ثالثــة جرامــات‪ ،‬وعــدد (‪ )5‬خمــس حبــات يحتمــل أن‬\n                                                   ‫تكــون مــن حبــوب الترامــادول‪.‬‬\n     ‫وباســتجوابه أقــر بصحــة واقعــة القبــض والضبــط وبشــرائه و حيازتــه‬\n     ‫للحشــيش املخــدر وحبــوب الترامــادول مــن شــخص اليعــرف اســمه‬\n                               ‫بقصــد التعاطــي وتعاطيــه لنوعهمــا يف الســابق‪.‬‬\n     ‫وقــد أثبــت التقريــر الكيمــاوي الشــرعي رقــم (‪957‬ك ش) لعام ‪1434‬هـ‬\n     ‫إيجابيــة عينــة القطعتــن املضبوطتــن والســجارة املضبوطــة للحشــيش‬\n     ‫املخــدر املــدرج يف اجلــدول(‪ )1‬فئــة (أ) مــن نظــام مكافحــة املخــدرات‬\n     ‫واملؤثــرات العقليــة ‪ ،‬كمــا أثبــت التقريــر إيجابيــة احلبــوب املضبوطــة‬\n     ‫لعقــار الترامــادول احملظــور واملــدرج يف اجلــدول (‪ )1‬فئــة (هــ) مــن نظــام‬\n                                        ‫مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n     ‫وانتهــى التحقيــق معــه إلــى توجيــه االتهــام ل ــه بشــراء وحيــازة قطعتــن‬\n     ‫مــن احلشــيش املخــدر بلــغ وزنهمــا (‪ )3‬ثالثــة جرامــات وســيجارة ممزوجــة‬\n\n\n‫‪97‬‬\n\f‫جرامــا واحـ ًـدا وحيــازة عــدد (‪ )5‬خمــس‬  ‫ً‬     ‫باحلشــيش املخــدر بلــغ وزنهــا (‪)1‬‬\n‫حبــات مــن حبــوب الترامــادول احملظــورة بقصــد التعاطــي وتعاطيــه‬\n‫لنوعهمــا يف الســابق‪ ،‬املجــرم مبوجــب املــادة ( الثالثــة) مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم‬\n        ‫(م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ وتســتره علــى مصــدر املخــدرات‪.‬‬\n                                                   ‫وذلك لألدلة والقرائن التالية ‪:‬‬\n‫‪ -1‬إقــراره املنــوه عنــه املــدون علــى الصفحــة رقــم ( ‪ )2،1‬مــن دفتــر‬\n                                                       ‫التحقيــق لفــة رقــم(‪.)........‬‬\n                          ‫‪ -2‬ماجاء يف محضر الضبط املرفق لفة رقم (‪.)4‬‬\n‫‪ -3‬التقريــر الكيمــاوي الشــرعي املنــوه عنــه ‪ ،‬واملرفــق علــى اللفــة رقــم‬\n                                                                               ‫(‪. )........‬‬\n‫وحيــث إن مــا أقــدم عليــه املذكــور ‪ ،‬وهــو بكامــل أهليتــه املعتبــرة‬\n‫شــرع ًا ‪ ،‬فعــل مجــرم ومعاقــب علي ــه نظامـ ًا ؛ لــذا أطلــب إثبــات مــا أســند‬\n                                                   ‫إليــه واحلكــم عليــه مبــا يلــي‪-:‬‬\n‫‪-1‬بالعقوبــة الــواردة يف الفقــرة األولــى مــن املــادة (‪ )41‬مــن النظــام املشــار‬\n        ‫إليــه لقــاء مــا أســند إليــه باســتثناء التســتر علــى مصــدر املخــدرات ‪.‬‬\n‫‪2‬ـ بالعقوبــة الــواردة يف الفقــرة الثانيــة مــن املــادة (‪ )56‬مــن النظــام بإبعــاده‬\n                                         ‫خــارج البــاد بعــد تنفيــذ احلكــم بحقــه ‪.‬‬\n                       ‫‪-3‬بعقوبة تعزيرية لقاء تستره على مصدر املخدرات‪.‬‬\n‫وبســؤال املدعــى عليــه أجــاب قائــا مــا ذكــره املدعــي العــام مــن أنــه‬\n‫بتاريخ‪1434/2/17‬ه ـ مت اســتيقاف ســيارتي نــوع ‪ ......‬علــى طريــق‬\n‫الدمــام الريــاض وأنــه مت تفتيشــها وأنــه عثــر فيهــا علــى ســيجارة‬\n‫حشــيش تــزن جــرام واحــد وكذلــك علــى قطعتــي حشــيش يبلــغ وزنهــا‬\n\n\n                                                                                              ‫‪98‬‬\n\f     ‫ثــاث جرامــات وأنــه عثــر كذلــك علــى عــدد خمــس حبــات مــن حبــوب‬\n     ‫الترامــادول احملظــورة فهــذا كلــه صحيــح وهــي تعــود لــي وقصــدي مــن‬\n     ‫حيازتهــا االســتعمال وأنــا أســتعملها وأمــا مــا ذكــره املدعــي العــام مــن‬\n     ‫أننــي تســترت علــى مصدرهــا فهــذا غيــر صحيــح حيــث إننــي أخبرتهــم‬\n     ‫أننــي أخــذت مــن شــخص يف الريــاض ال أعــرف اســمه هكــذا أجــاب‬\n     ‫وبســؤال املدعــي العــام هــل لديــه بينــه علــى أن املدعــى عليــه تســتر علــى‬\n     ‫مصــدر هــذه احلبــوب فأجــاب قائــا نعــم لــدي بينــه وهــي أن املدعــى‬\n     ‫عليــه عندمــا مت ســؤاله عــن مصدرهــا يف دفتــر التحقيــق أجــاب بأنــه ال‬\n     ‫يعرفــه هكــذا أجــاب كمــا جــرى االطــاع علــى التقريــر الكيمائــي‬\n     ‫الشــرعي رقــم ‪.............‬واملتضمــن إيجابيــة العينــات جميعهــا للحشــيش‬\n     ‫حلبــوب الترامــادول احملظــورة واســتهالك جميــع العينــات يف التحليــل أ‪.‬هـ‬\n     ‫فبنــاء علــى مــا تقــدم مــن الدعــوى واالجابــه وإقــرار املدعــى عليــه باحليــازه‬\n     ‫للحشــيش واحلبــوب احملظــورة بقصــد االســتعمال وإنــكاره للتستســر‬\n     ‫علــى مصدرهــا وحيــث إن املدعــي العــام ال بينــه لــه علــى تســتره وحيــث‬\n     ‫إن احلشــيش يشــترك مــع اخلمــر يف منــاط احلكــم وللتقريــر الكيمــاوي‬\n     ‫الشــرعي ولقــول صلــى اهلل عليــه وســلم كل مســكر حــرام للذلــك‬\n     ‫كلــه فقــد ثبــت لــدي إدانــه املدعــى عليــه بحيــازة عــدد خمــس حبــات‬\n     ‫محظــورة وســيجارة حشــيش تــزن جــرام واحــد وقطعتــي حشــيش تــزن‬\n     ‫ثالثــة جرامــات بقصــد االســتعمال ولــم يثبــت لــدي إدانتــه بالتســتر علــى‬\n     ‫مصــدر احلبــوب وحكمــت عليــه مبــا يلــي أوال‪ :‬جلــد املدعــى عليــه ثمانــن‬\n     ‫جلــدة دفعــة واحــدة حــد املســكر ثانيــا‪ :‬ســجن املدعــى عليــه مــدة أربعــة‬\n     ‫أشــهر يحتســب منهــا مــده بقائــه بالســجن بخصــوص هــذه القضيــة وقــد‬\n     ‫نزلــت عــن العقوبــة املقــرره نظامــا وذلــك مبوجــب املــادة ‪ 60‬مــن نظــام‬\n\n\n‫‪99‬‬\n\f‫مكافحــة املخــدرات واملؤثــرات العقليــة نظــرا لقلــة الكميه ثالثــا‪ :‬إبعاد‬\n‫املدعــى عليــه مــن البــاد بعــد تنفيــذ مــدة محكوميتــه وذلــك مبوجــب‬\n‫الفقــرة الثانيــة مــن املــادة ‪ 56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة رابعــا‪ :‬رد دعــوى املدعــي العــام بخصــوص معاقبــه املدعــى عليــه‬\n‫علــى التســتر لعــدم ثبوتهــا هــذا مــا ظهــر لــي وبــه حكمــت وبعــرض ذلــك‬\n‫علــى املدعــي العــام قــرر املدعــي العــام اعتراضــه عليــه وطلــب رفعــه إلــى‬\n‫محكمــة االســتئناف بــدون الئحــه فأجبتــه لطلبــه وأمــا املدعــى عليــه‬\n               ‫فقــرر قناعتــه بــه وبــه ختمــت اجللســة يف متــام الســاعة ‪09: 30‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n‫لــدى احملكمــة برقــم ‪/341072759‬ج‪ 2‬وتاريــخ ‪1434/5/1‬ه ـ الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة اجلزائية مبحافظة األحســاء املكلف برقم‬\n‫‪ 34/879320‬وتاريــخ ‪1434/4/28‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشيخ‪.............‬املســجل برقــم ‪34191446‬‬\n‫وتاريــخ ‪1434/4/17‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد‪.............‬‬\n‫(مصــري اجلنســية) يف قضيــة مخــدرات وقــد تضمــن القــرار حكــم‬\n‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه‬\n‫وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم‪ .‬واهلل املوفــق وصلــى اهلل‬\n           ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/5/7‬هــ‪.‬‬\n\n\n\n\n                                                                                         ‫‪100‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":95,"source_page_end":100,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"a5fe3af12bb760346b00e617839d4b5cfd55efce027d2bf9c2d530574768b816","normalized_text_hash":"577d3f5408ea8bd688c5bd02d132478dd887fc6c5af44f68a2e9b8be4f829848","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p95-34191446"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
